const ruForm=(n,f)=>{n=Math.abs(Number(String(n).replace(/[^\d]/g,''))||0)%100;const d=n%10;return n>10&&n<20?f[2]:d===1?f[0]:d>1&&d<5?f[1]:f[2]};
