function habitRingMarkup(compact=false){
 const habit=state.writingHabit||{},target=Math.max(1,Number(habit.target)||1500),value=dailyTotal(dateLocal()),pct=Math.max(0,Math.round(100*value/target)),shown=Math.min(100,pct);
 const stage=pct>=100?'done':pct>=70?'near':value>0?'writing':'start';
 const messages=STORY_REPLIES[stage];const stamp=dateLocal()+':'+stage+':'+(book()?.id||'');
 let hash=0;for(const c of stamp)hash=(hash*31+c.charCodeAt(0))>>>0;
 const msg=messages[hash%messages.length],color=stage==='done'?'#65b88a':stage==='near'?'#e6b756':'#d87579';
 return `<div class="habit-ring-host daily-progress-widget ${compact?'is-compact':''}" data-habit-ring data-compact="${compact?'1':'0'}" title="Дневная норма: ${fmtNum(value)} из ${fmtNum(target)} ${ncUnitGen(habit.unit)}">
 <span class="habit-circle" style="--habit-color:${color};--habit-angle:${shown*3.6}deg"><b>${pct}%</b></span><span class="habit-ring-copy"><strong>✧ ${esc(msg)}</strong><small>${fmtNum(value)} / ${fmtNum(target)} ${ncUnitGen(habit.unit)} · <span>дневной ритм</span></small></span></div>`;
}
