function daysTo(date){if(!date)return null;const start=new Date(dateLocal()+'T12:00:00'),end=new Date(date+'T12:00:00');return Math.max(1,Math.floor((end-start)/86400000)+1)}
function goalStats(b){const g=b.goal||{},unit=g.unit||'characters',current=totalOf(b,unit),target=Number(g.target)||0,left=Math.max(0,target-current),days=daysTo(g.deadline),daily=days?Math.ceil(left/days):null;return {g,unit,current,target,left,days,daily,pct:target?Math.min(100,Math.round(100*current/target)):0}}
