function snapshot(){let temporary=new Set(state.musicTracks.filter(t=>t.kind==='session').map(t=>t.id));return {...state,musicTracks:state.musicTracks.filter(t=>t.kind!=='session'),musicPlaylists:state.musicPlaylists.map(p=>({...p,trackIds:(p.trackIds||[]).filter(id=>!temporary.has(id))}))}}const remoteKey=window.__NOCTURNE_BOOT?.key||'';
let serverRevision=window.__NOCTURNE_BOOT?.revision||0, pending=false, saving=false, failed=false, saveTimer=null;
// RC2: сохраняем после паузы в 450 мс, но не даём непрерывному набору
// откладывать первое сохранение дольше 10 секунд. Таймер сбрасывается
// только после успешного начала очередной отправки, а не при каждом символе.
const SAVE_IDLE_MS=450, SAVE_MAX_DIRTY_MS=10000;
let firstUnsentEditAt=0;
function saveLabel(t){let x=document.querySelector('#saveStatus');if(x)x.textContent=t;let w=document.querySelector('#writerSaved');if(w)w.textContent=t}
function persist(){
  if(failed){saveLabel('⚠ ОШИБКА — сделай копию JSON!');return false}
  if(!pending)firstUnsentEditAt=Date.now();
  pending=true;saveLabel('◌ Сохраняется на Mac…');clearTimeout(saveTimer);
  const timeLeft=Math.max(0,SAVE_MAX_DIRTY_MS-(Date.now()-firstUnsentEditAt));
  saveTimer=setTimeout(flushSave,Math.min(SAVE_IDLE_MS,timeLeft));return true;
}
async function flushSave(){
  clearTimeout(saveTimer);
  if(saving||!pending||failed)return;
  saving=true;pending=false;firstUnsentEditAt=0;
  const packed=JSON.stringify({state:snapshot(),baseRevision:serverRevision});
  try{
    const response=await fetch('/api/save',{method:'POST',headers:{'Content-Type':'application/json','X-Nocturne-Key':remoteKey},body:packed});
    const result=await response.json();
    if(!response.ok)throw new Error(result.error||('HTTP '+response.status));
    serverRevision=result.revision;
    saveLabel(pending?'◌ Сохраняется на Mac…':'● Сохранено на Mac');
  }catch(e){
    pending=true;failed=true;saveLabel('⚠ НЕ СОХРАНЕНО — экспортируй JSON!');
    notify('Ошибка сохранения: '+e.message+'. Экспортируй JSON и не закрывай окно.');
  }finally{saving=false;if(pending&&!failed){saveTimer=setTimeout(flushSave,40)}}
}
async function waitSaved(){
  for(let i=0;i<240;i++){
    if(failed)throw new Error('Сохранение не удалось. Экспортируй JSON через «⇩ JSON».');
    if(pending&&!saving)await flushSave();
    if(!saving&&!pending)return;
    await new Promise(r=>setTimeout(r,50));
  }
  throw new Error('Сохранение выполняется слишком долго');
}
