document.querySelector('#themeImportFile').addEventListener('change',e=>{themeImport(e.target.files?.[0]);e.target.value=''});document.querySelector('#editorImageFile').addEventListener('change',e=>{importEditorImage(e.target.files?.[0]);e.target.value=''});document.querySelector('#restoreFile').addEventListener('change',e=>{restore(e.target.files?.[0]);e.target.value=''});document.querySelector('#localMusicFiles').addEventListener('change',e=>{importMusicFiles(e.target.files);e.target.value=''});document.querySelector('#musicProgress').addEventListener('input',e=>{let a=document.querySelector('#studioAudio');if(Number.isFinite(a.duration)&&a.duration>0)a.currentTime=Number(e.target.value)/1000*a.duration});let studioAudio=document.querySelector('#studioAudio');studioAudio.volume=Math.min(1,Number.isFinite(Number(state.musicVolume))?Number(state.musicVolume):1);studioAudio.addEventListener('play',renderMusicDock);studioAudio.addEventListener('pause',renderMusicDock);studioAudio.addEventListener('ended',()=>stepTrack(1));studioAudio.addEventListener('timeupdate',()=>{document.querySelector('#musicTime').textContent=fmtTime(studioAudio.currentTime)+(Number.isFinite(studioAudio.duration)?' / '+fmtTime(studioAudio.duration):'');document.querySelector('#musicProgress').value=Number.isFinite(studioAudio.duration)&&studioAudio.duration>0?Math.round(studioAudio.currentTime/studioAudio.duration*1000):0});studioAudio.addEventListener('error',()=>{if(musicRuntime.trackId)notify('Проблема с аудио. Проверь формат или ссылку.')});
