// Copy exactly what the author selected, never the invisible layout spacers.
document.addEventListener('copy',e=>{
 const sel=window.getSelection();const el=document.querySelector('[data-prose-flow]');
 if(!el||!sel?.rangeCount||sel.isCollapsed||!el.contains(sel.getRangeAt(0).commonAncestorContainer))return;
 const wrapper=document.createElement('div');wrapper.append(sel.getRangeAt(0).cloneContents());
 wrapper.querySelectorAll('[data-flow-divider]').forEach(n=>n.remove());
 if(e.clipboardData){e.clipboardData.setData('text/plain',editorPlainText(wrapper));e.clipboardData.setData('text/html',safeRichMarkup(wrapper.innerHTML));e.preventDefault()}
});
