document.addEventListener('paste',e=>{
 const el=e.target.closest?.('[data-chapter-document],[data-prose-flow],[data-prose-page]');if(!el)return;
 const imageItem=Array.from(e.clipboardData?.items||[]).find(item=>item.kind==='file'&&item.type.startsWith('image/'));
 if(imageItem){e.preventDefault();rememberRichSelection();captureImageInsertion();importEditorImage(imageItem.getAsFile());return}
 e.preventDefault();let text=e.clipboardData?.getData('text/plain')||'';document.execCommand('insertText',false,text);
});
document.addEventListener('keydown',e=>{if(ui.tab==='canvas'&&e.key.toLowerCase()==='l'&&!e.metaKey&&!e.ctrlKey&&!e.altKey&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)){ui.canvasLinkMode=!ui.canvasLinkMode;ui.canvasLinkFrom=null;render();return}ritualTyping(e);if(e.key==='Escape'&&ui.clean){ritualClean(false);return}if(e.key==='Escape'){if(document.querySelector('#nocturneImageViewer').classList.contains('open')){closePicture();return}closeModal()}if(document.querySelector('#nocturneImageViewer').classList.contains('open')){if(e.key==='ArrowLeft')stepPicture(-1);if(e.key==='ArrowRight')stepPicture(1)}if((e.metaKey||e.ctrlKey)&&e.key==='Enter'&&e.target.matches('[data-prose-page],[data-prose-flow]')){e.preventDefault();if(e.target.hasAttribute('data-prose-flow')){document.execCommand('insertHTML',false,'<br><br>');saveFlowEditor(e.target)}else addPage();return}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'){e.preventDefault();persist();notify('Сохранение отправлено в папку NOCTURNE. Для полного архива нажми «Архив».')}});
async function quitNocturne(){
 try{
   await waitSaved();
   const r=await fetch('/api/quit',{method:'POST',headers:{'X-Nocturne-Key':remoteKey}});
   if(!r.ok)throw new Error('Не удалось завершить приложение');
   document.body.innerHTML='<div style="min-height:85vh;display:grid;place-items:center;background:#16120f;color:#f0dcc0;font:22px Georgia;text-align:center;padding:30px"><div>☾<h1 style="font:calc(36px * var(--nc-fs,1) * var(--nc-hs,1)) var(--nc-head,Georgia);margin:18px 0">NOCTURNE</h1><p>Все изменения сохранены на Mac в выбранной папке NOCTURNE.</p><p style="font-size:15px;opacity:.7">Можно закрыть эту вкладку.</p></div></div>';
 }catch(e){notify('Не удалось безопасно закрыть NOCTURNE: '+e.message)}
}
