document.querySelector('#app').addEventListener('drop',e=>{const note=e.target.closest('[data-note-drag]');if(!note||!ui.noteDrag)return;e.preventDefault();const a=book()?.notesCards||[],i=a.findIndex(x=>x.id===ui.noteDrag),j=a.findIndex(x=>x.id===note.dataset.noteDrag);if(i>=0&&j>=0&&i!==j){const [item]=a.splice(i,1);a.splice(j,0,item);persist();render()}ui.noteDrag=null});
document.querySelector('#app').addEventListener('dragend',e=>{if(e.target.closest('[data-note-drag]'))ui.noteDrag=null});
document.querySelector('#app').addEventListener('pointerdown',canvasPointerDown);document.addEventListener('pointerup',canvasPointerRelease);document.querySelector('#app').addEventListener('dblclick',e=>{let card=e.target.closest('[data-canvas-item]');if(card){ui.canvasSelected=card.dataset.canvasItem;canvasEditCard()}});document.querySelector('#app').addEventListener('pointerdown',mapMoveNode);document.querySelector('#app').addEventListener('dragstart',e=>{let x=e.target.closest('[data-scene]');if(!x)return;ui.drag=x.dataset.scene;x.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',ui.drag)});
document.querySelector('#app').addEventListener('dragover',e=>{const x=e.target.closest('[data-scene],[data-drop-chapter]');if(!x||!ui.drag)return;e.preventDefault();x.classList.add('over')});
document.querySelector('#app').addEventListener('dragleave',e=>{e.target.closest('[data-scene],[data-drop-chapter]')?.classList.remove('over')});
document.querySelector('#app').addEventListener('drop',e=>{const x=e.target.closest('[data-scene],[data-drop-chapter]');if(!x||!ui.drag)return;e.preventDefault();const b=book(),arr=b.scenes,i=arr.findIndex(s=>s.id===ui.drag);if(i<0)return;
 const targetScene=x.dataset.scene?arr.find(s=>s.id===x.dataset.scene):null;
 const targetChapter=targetScene?.chapterId||x.dataset.dropChapter;
 const chapter=b.chapters.find(c=>c.id===targetChapter);if(chapter){arr[i].chapterId=chapter.id;arr[i].chapter=chapter.title;}
 const moved=arr.splice(i,1)[0];const j=targetScene?arr.findIndex(s=>s.id===targetScene.id):-1;
 if(j>=0)arr.splice(j,0,moved);else arr.push(moved);
 realignScenes(b);ui.drag=null;persist();render();});
document.querySelector('#app').addEventListener('dragend',()=>{ui.drag=null;document.querySelectorAll('.dragging,.over').forEach(x=>x.classList.remove('dragging','over'))});

// Widget drag uses only explicitly draggable handles, not the manuscript or card bodies.
const widgetDrag={id:null,bookId:null};
function widgetDragReset(){
 widgetDrag.id=null;widgetDrag.bookId=null;
 document.querySelectorAll('.widget-dragging,.widget-drop-before,.widget-drop-after').forEach(el=>el.classList.remove('widget-dragging','widget-drop-before','widget-drop-after'));
}
function widgetDragLocation(event){
 const card=event.target.closest('[data-widget-stack] > [data-widget-active]');
 const stack=card?.closest('[data-widget-stack]');
 if(!card||!stack)return null;
 if(stack.dataset.widgetStack==='desk'&&!ui.widgetArrange)return null;
 return {card,stack,source:widgetDrag.id,target:card.dataset.widgetActive};
}
const widgetRoot=document.querySelector('#app');
widgetRoot.addEventListener('dragstart',event=>{
 const handle=event.target.closest('[data-widget-grip]');
 const stack=handle?.closest('[data-widget-stack]');
 const source=handle?.dataset.widgetGrip,b=book();
 if(!handle||!stack||!b||!b.widgetLayout?.includes(source)||stack.dataset.widgetStack==='desk'&&!ui.widgetArrange)return;
 widgetDrag.id=source;widgetDrag.bookId=b.id;
 const card=handle.closest('[data-widget-active]');card?.classList.add('widget-dragging');
 event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain','NOCTURNE-widget:'+source);
});
widgetRoot.addEventListener('dragover',event=>{
 if(!widgetDrag.id||widgetDrag.bookId!==book()?.id)return;
 const info=widgetDragLocation(event);if(!info||info.source===info.target)return;
 event.preventDefault();event.dataTransfer.dropEffect='move';
 document.querySelectorAll('.widget-drop-before,.widget-drop-after').forEach(n=>n.classList.remove('widget-drop-before','widget-drop-after'));
 const rect=info.card.getBoundingClientRect();
 info.card.classList.add(event.clientY>rect.top+rect.height/2?'widget-drop-after':'widget-drop-before');
});
widgetRoot.addEventListener('drop',event=>{
 if(!widgetDrag.id||widgetDrag.bookId!==book()?.id)return;
 const info=widgetDragLocation(event);
 if(!info||info.source===info.target){widgetDragReset();return;}
 event.preventDefault();
 const rect=info.card.getBoundingClientRect();
 const after=event.clientY>rect.top+rect.height/2;
 const id=info.source,target=info.target;
 widgetDragReset();widgetApplyMove(id,target,after);
});
widgetRoot.addEventListener('dragend',widgetDragReset);
// Keyboard access to the grip: arrows move the focused widget when arranging.
widgetRoot.addEventListener('keydown',event=>{
 const grip=event.target.closest('[data-widget-grip]');
 if(!grip||!['ArrowUp','ArrowDown'].includes(event.key))return;
 event.preventDefault();
 const arr=book()?.widgetLayout||[],idx=arr.indexOf(grip.dataset.widgetGrip),dir=event.key==='ArrowUp'?-1:1;
 const dest=arr[idx+dir];if(dest)widgetApplyMove(grip.dataset.widgetGrip,dest,dir>0);
});

ui.scope=state.activeWorldId?'world':'book';state.theme=state.libraryTheme||'amber';if(!window.__NOCTURNE_BOOT?.state)persist();try{render()}catch(e){console.error('NOCTURNE: первая отрисовка',e);window.__ncFirstRenderFailed=true}if(!state.profile?.askedAt)setTimeout(profileWelcome,700);
/* Desktop edition 0.9.12: the author must ALWAYS have a visible way to leave focus.
   Browser fullscreen is optional and can be declined by Safari or permissions. */
function exitWriterZen(){
 if(!ui.writerZen && !document.fullscreenElement)return;
 const editor=document.querySelector('[data-chapter-document]');if(editor)chapterSave(editor);
 ui.writerZen=false;document.body.classList.remove('writer-zen');
 if(document.fullscreenElement && document.exitFullscreen){document.exitFullscreen().catch(()=>{});}
 render();
}
function toggleWriterZen(){
 if(ui.writerZen){exitWriterZen();return;}
 const editor=document.querySelector('[data-chapter-document]');if(editor)chapterSave(editor);
 ui.writerZen=true;document.body.classList.add('writer-zen');render();
 // requestFullscreen must be initiated from a real click, not on startup.
 try{if(window.__NOCTURNE_NATIVE?.platform!=='mac'&&!document.fullscreenElement && document.documentElement.requestFullscreen){
  const attempt=document.documentElement.requestFullscreen();if(attempt?.catch)attempt.catch(()=>{});
 }}catch(e){}
}
let writerFullscreenWasEntered=false;
document.addEventListener('fullscreenchange',()=>{
 // Ignore a denied fullscreen request. Only a real fullscreen session can trigger this exit.
 if(document.fullscreenElement){writerFullscreenWasEntered=true;return;}
 if(writerFullscreenWasEntered && ui.writerZen){writerFullscreenWasEntered=false;
  const ed=document.querySelector('[data-chapter-document]');if(ed)chapterSave(ed);
  ui.writerZen=false;document.body.classList.remove('writer-zen');render();
 }
});
document.addEventListener('keydown',e=>{
 if(e.key==='Escape'&&ui.writerZen){e.preventDefault();exitWriterZen()}
},true);
document.addEventListener('click',e=>{
 if(e.target.closest('[data-zen-exit]')){e.preventDefault();exitWriterZen();}
},true);

document.addEventListener('click',e=>{if(e.target.closest('[data-life-letter-open],[data-act="life-refresh-echo"],[data-act="life-toggle-finish"]')){e.stopImmediatePropagation();lifeAction(e)}},true);
document.addEventListener('change',e=>{if(e.target.matches('[data-life-chapter],[data-life-setting]')){e.stopImmediatePropagation();lifeAction(e)}},true);

// RC3.2: navigation is intentionally simple: groups collapse, individual
// destinations stay visible. The experimental hide-by-checkbox panel is removed.
document.addEventListener('click',e=>{
 const worldToggle=e.target.closest('#worldNavCollapse');
 if(worldToggle){e.preventDefault();e.stopImmediatePropagation();const s=readNocturneNav();s.worldsCollapsed=!s.worldsCollapsed;saveNocturneNav(s);const list=document.querySelector('#worldNav');if(list)list.hidden=s.worldsCollapsed;worldToggle.setAttribute('aria-expanded',String(!s.worldsCollapsed));const caret=worldToggle.querySelector('.worlds-caret');if(caret)caret.textContent=s.worldsCollapsed?'▸':'▾';return;}
 const summary=e.target.closest('.nav-section > summary');
 if(summary){e.preventDefault();e.stopImmediatePropagation();const detail=summary.parentElement,i=Number(detail.dataset.navSection),s=readNocturneNav();detail.open=!detail.open;s.collapsed=s.collapsed.filter(x=>x!==i);if(!detail.open)s.collapsed.push(i);saveNocturneNav(s);return;}
},true);


/* ============================================================================
   NOCTURNE RC3.8 — правки по замечаниям автора (2 ноября 2026).
   Свои окна ввода вместо системных, план и таймер как виджеты, плеер и
   выбор виджетов в фокусе, клавиши мультимедиа, громкость, поиск ⌘F,
   вкладки разделов, отметка «где остановилась», синхронная прокрутка
   в «Редакциях», значок загрузки.
   ========================================================================== */

/* ——— Свои окна ввода. В окне Mac системное окно поверх режима фокуса
       оставляло чёрный экран; своё окно живёт внутри страницы. ——— */
function ncAsk(opts){
 opts=typeof opts==='string'?{label:opts}:(opts||{});
 return new Promise(resolve=>{
  document.querySelector('#ncAskVeil')?.remove();
  const veil=document.createElement('div');veil.id='ncAskVeil';veil.className='nc-ask-veil';
  const multi=!!opts.multiline,ro=!!opts.readonly;
  const choices=Array.isArray(opts.choices)?opts.choices:null;
  const choiceHtml=choices?`${opts.choicesTitle?`<div class="nc-ask-sub">${esc(opts.choicesTitle)}</div>`:''}<div class="nc-ask-choices" role="radiogroup">${choices.map(c=>`<label class="nc-radio"><input type="radio" name="ncAskChoice" value="${esc(c.value)}" ${c.value===opts.choice?'checked':''}><span><b>${esc(c.label)}</b>${c.hint?`<small>${esc(c.hint)}</small>`:''}</span></label>`).join('')}</div>`:'';
  veil.innerHTML=`<form class="nc-ask" role="dialog" aria-modal="true" aria-labelledby="ncAskTitle"><h3 id="ncAskTitle">${esc(opts.title||'NOCTURNE')}</h3>${choiceHtml}${opts.label?`<label for="ncAskInput" id="ncAskLabel">${esc(opts.label)}</label>`:''}${opts.confirm?'<input id="ncAskInput" type="hidden">':multi?`<textarea id="ncAskInput" rows="${Number(opts.rows)||5}" ${ro?'readonly':''} spellcheck="true"></textarea>`:`<input id="ncAskInput" type="text" ${opts.numeric?'inputmode="numeric"':''} autocomplete="off" spellcheck="true">`}${opts.hint?`<p class="mini-help">${esc(opts.hint)}</p>`:''}<div class="nc-ask-foot">${ro?'':'<button type="button" class="btn plain" data-nc-ask="cancel">Отмена</button>'}<button type="submit" class="btn gold">${esc(opts.okText||(ro?'Готово':'Сохранить'))}</button></div></form>`;
  document.body.append(veil);
  const input=veil.querySelector('#ncAskInput');input.value=opts.value==null?'':String(opts.value);
  const prev=document.activeElement;let done=false;
  const picked=()=>veil.querySelector('input[name="ncAskChoice"]:checked')?.value??opts.choice;
  if(choices)veil.addEventListener('change',e=>{if(e.target.name==='ncAskChoice'&&typeof opts.onChoice==='function'){try{opts.onChoice(e.target.value,input,veil.querySelector('#ncAskLabel'))}catch(err){}}});
  const finish=v=>{if(done)return;done=true;window.removeEventListener('keydown',onKey,true);const ch=choices?picked():null;veil.remove();try{if(prev&&prev.isConnected&&prev!==document.body&&prev.focus)prev.focus({preventScroll:true})}catch(e){}resolve(choices&&v!==null?{value:v,choice:ch}:v)};
  const onKey=e=>{
   if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();finish(ro?input.value:null);return}
   if(e.key==='Enter'&&multi&&(e.metaKey||e.ctrlKey)){e.preventDefault();e.stopImmediatePropagation();finish(input.value)}
  };
  window.addEventListener('keydown',onKey,true);
  veil.querySelector('form').addEventListener('submit',e=>{e.preventDefault();e.stopPropagation();finish(input.value)});
  veil.addEventListener('click',e=>{if(e.target.closest('[data-nc-ask="cancel"]')){e.preventDefault();finish(null)}});
  setTimeout(()=>{try{if(opts.confirm){veil.querySelector('button[type=submit]')?.focus();return}input.focus();if(!multi||ro)input.select()}catch(e){}},30);
 });
}
function ncPrompt(label,value,opts){return ncAsk({...(opts||{}),label,value})}
async function ncHabitAdjust(){
 state.writingHabit??={target:1500,unit:'characters'};const old=state.writingHabit;
 const u0=ncHabitUnit();let cur=u0;
 const r=await ncAsk({title:'Дневная норма',choicesTitle:'Как считать',choices:ncUnitList(),choice:u0,label:ncNormLabel(u0),value:old.target||1500,numeric:true,
  hint:'Круг дневной нормы заполняется, пока ты пишешь. Так же считаются календарь, итоги месяца и счётчик на «Письменном столе». Поменять можно в любой момент.',
  onChoice:(v,input,label)=>{const n=Number(String(input.value).replace(/\s/g,'').replace(',','.'))||Number(old.target)||1500;input.value=ncConvertNorm(n,cur,v);cur=v;if(label)label.textContent=ncNormLabel(v)}});
 if(r===null)return;const n=Math.round(Number(String(r.value).replace(/\s/g,'').replace(',','.')));
 if(!(n>=1)){notify('Норма — это число больше нуля');return}
 old.target=n;old.unit=ncUnitOk(r.choice)?r.choice:u0;try{lifeHistoryRevision++}catch(e){}persist();render();notify('Дневная норма: '+fmtNum(n)+' '+ncUnitWord(old.unit,n));
}

/* ——— Журнал ошибок страницы: пишется в music-debug.log рядом с библиотекой.
       Помогает понять редкие сбои вроде «чёрного экрана». ——— */
(function(){
 const N=window.__NOCTURNE_NATIVE;if(!N)return;let sent=0;
 const key=()=>(window.__NOCTURNE_BOOT&&window.__NOCTURNE_BOOT.key)||(typeof remoteKey!=='undefined'?remoteKey:'')||'';
 const send=t=>{if(sent++>40)return;try{fetch('/api/native/log',{method:'POST',headers:{'X-Nocturne-Key':key()},body:String(t).slice(0,1800)}).catch(()=>{})}catch(e){}};
 window.__ncLog=send;
 window.addEventListener('error',e=>{if(e.target&&e.target!==window)return;send('js error: '+(e.message||'')+' @'+String(e.filename||'').split('/').pop()+':'+e.lineno+':'+e.colno+(e.error&&e.error.stack?' | '+String(e.error.stack).split('\n').slice(0,4).join(' | '):''))});
 window.addEventListener('unhandledrejection',e=>{const r=e.reason;send('promise: '+(r&&(r.stack||r.message)||r))});
 setTimeout(()=>send('ui RC3.8 caps: highlights='+!!(window.CSS&&CSS.highlights)+' mediaSession='+('mediaSession' in navigator)+' fullscreen='+!!document.fullscreenEnabled),6000);
})();

/* ——— Значок «подожди, идёт работа». Вращение рисует видеокарта, поэтому
       он крутится, даже пока страница считает. ——— */
function ncBusyShow(label){let el=document.querySelector('#ncBusy');if(!el){el=document.createElement('div');el.id='ncBusy';el.className='nc-busy';el.setAttribute('role','status');el.innerHTML='<i aria-hidden="true"></i><span></span>';document.body.append(el)}el.querySelector('span').textContent=label||'Минутку…';el.classList.add('on')}
function ncBusyHide(){document.querySelector('#ncBusy')?.classList.remove('on')}
function ncBusyRun(show,label,fn){
 if(!show){return fn()}
 ncBusyShow(label);
 requestAnimationFrame(()=>setTimeout(()=>{try{fn()}catch(e){console.error(e);window.__ncLog?.('busy task: '+(e&&e.stack||e))}finally{ncBusyHide()}},16));
}
function ncBookChars(b){b=b||book();if(!b)return 0;let n=0;for(const c of b.chapters||[])n+=String(c.plain||'').length;return n}

/* ——— Вкладки: последние открытые разделы над страницей, как в браузере.
       Переход возвращает и место прокрутки. ——— */
var NC_TABS_KEY='nocturne.tabs.v1';
var ncTabs=[];try{ncTabs=(JSON.parse(localStorage.getItem(NC_TABS_KEY)||'[]')||[]).filter(x=>typeof x==='string').slice(0,7)}catch(e){ncTabs=[]}
var ncTabScroll={};
var NC_TAB_NAMES={library:['Библиотека','⌂'],world:['Вселенная','◎'],atmosphere:['Атмосфера книги','✧'],outline:['План глав','▤'],desk:['Письменный стол','✒'],textlab:['Редакции','☷'],reader:['Читать рукопись','☷'],bookdocs:['Документы книги','▣'],notes:['Карточки','▦'],characters:['Персонажи','♙'],lore:['Лор','♜'],map:['Карта чувств','⌘'],roles:['Древо статусов','♧'],timeline:['Нити времени','◷'],threads:['Линии и тайны','◇'],moodboard:['Вдохновение','✧'],canvas:['Холст','▧'],ideas:['Шкатулка идей','✦'],music:['Музыка','♫'],rhythm:['Ритм письма','◫'],life:['Жизнь книги','✦'],widgets:['Виджеты','▤'],themeatelier:['Ателье оформления','✦'],settings:['Настройки','⚙']};
function ncTabInfo(id){const n=NC_TAB_NAMES[id];if(n)return {label:n[0],icon:n[1]};const d=document.querySelector(`.sidebar [data-tab="${CSS.escape(id)}"]`);return {label:(d?.textContent||id).trim(),icon:'•'}}
function ncTabsSave(){try{localStorage.setItem(NC_TABS_KEY,JSON.stringify(ncTabs))}catch(e){}}
function ncTabsNote(id){if(!id)return;if(!ncTabs.includes(id)){ncTabs.push(id);while(ncTabs.length>7){const drop=ncTabs.findIndex(x=>x!==id);ncTabs.splice(drop,1)}ncTabsSave()}}
function ncTabsDraw(){
 const top=document.querySelector('.topbar');if(!top)return;let bar=document.querySelector('#ncTabs');
 if(!bar){bar=document.createElement('nav');bar.id='ncTabs';bar.className='nc-tabs';bar.setAttribute('aria-label','Открытые разделы');top.after(bar)}
 ncTabsNote(ui.tab);
 const list=ncTabs.filter(id=>id==='library'||id==='settings'||id==='music'||id==='rhythm'||id==='ideas'||id==='themeatelier'||id==='world'||book());
 bar.hidden=list.length<2;
 bar.style.top=(top.offsetHeight||74)+'px';
 bar.innerHTML=list.map((id,i)=>{const t=ncTabInfo(id),on=id===ui.tab;return `<div class="nc-tab ${on?'on':''}"><button type="button" class="nc-tab-go" data-nc-tab="${esc(id)}" ${on?'aria-current="page"':''} title="${esc(t.label)}${i<9?' · ⌃'+(i+1):''}"><span aria-hidden="true">${t.icon}</span>${esc(t.label)}</button><button type="button" class="nc-tab-x" data-nc-tab-close="${esc(id)}" aria-label="Закрыть вкладку ${esc(t.label)}" title="Закрыть вкладку">×</button></div>`}).join('');
}
function ncTabGo(id){if(!id||id===ui.tab)return;ncTabScroll[ui.tab]=window.scrollY;setTab(id);const y=ncTabScroll[id];if(y)requestAnimationFrame(()=>requestAnimationFrame(()=>window.scrollTo(0,y)))}
document.addEventListener('click',e=>{
 const go=e.target.closest('[data-nc-tab]');if(go){e.preventDefault();e.stopPropagation();ncTabGo(go.dataset.ncTab);return}
 const x=e.target.closest('[data-nc-tab-close]');if(x){e.preventDefault();e.stopPropagation();const id=x.dataset.ncTabClose,i=ncTabs.indexOf(id);if(i<0)return;ncTabs.splice(i,1);ncTabsSave();if(id===ui.tab){const next=ncTabs[Math.max(0,i-1)];if(next){ncTabGo(next);return}ncTabs.push(id)}ncTabsDraw()}
},true);
document.addEventListener('keydown',e=>{
 if(!e.ctrlKey||e.metaKey||e.altKey)return;
 if(e.key==='Tab'){const list=ncTabs.filter(id=>id!=='x');if(list.length<2)return;e.preventDefault();const i=list.indexOf(ui.tab),n=list[(i+(e.shiftKey?-1:1)+list.length)%list.length];ncTabGo(n);return}
 const d=/^Digit([1-9])$/.exec(e.code||'');if(d&&!e.shiftKey&&!isTyping(e)){const id=ncTabs[Number(d[1])-1];if(id){e.preventDefault();ncTabGo(id)}}
},true);
function isTyping(e){const t=e.target;return !!(t&&(t.isContentEditable||/^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName)))}
window.addEventListener('resize',()=>{const bar=document.querySelector('#ncTabs'),top=document.querySelector('.topbar');if(bar&&top)bar.style.top=(top.offsetHeight||74)+'px'});

/* setTab: тяжёлые разделы открываются со значком загрузки, вкладки запоминают прокрутку. */
function setTab(tab){
 if(tab!==ui.tab)ncTabScroll[ui.tab]=window.scrollY;
 const heavy=['reader','desk','textlab','outline'].includes(tab)&&tab!==ui.tab&&ncBookChars()>120000;
 const label=tab==='reader'?'Открываю рукопись…':tab==='desk'?'Раскладываю страницы…':'Открываю…';
 return ncBusyRun(heavy,label,()=>ncSetTabNow(tab));
}

/* ——— После каждой отрисовки ——— */
function ncAfterRender(){
 if(!ncReady)return;
 ncTabsDraw();
 if(ui.tab==='textlab')ncLabAfterRender();
 if(ui.tab==='desk')requestAnimationFrame(ncStopPaint);
 if(ncFind.open)ncFindRefresh(true);
 try{ncDockState()}catch(e){}
 try{ncDiagAfterRender()}catch(e){}
 try{ncApplyFonts();if(ui.tab==='themeatelier'){ncFontFaces(ncFontCatalog().map(x=>x.id));ncUserFontsRegister()}}catch(e){}
 try{ncWinChrome()}catch(e){}
 try{ncLibAfterRender()}catch(e){}
 try{ncDeskBarSchedule()}catch(e){}
 try{ncZenPlace(true)}catch(e){console.error(e)}
 ncMusicSync();
}

/* ——— Виджеты: план главы и таймер — тоже виджеты; любой можно свернуть;
       в фокусе виджеты добавляются и убираются кнопкой «＋ Виджеты». ——— */
function ncWidgetsMigrate(b){
 if(!b||b.ncWidgets38)return;
 b.widgetLayout=Array.isArray(b.widgetLayout)?b.widgetLayout.filter(id=>id!=='plan'):['chapter','cards'];
 if(!b.widgetLayout.includes('chapter'))b.widgetLayout.unshift('chapter');
 if(!b.widgetLayout.includes('timer'))b.widgetLayout.splice(b.widgetLayout.indexOf('chapter')+1,0,'timer');
 b.ncWidgets38=1;try{persist()}catch(e){}
}
function ncWidgetPicker(b){const chosen=new Set(b.widgetLayout||[]);return `<div class="nc-widget-picker" role="group" aria-label="Выбор виджетов"><div class="tiny muted">Нажми, чтобы показать или убрать. Порядок — в «Расставить виджеты».</div>${widgetCatalog().map(([id,title,ico])=>`<button type="button" class="nc-picker-item ${chosen.has(id)?'on':''}" data-nc-widget-toggle="${esc(id)}" aria-pressed="${chosen.has(id)}"><span aria-hidden="true">${ico}</span>${esc(title)}<b aria-hidden="true">${chosen.has(id)?'✓':'＋'}</b></button>`).join('')}</div>`}
function ncWidgetCardHtml(b,ch,id,i,ids,catalog,folded){
 const item=catalog.get(id),f=folded.has(id),side=ncWidgetSide(b,id);
 const sideBtn=ncZenOn()?`<button type="button" class="nc-side-btn" data-nc-widget-side="${esc(id)}" title="${side==='left'?'Перенести направо':'Перенести налево'}" aria-label="${side==='left'?'Перенести направо':'Перенести налево'}: ${esc(item[1])}">${side==='left'?'→':'←'}</button>`:'';
 const zdrag=ncZenOn()&&!ui.widgetArrange?` draggable="true" data-nc-wdrag="${esc(id)}" title="Перетащи за заголовок на другую сторону или выше/ниже"`:'';
 return `<section class="widget-preview-card ${f?'nc-folded':''} ${ncZenOn()&&side==='left'?'nc-on-left':''}" data-widget-active="${esc(id)}"><div class="widget-item-heading"${zdrag}>
 <button type="button" class="nc-fold" data-nc-widget-fold="${esc(id)}" aria-expanded="${!f}" title="${f?'Развернуть':'Свернуть'}"><strong>${item[2]} ${esc(item[1])}</strong><span class="nc-fold-mark" aria-hidden="true">${f?'▸':'▾'}</span></button>${sideBtn}
 ${ui.widgetArrange?`<span class="widget-item-tools"><span class="widget-grip" data-widget-grip="${esc(id)}" draggable="true" tabindex="0" role="button" aria-label="Перетащить виджет ${esc(item[1])}" title="Перетащить виджет мышью">⋮⋮</span><button type="button" class="btn small" data-widget-shift="-1" data-widget-id="${esc(id)}" ${i===0?'disabled':''} title="Выше" aria-label="Переместить ${esc(item[1])} выше">↑</button><button type="button" class="btn small" data-widget-shift="1" data-widget-id="${esc(id)}" ${i===ids.length-1?'disabled':''} title="Ниже" aria-label="Переместить ${esc(item[1])} ниже">↓</button></span>`:''}</div>
 ${f?'':`<div class="widget-content">${widgetPanelContent(id,b,ch)}</div>`}</section>`;
}
function ncWidgetIds(b){const catalog=new Map(widgetCatalog().map(x=>[x[0],x]));return {catalog,ids:(b.widgetLayout||['chapter','cards']).filter(id=>catalog.has(id)),folded:new Set(b.widgetCollapsed||[])}}
function writerWidgetPreview(b,ch){
 ncWidgetsMigrate(b);
 const {catalog,ids,folded}=ncWidgetIds(b);
 const split=ncZenOn()&&!ui.widgetArrange;
 const shown=ids.map((id,i)=>[id,i]).filter(([id])=>!split||ncWidgetSide(b,id)!=='left');
 const hint=ui.widgetArrange?(ncZenOn()?'Перетащи за ⋮⋮ или используй стрелки; ← → — сторона в фокусе':'Перетащи за ⋮⋮ или используй стрелки'):'Порядок сохраняется для этой книги';
 return `<div class="widget-desk-preview writer-widget-stack ${ui.widgetArrange?'widget-arranging':''}" data-widget-stack="desk">
 <div class="widget-stack-toolbar"><div><div class="cap">Мои виджеты</div><small class="muted">${hint}</small></div>
 <div class="widget-stack-tools"><button type="button" class="btn small ${ui.widgetPicker?'gold':''}" data-nc-widget-picker aria-expanded="${!!ui.widgetPicker}" title="Показать или убрать виджеты">${ui.widgetPicker?'✓ Готово':'＋ Виджеты'}</button><button type="button" class="btn small ${ui.widgetArrange?'gold':''}" data-widget-arrange aria-pressed="${!!ui.widgetArrange}">${widgetEditLabel()}</button></div></div>
 ${ui.widgetPicker?ncWidgetPicker(b):''}
 ${shown.map(([id,i])=>ncWidgetCardHtml(b,ch,id,i,ids,catalog,folded)).join('')}
 ${ids.length?(shown.length?'':'<p class="muted tiny nc-zen-empty">Все виджеты сейчас слева. «→» на виджете возвращает его сюда.</p>'):'<p class="muted tiny">Все виджеты убраны. Нажми «＋ Виджеты», чтобы вернуть нужные.</p>'}</div>`;
}
function ncPlanWidget(b,ch){
 if(!ch)return '<p class="muted">Выбери главу.</p>';
 return `<h4 class="nc-plan-title">${esc(ch.title)}</h4><div class="nc-plan-scroll" tabindex="0" aria-label="План главы"><p class="nc-plan-text">${esc(ch.summary||'Добавь краткий замысел главы в разделе «План глав».')}</p>${ch.goal?`<div class="nc-plan-goal"><b>Подробности</b><p>${esc(ch.goal)}</p></div>`:''}</div><div class="nc-widget-row"><button type="button" class="btn small" data-edit="chapter" data-id="${esc(ch.id)}">✎ Редактировать план</button>${ncMarksOf(ch).length?`<button type="button" class="btn small" data-nc-stop-go="chapter" title="К следующей отметке (${ncKeys('K')})">↧ К отметке</button>`:''}</div>${ncMarksListHtml(ch)}`;
}
function ncTimerWidget(){
 const p=ritualPrefs(),br=ritualTimer.phase==='break';
 return `<div class="nc-timer"><div class="nc-timer-clock" data-ritual-clock>${ritualTime(ritualCurrentMs())}</div><div class="nc-timer-phase" data-ritual-phase>${br?'Отдых':'Время писать'}</div><div class="nc-widget-row"><button type="button" class="btn small gold" data-ritual-action="start" data-ritual-start>${ritualTimer.running?'Ⅱ Пауза':'▶ '+(br?'Начать отдых':'Начать')}</button><button type="button" class="btn small" data-ritual-action="plus" title="Добавить 10 минут">+10 мин</button><button type="button" class="btn small" data-ritual-action="reset" title="Сбросить таймер" aria-label="Сбросить таймер">↺</button><button type="button" class="btn small" data-ritual-action="phase" data-nc-phase-btn>${br?'✒ К письму':'☕ Перерыв'}</button></div><label class="nc-timer-preset">Письмо / отдых <select data-ritual-pref="preset">${Object.keys(RITUAL_PRESETS).map(x=>`<option value="${x}" ${p.preset===x?'selected':''}>${x} мин</option>`).join('')}</select></label><div class="tiny muted">+ <b data-ritual-added>0</b> зн. за сеанс</div></div>`;
}
function ncMusicWidget(){
 const a=document.querySelector('#studioAudio'),t=getMusicIndex().get(musicRuntime.trackId),on=!!(t&&a&&!a.paused);
 const pl=t?(state.musicPlaylists.find(x=>x.id===musicRuntime.playlistId)?.name||''):'';
 return `<div class="nc-mini-player"><div class="nc-mini-title" data-nc-mini-title>${esc(t?.title||'Музыка не играет')}</div><div class="tiny muted" data-nc-mini-sub>${esc(t?pl:'Нажми ▶ — заиграет плейлист книги')}</div><div class="nc-widget-row"><button type="button" class="btn small" data-act="music-prev" title="Предыдущий трек" aria-label="Предыдущий трек">⏮</button><button type="button" class="btn small gold" data-act="music-playpause" data-nc-mini-play title="Играть / пауза" aria-label="Играть или пауза">${on?'❚❚':'▶'}</button><button type="button" class="btn small" data-act="music-next" title="Следующий трек" aria-label="Следующий трек">⏭</button></div></div>`;
}
document.addEventListener('click',e=>{
 const pk=e.target.closest('[data-nc-widget-picker]');
 if(pk){e.preventDefault();e.stopPropagation();ui.widgetPicker=!ui.widgetPicker;ncDeskRefreshWidgets();return}
 const tg=e.target.closest('[data-nc-widget-toggle]');
 if(tg){e.preventDefault();e.stopPropagation();const b=book();if(!b)return;const id=tg.dataset.ncWidgetToggle;b.widgetLayout??=[];b.widgetLayout=b.widgetLayout.includes(id)?b.widgetLayout.filter(x=>x!==id):[...b.widgetLayout,id];persist();ncDeskRefreshWidgets();return}
 const fold=e.target.closest('[data-nc-widget-fold]');
 if(fold&&!ui.widgetArrange){e.preventDefault();e.stopPropagation();const b=book();if(!b)return;const id=fold.dataset.ncWidgetFold;const s=new Set(b.widgetCollapsed||[]);s.has(id)?s.delete(id):s.add(id);b.widgetCollapsed=[...s];persist();ncDeskRefreshWidgets();return}
},true);
/* Перерисовать только колонку виджетов: текст главы и курсор не трогаем. */
function ncDeskRefreshWidgets(){
 const stack=document.querySelector('.writer-widget-stack[data-widget-stack="desk"]');
 const ctx=typeof chapterWriterContext==='function'?chapterWriterContext():null;
 if(!stack||!ctx?.b){render();return}
 const t=document.createElement('template');t.innerHTML=writerWidgetPreview(ctx.b,ctx.ch).trim();
 const fresh=t.content.firstElementChild;if(fresh){stack.replaceWith(fresh);try{ncZenPlace(true)}catch(e){}ritualPageTimer()}
}

/* ——— Плеер в фокусе: прячется внизу и выезжает, когда мышь у нижнего края. ——— */
/* RC3.8.5: и вне фокуса плеер виден, только пока играет музыка (в «Музыкальной шкатулке» — всегда).
   Тишина — плеер уезжает вниз; мышь у нижнего края или на ярлычке «♫ плеер» — выезжает. */
var ncDockTimer=null,ncDockHideTimer=null;
function ncDockPlaying(){const a=document.querySelector('#studioAudio');return !!(a&&a.currentSrc&&!a.paused&&!a.ended)}
function ncDockState(){
 const on=ncDockPlaying()||ui.tab==='music',body=document.body;
 clearTimeout(ncDockHideTimer);
 if(on){body.classList.add('nc-music-on');return}
 if(!body.classList.contains('nc-music-on'))return;
 ncDockHideTimer=setTimeout(()=>{if(!ncDockPlaying()&&ui.tab!=='music')body.classList.remove('nc-music-on')},1400);
}
document.addEventListener('mousemove',e=>{
 const body=document.body,hidden=ui.writerZen||!body.classList.contains('nc-music-on');
 if(!hidden){if(body.classList.contains('nc-dock-peek')){clearTimeout(ncDockTimer);body.classList.remove('nc-dock-peek')}return}
 const near=e.clientY>window.innerHeight-(ui.writerZen?48:16)||!!e.target.closest?.('#soundDock,.nc-dock-hint');
 if(near){clearTimeout(ncDockTimer);body.classList.add('nc-dock-peek')}
 else if(body.classList.contains('nc-dock-peek')){clearTimeout(ncDockTimer);ncDockTimer=setTimeout(()=>body.classList.remove('nc-dock-peek'),650)}
},{passive:true});
(function(){
 if(!document.querySelector('.nc-dock-hint'))document.body.insertAdjacentHTML('beforeend','<div class="nc-dock-hint" aria-hidden="true">♫ плеер</div>');
 if(!document.querySelector('.nc-foot-credit'))document.body.insertAdjacentHTML('beforeend','<div class="nc-foot-credit" aria-hidden="true">NOCTURNE © 2026 · Елизавета Левинская</div>');
 const a=document.querySelector('#studioAudio');if(a)['play','playing','pause','ended','emptied','abort','error'].forEach(t=>a.addEventListener(t,()=>{try{ncDockState()}catch(e){}}));
})();

/* ——— Музыка: клавиши ⏮ ⏯ ⏭ на клавиатуре и в «Пункте управления»,
       громкость выше 100 % и мини-плеер в виджете. ——— */
var ncMusicGraph=null;
function ncMusicAudio(){return document.querySelector('#studioAudio')}
function ncMusicBoost(level){
 const a=ncMusicAudio();if(!a)return false;
 try{
  if(!ncMusicGraph){
   const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return false;
   const ctx=new AC(),src=ctx.createMediaElementSource(a),gain=ctx.createGain(),lim=ctx.createDynamicsCompressor();
   lim.threshold.value=-4;lim.knee.value=4;lim.ratio.value=12;lim.attack.value=.003;lim.release.value=.25;
   src.connect(gain);gain.connect(lim);lim.connect(ctx.destination);ncMusicGraph={ctx,gain};
  }
  if(ncMusicGraph.ctx.state!=='running')ncMusicGraph.ctx.resume().catch(()=>{});
  ncMusicGraph.gain.gain.value=Math.max(1,level);return true;
 }catch(e){window.__ncLog?.('music boost: '+(e&&e.message));return false}
}
function ncSetMusicVolume(v,fromGesture){
 v=Math.max(0,Math.min(2,Number(v)||0));state.musicVolume=v;
 const a=ncMusicAudio();if(a)a.volume=Math.min(1,v);
 if(v>1){if(fromGesture||ncMusicGraph)ncMusicBoost(v)}else if(ncMusicGraph)ncMusicGraph.gain.gain.value=1;
 const out=document.querySelector('#ncVolumeLabel');if(out)out.textContent=Math.round(v*100)+'%';
 const s=document.querySelector('#musicVolume');if(s){s.title='Громкость '+Math.round(v*100)+'%'+(v>1?' (усиление)':'');s.classList.toggle('nc-boost',v>1)}
 clearTimeout(ncSetMusicVolume.t);ncSetMusicVolume.t=setTimeout(()=>persist(),400);
}
(function(){
 const a=ncMusicAudio(),s=document.querySelector('#musicVolume');
 const v=Number.isFinite(Number(state.musicVolume))?Number(state.musicVolume):1;
 if(s){s.max='2';s.step='0.05';s.value=String(v);s.insertAdjacentHTML('afterend','<output id="ncVolumeLabel" class="sound-time nc-vol-label"></output>')}
 if(a)a.volume=Math.min(1,v);
 ncSetMusicVolume(v,false);
 /* Усиление включается только по действию человека: иначе браузер может оставить звук выключенным. */
 const arm=()=>{if((state.musicVolume||1)>1&&!ncMusicGraph)ncMusicBoost(state.musicVolume);else if(ncMusicGraph&&ncMusicGraph.ctx.state!=='running')ncMusicGraph.ctx.resume().catch(()=>{})};
 document.addEventListener('pointerdown',arm,true);document.addEventListener('keydown',arm,true);
 if(a){a.addEventListener('play',ncMusicSync);a.addEventListener('pause',ncMusicSync);a.addEventListener('loadedmetadata',ncMusicSync)}
 const ms=navigator.mediaSession;if(!ms)return;
 const set=(k,f)=>{try{ms.setActionHandler(k,f)}catch(e){}};
 set('play',()=>{const el=ncMusicAudio();if(musicRuntime.trackId&&el)el.play().then(renderMusicDock).catch(()=>{});else{const id=book()?.atmospherePlaylistId||state.activeMusicPlaylistId;if(id)playPlaylist(id)}});
 set('pause',()=>{ncMusicAudio()?.pause()});
 set('stop',()=>{ncMusicAudio()?.pause()});
 set('previoustrack',()=>stepTrack(-1));
 set('nexttrack',()=>stepTrack(1));
 set('seekto',d=>{const el=ncMusicAudio();if(el&&Number.isFinite(d?.seekTime))el.currentTime=d.seekTime});
})();
document.addEventListener('input',e=>{if(e.target.id==='musicVolume'){e.stopImmediatePropagation();ncSetMusicVolume(e.target.value,true)}},true);
document.addEventListener('change',e=>{if(e.target.id==='musicVolume'){e.stopImmediatePropagation();ncSetMusicVolume(e.target.value,true)}},true);
function ncMusicSync(){
 const a=ncMusicAudio();const t=typeof getMusicIndex==='function'?getMusicIndex().get(musicRuntime.trackId):null;
 const on=!!(t&&a&&!a.paused);
 document.querySelectorAll('[data-nc-mini-play]').forEach(b=>b.textContent=on?'❚❚':'▶');
 document.querySelectorAll('[data-nc-mini-title]').forEach(x=>x.textContent=t?.title||'Музыка не играет');
 const pl=t?(state.musicPlaylists.find(x=>x.id===musicRuntime.playlistId)?.name||''):'';
 document.querySelectorAll('[data-nc-mini-sub]').forEach(x=>x.textContent=t?pl:'Нажми ▶ — заиграет плейлист книги');
 const ms=navigator.mediaSession;if(!ms)return;
 try{
  if(t&&window.MediaMetadata){const key=t.id+'|'+pl;if(ncMusicSync.key!==key){ncMusicSync.key=key;ms.metadata=new MediaMetadata({title:t.title||'Без названия',artist:pl||'NOCTURNE',album:book()?.title||'NOCTURNE'})}}
  else if(!t){ms.metadata=null;ncMusicSync.key=''}
  ms.playbackState=t?(a.paused?'paused':'playing'):'none';
  if(t&&a&&Number.isFinite(a.duration)&&a.duration>0&&ms.setPositionState)ms.setPositionState({duration:a.duration,playbackRate:a.playbackRate||1,position:Math.min(a.duration,a.currentTime||0)});
 }catch(e){}
}

/* ——— Печатная машинка громче: общий выход с мягким ограничителем,
       чтобы на полной громкости звук был отчётливым, но не хрипел. ——— */
function ncTypeOut(ac){
 if(!ac.__ncOut){
  /* Цепочка: усиление → жёсткий ограничитель → мягкое «насыщение» (никогда не выше 0 дБ) → громкость из настроек. */
  const g=ac.createGain(),lim=ac.createDynamicsCompressor(),make=ac.createGain(),sh=ac.createWaveShaper(),vol=ac.createGain();
  g.gain.value=9;lim.threshold.value=-20;lim.knee.value=3;lim.ratio.value=20;lim.attack.value=.0005;lim.release.value=.05;make.gain.value=3.2;
  const n=2048,c=new Float32Array(n),k=2.2;for(let i=0;i<n;i++){const x=i/(n-1)*2-1;c[i]=Math.tanh(k*x)/Math.tanh(k)}sh.curve=c;sh.oversample='none';
  g.connect(lim);lim.connect(make);make.connect(sh);sh.connect(vol);vol.connect(ac.destination);ac.__ncOut=g;ac.__ncVol=vol;
 }
 const v=Math.max(0,Math.min(100,Number(ritualPrefs().volume)||0))/100;
 try{ac.__ncVol.gain.setValueAtTime(Math.pow(v,1.6),ac.currentTime)}catch(e){ac.__ncVol.gain.value=Math.pow(v,1.6)}
 return ac.__ncOut;
}
function ncTypeNoise(ac){if(!ac.__ncNoise){const nb=ac.createBuffer(1,Math.round(ac.sampleRate*.5),ac.sampleRate),a=nb.getChannelData(0);for(let i=0;i<a.length;i++)a[i]=Math.random()*2-1;ac.__ncNoise=nb}return ac.__ncNoise}
/* RC3.8.1: звук клавиш заметно громче и плотнее, чтобы его было слышно поверх музыки:
   щелчок (высокие), удар (середина) и короткий «тук» (низ). Громкость — общим регулятором. */
function ritualPlay(kind,scale=1){
 const p=ritualPrefs();if(p.sound==='off'||p.volume<=0)return;
 try{
  const ac=ritualAudio();if(!ac)return;const out=ncTypeOut(ac),t=ac.currentTime+.002,nb=ncTypeNoise(ac),rate=.92+Math.random()*.16;
  const env=(node,peak,dur)=>{const g=ac.createGain();g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(Math.max(.0002,peak*scale),t+.002);g.gain.exponentialRampToValueAtTime(.0001,t+dur);node.connect(g);g.connect(out)};
  const noise=(type,freq,q,peak,dur)=>{const s=ac.createBufferSource();s.buffer=nb;s.playbackRate.value=rate;const f=ac.createBiquadFilter();f.type=type;f.frequency.value=freq;f.Q.value=q;s.connect(f);env(f,peak,dur);s.start(t,Math.random()*.2);s.stop(t+dur+.03)};
  const tone=(type,f0,f1,peak,dur)=>{const o=ac.createOscillator();o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(f1,t+dur);env(o,peak,dur);o.start(t);o.stop(t+dur+.02)};
  if(kind==='bell'){noise('bandpass',2200,1.4,.25,.11);tone('sine',1150,870,.3,.25);return}
  if(p.sound==='soft'){noise('lowpass',1500,.6,.55,.06);noise('bandpass',700,.8,.35,.05);return}
  if(p.sound==='quill'){noise('lowpass',1800,.3,.35,.11);noise('bandpass',3200,.5,.12,.08);return}
  noise('highpass',2600,.7,.55,.014);noise('bandpass',1250,.9,.5,.045);tone('triangle',260,150,.35,.035);
 }catch(_){/* звук не должен мешать письму */}
}
function ritualCarriageReturn(){
 const p=ritualPrefs();if(p.sound==='off'||p.volume<=0)return;
 try{
  const ac=ritualAudio();if(!ac)return;const out=ncTypeOut(ac),t=ac.currentTime+.002;
  if(p.bell){const o=ac.createOscillator(),g=ac.createGain();o.type='sine';o.frequency.setValueAtTime(1340,t);o.frequency.exponentialRampToValueAtTime(1030,t+.13);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.16,t+.009);g.gain.exponentialRampToValueAtTime(.0001,t+.22);o.connect(g);g.connect(out);o.start(t);o.stop(t+.23)}
  const buffer=ac.createBuffer(1,Math.round(ac.sampleRate*.46),ac.sampleRate),data=buffer.getChannelData(0);
  for(let i=0;i<data.length;i++){const x=i/ac.sampleRate,envelope=Math.exp(-5*x),pulse=((x*49)%1<.22)?1:.38;data[i]=(Math.random()*2-1)*envelope*pulse}
  const src=ac.createBufferSource(),filter=ac.createBiquadFilter(),g=ac.createGain();src.buffer=buffer;filter.type='bandpass';filter.frequency.value=p.sound==='soft'?760:1650;filter.Q.value=.65;g.gain.setValueAtTime(.0001,t+.065);g.gain.exponentialRampToValueAtTime(.42,t+.09);g.gain.exponentialRampToValueAtTime(.0001,t+.51);src.connect(filter);filter.connect(g);g.connect(out);src.start(t+.065);src.stop(t+.52);
  const stop=ac.createOscillator(),sg=ac.createGain();stop.type='triangle';stop.frequency.setValueAtTime(210,t+.49);stop.frequency.exponentialRampToValueAtTime(92,t+.57);sg.gain.setValueAtTime(.0001,t+.49);sg.gain.exponentialRampToValueAtTime(.32,t+.501);sg.gain.exponentialRampToValueAtTime(.0001,t+.585);stop.connect(sg);sg.connect(out);stop.start(t+.49);stop.stop(t+.59);
 }catch(_){/* звук не должен мешать письму */}
}
function ncTypewriterLine(){
 const p=ritualPrefs(),off=p.sound==='off';
 return `<div class="writer-toolline nc-typewriter-line"><span class="cap">Звук печати</span><select data-ritual-pref="sound" aria-label="Звук печати"><option value="off" ${off?'selected':''}>Без звука</option><option value="classic" ${p.sound==='classic'?'selected':''}>Классическая машинка</option><option value="soft" ${p.sound==='soft'?'selected':''}>Мягкие клавиши</option><option value="quill" ${p.sound==='quill'?'selected':''}>Шуршание пера</option></select><label class="nc-inline">Громкость <input type="range" data-ritual-pref="volume" min="0" max="100" step="5" value="${p.volume}" ${off?'disabled':''} aria-label="Громкость печати"> <b data-ritual-volume>${p.volume}%</b></label><label class="nc-inline"><input type="checkbox" data-ritual-pref="enterSound" ${p.enterSound?'checked':''}> Enter — каретка</label><label class="nc-inline"><input type="checkbox" data-ritual-pref="bell" ${p.bell?'checked':''} ${!p.enterSound?'disabled':''}> звонок</label><label class="nc-inline"><input type="checkbox" data-ritual-pref="followCaret" ${p.followCaret?'checked':''}> Строка набора в центре</label><button type="button" class="btn small" data-nc-type-test ${off?'disabled':''}>▶ Проба</button></div>`;
}
document.addEventListener('click',e=>{if(e.target.closest('[data-nc-type-test]')){e.preventDefault();ritualPlay('key');setTimeout(()=>ritualPlay('key'),120);setTimeout(()=>ritualPlay('key'),230);setTimeout(()=>{if(ritualPrefs().enterSound)ritualCarriageReturn()},420)}});
document.addEventListener('change',e=>{if(e.target.matches?.('.nc-typewriter-line [data-ritual-pref]'))setTimeout(ncTypewriterSync,0)});
document.addEventListener('input',e=>{if(e.target.matches?.('.nc-typewriter-line [data-ritual-pref="volume"]')){const v=e.target.value;document.querySelectorAll('[data-ritual-volume]').forEach(x=>x.textContent=v+'%');clearTimeout(ncTypewriterSync.t);ncTypewriterSync.t=setTimeout(()=>ritualPlay('key'),120)}});
function ncTypewriterSync(){const line=document.querySelector('.nc-typewriter-line');if(!line)return;const t=document.createElement('template');t.innerHTML=ncTypewriterLine();line.replaceWith(t.content.firstElementChild)}

/* ——— Отметка «здесь я остановилась»: подсветка фразы в главе и в «Редакциях».
       Текст рукописи не меняется: отметка хранится отдельно и находится по фразе. ——— */
var ncHL=!!(window.CSS&&CSS.highlights&&window.Highlight);
function ncRangeFromOffsets(root,start,end){
 const {nodes}=markTextNodes(root);let r=null;const rg=document.createRange();let okS=false,okE=false;
 for(const [n,at] of nodes){const len=n.nodeValue.length;
  if(!okS&&start<=at+len){rg.setStart(n,Math.max(0,start-at));okS=true}
  if(okS&&end<=at+len){rg.setEnd(n,Math.max(0,end-at));okE=true;break}}
 if(okS&&okE)r=rg;return r;
}
function ncStopRange(ed,mark){
 if(!ed||!mark?.quote)return null;
 const {text}=markTextNodes(ed);const r=markFindRange(text,mark.quote,mark.offset);
 return r?ncRangeFromOffsets(ed,r[0],r[1]):null;
}
/* RC3.8.6: в главе сколько угодно отметок — «Отметка 1», «Отметка 2»… по порядку в тексте.
   Старая одиночная ch.stopMark становится первой в списке ch.stopMarks. */
function ncDeskChapter(){const ed=document.querySelector('[data-chapter-document]');const b=book();const ch=ed&&b?.chapters?.find(c=>c.id===ed.dataset.chapterDocument);return {ed,ch}}
function ncMarksOf(ch){
 if(!ch)return [];
 if(ch.stopMark&&!Array.isArray(ch.stopMarks)){ch.stopMarks=[{...ch.stopMark,id:ch.stopMark.id||uid()}];delete ch.stopMark}
 if(!Array.isArray(ch.stopMarks))return [];
 ch.stopMarks.forEach(m=>{if(!m.id)m.id=uid()});return ch.stopMarks;
}
function ncMarksSorted(ch){return ncMarksOf(ch).slice().sort((a,b)=>(Number(a.offset)||0)-(Number(b.offset)||0))}
function ncMarksLocated(ed,ch){
 if(!ed||!ch)return [];const {text}=markTextNodes(ed);const out=[];
 for(const m of ncMarksSorted(ch)){const at=markFindRange(text,m.quote,m.offset);if(at){m.offset=at[0];out.push({m,at})}}
 return out.sort((x,y)=>x.at[0]-y.at[0]);
}
function ncDeskCaret(ed){
 const sel=window.getSelection();
 try{if(sel?.rangeCount&&ed.contains(sel.focusNode)){const c=document.createRange();c.selectNodeContents(ed);c.setEnd(sel.focusNode,sel.focusOffset);return c.toString().length}}catch(e){}
 return -1;
}
function ncStopPaint(){
 if(!ncHL)return;
 const {ed,ch}=ncDeskChapter();const rs=[];
 for(const {at} of ncMarksLocated(ed,ch)){const r=ncRangeFromOffsets(ed,at[0],at[1]);if(r)rs.push(r)}
 if(rs.length)CSS.highlights.set('nc-stop',new Highlight(...rs));else CSS.highlights.delete('nc-stop');
}
function ncSentenceAround(ed){
 const sel=window.getSelection();if(!sel?.rangeCount||!ed.contains(sel.anchorNode))return null;
 const range=sel.getRangeAt(0);
 if(!range.collapsed&&range.toString().trim())return range.cloneRange();
 let block=(sel.anchorNode.nodeType===1?sel.anchorNode:sel.anchorNode.parentElement).closest('div,p,h2,h3,h4,li,blockquote');
 if(!block||!ed.contains(block)||block===ed)block=null;
 const host=block||ed;const {text}=markTextNodes(host);
 const pre=document.createRange();pre.selectNodeContents(host);pre.setEnd(range.startContainer,range.startOffset);
 const caret=pre.toString().length;
 let s=caret;while(s>0&&!/[.!?…]/.test(text[s-1])&&caret-s<300)s--;while(s<text.length&&/\s/.test(text[s]))s++;
 let e=caret;while(e<text.length&&!/[.!?…]/.test(text[e])&&e-caret<300)e++;if(e<text.length)e++;
 if(e<=s){s=Math.max(0,caret-20);e=Math.min(text.length,caret+20)}
 return ncRangeFromOffsets(host,s,e);
}
function ncStopSetChapter(){
 const {ed,ch}=ncDeskChapter();if(!ch){notify('Открой главу на письменном столе');return}
 const marks=ncMarksOf(ch),sel=window.getSelection(),caret=ncDeskCaret(ed);
 /* курсор стоит внутри уже отмеченной фразы — снять эту отметку */
 if(caret>=0&&sel?.isCollapsed){const loc=ncMarksLocated(ed,ch);const i=loc.findIndex(x=>caret>=x.at[0]&&caret<=x.at[1]);
  if(i>=0){ch.stopMarks=marks.filter(m=>m!==loc[i].m);persist();ncStopPaint();ncDeskRefreshWidgets();notify('Отметка '+(i+1)+' снята');return}}
 const r=ncSentenceAround(ed);if(!r){notify('Поставь курсор в тексте или выдели фразу — и нажми ещё раз');return}
 const quote=r.toString().replace(/\s+/g,' ').trim().slice(0,400);if(!quote){notify('Выдели фразу с текстом');return}
 const pre=document.createRange();pre.selectNodeContents(ed);pre.setEnd(r.startContainer,r.startOffset);
 const offset=pre.toString().length,len=r.toString().length;
 const mark={id:uid(),quote,offset,caret:caret>=offset&&caret<=offset+len?caret-offset:len,at:Date.now()};
 marks.push(mark);ch.stopMarks=marks;persist();ncStopPaint();
 const n=ncMarksLocated(ed,ch).findIndex(x=>x.m===mark)+1,all=marks.length;
 notify((n>0?'Отметка '+n:'Место отмечено')+(all>1?' из '+all:'')+(ncHL?' — фраза подсвечена':'. «↧ К отметке» вернёт сюда'));
 ncDeskRefreshWidgets();
}
/* Без номера — к следующей отметке после курсора (по кругу); с номером — к этой отметке. */
function ncStopGoChapter(idx){
 const {ed,ch}=ncDeskChapter();
 if(!ch||!ncMarksOf(ch).length){notify('В этой главе нет отметок. Поставь курсор в текст и нажми «⚑ Отметить место»');return}
 const loc=ncMarksLocated(ed,ch);if(!loc.length){notify('Отмеченные фразы больше не найдены в тексте');return}
 let k;
 if(Number.isInteger(idx))k=Math.max(0,Math.min(loc.length-1,idx));
 else{const caret=ncDeskCaret(ed);k=caret<0?0:loc.findIndex(x=>x.at[0]>caret);if(k<0)k=0}
 const {m,at}=loc[k],r=ncRangeFromOffsets(ed,at[0],at[1]);if(!r)return;
 ncStopPaint();ncScrollRangeIntoView(r);
 try{ed.focus({preventScroll:true});const rel=Math.max(0,Math.min(Number(m.caret)||0,at[1]-at[0]));const c=ncRangeFromOffsets(ed,at[0]+rel,at[0]+rel);const sel=window.getSelection();sel.removeAllRanges();sel.addRange(ncHL&&c?c:r)}catch(e){}
 ncFlashRange(r);
 if(loc.length>1)notify('Отметка '+(k+1)+' из '+loc.length);
}
function ncStopClearChapter(id){
 const {ch}=ncDeskChapter();const marks=ncMarksOf(ch);if(!marks.length)return;
 if(id){const loc=ncMarksSorted(ch);const i=loc.findIndex(m=>m.id===id);ch.stopMarks=marks.filter(m=>m.id!==id);persist();ncStopPaint();ncDeskRefreshWidgets();notify(i>=0?'Отметка '+(i+1)+' снята':'Отметка снята');return}
 ch.stopMarks=[];persist();ncStopPaint();ncDeskRefreshWidgets();notify('Отметки сняты');
}
function ncMarksListHtml(ch){
 const ms=ncMarksSorted(ch);if(!ms.length)return '';
 return `<div class="nc-marks" aria-label="Отметки в главе"><div class="nc-marks-h">⚑ Отметки · ${ms.length}</div><div class="nc-marks-list">${ms.map((m,i)=>`<div class="nc-mark-row"><button type="button" class="nc-mark-go" data-nc-stop-go="chapter" data-nc-stop-i="${i}" title="${esc('Отметка '+(i+1)+': «'+snip(m.quote||'',160)+'»')}"><b>${i+1}</b><span>${esc(snip(m.quote||'',70))}</span></button><button type="button" class="nc-mark-x" data-nc-stop-del="${esc(m.id)}" title="Снять отметку ${i+1}" aria-label="Снять отметку ${i+1}">×</button></div>`).join('')}</div></div>`;
}
document.addEventListener('mousedown',e=>{if(e.target.closest('[data-nc-stop-set="chapter"]'))e.preventDefault()},true);
document.addEventListener('click',e=>{
 const del=e.target.closest('[data-nc-stop-del]');if(del){e.preventDefault();e.stopPropagation();if(del.dataset.ncStopWhere)ncLabStopClear(del.dataset.ncStopWhere,del.dataset.ncStopDel);else ncStopClearChapter(del.dataset.ncStopDel);return}
 const s=e.target.closest('[data-nc-stop-set]'),g=e.target.closest('[data-nc-stop-go]'),c=e.target.closest('[data-nc-stop-clear]');
 if(!s&&!g&&!c)return;e.preventDefault();e.stopPropagation();
 const where=(s||g||c).dataset.ncStopSet||(s||g||c).dataset.ncStopGo||(s||g||c).dataset.ncStopClear;
 if(where==='chapter'){if(s)ncStopSetChapter();else if(g)ncStopGoChapter(g.dataset.ncStopI!=null?Number(g.dataset.ncStopI):undefined);else ncStopClearChapter();return}
 if(s)ncLabStopSet(where);else if(g)ncLabStopGo(where,g.dataset.ncStopI!=null?Number(g.dataset.ncStopI):undefined);else ncLabStopClear(where);
},true);

/* Прокрутить к диапазону: сначала внутренний скролл, потом окно. */
function ncScrollRangeIntoView(r,block=.35){
 let rect=r.getBoundingClientRect();if(!rect||(!rect.width&&!rect.height)){const rs=r.getClientRects();if(rs.length)rect=rs[0]}
 let el=(r.startContainer.nodeType===1?r.startContainer:r.startContainer.parentElement);
 while(el&&el!==document.body){const cs=getComputedStyle(el);if(/(auto|scroll)/.test(cs.overflowY)&&el.scrollHeight>el.clientHeight+2){const er=el.getBoundingClientRect();if(rect.top<er.top+20||rect.bottom>er.bottom-20){el.scrollTop+=rect.top-er.top-el.clientHeight*block;rect=r.getBoundingClientRect()}break}el=el.parentElement}
 const topLimit=(document.querySelector('.topbar')?.offsetHeight||0)+(document.querySelector('#ncTabs:not([hidden])')?.offsetHeight||0)+20,bottomLimit=window.innerHeight-90;
 if(rect.top<topLimit||rect.bottom>bottomLimit){const h=document.documentElement,old=h.style.scrollBehavior;h.style.scrollBehavior='auto';window.scrollBy(0,rect.top-window.innerHeight*block);h.style.scrollBehavior=old}
}
function ncFlashRange(r){
 const rects=[...r.getClientRects()].slice(0,8);document.querySelectorAll('.nc-flash').forEach(x=>x.remove());
 rects.forEach(q=>{const d=document.createElement('div');d.className='nc-flash';d.style.cssText=`left:${q.left-3}px;top:${q.top-2}px;width:${q.width+6}px;height:${q.height+4}px`;document.body.append(d);setTimeout(()=>d.remove(),1600)});
}

/* ——— «Редакции и перевод»: синхронная прокрутка, подсветка внутри полей,
       отметка места, переход к главе на письменном столе. ——— */
var NC_LAB_SYNC_KEY='nocturne.labsync.v1';
function ncLabSyncOn(){try{return localStorage.getItem(NC_LAB_SYNC_KEY)==='1'}catch(e){return !!ui.ncLabSync}}
function ncLabSyncSet(v){ui.ncLabSync=!!v;try{localStorage.setItem(NC_LAB_SYNC_KEY,v?'1':'0')}catch(e){}}
function ncLabToolbar(){const on=ncLabSyncOn();return `<label class="nc-lab-sync" title="Крутишь одно окно — второе едет следом, на то же место главы"><input type="checkbox" data-nc-lab-sync ${on?'checked':''}> ⇅ Листать оба окна вместе</label>`}
function ncLabPanes(){const panes=[...document.querySelectorAll('.lab-layout .lab-pane textarea')];return {source:panes.find(t=>t.readOnly)||null,draft:document.querySelector('[data-lab-draft-editor]')}}
/* RC3.8.7: в «Редакциях» у оригинала и у черновика сколько угодно отметок (lab.sourceStops[], draft.stopMarks[]);
   старые одиночные lab.sourceStop / draft.stopMark переносятся в списки. */
function ncLabMarksFor(where){
 const b=book(),lab=textLabData(b);if(!lab)return [];
 const host=where==='source'?lab:textLabDraft(b);if(!host)return [];
 const one=where==='source'?'sourceStop':'stopMark',many=where==='source'?'sourceStops':'stopMarks';
 if(host[one]&&!Array.isArray(host[many])){host[many]=[{...host[one]}];delete host[one]}
 if(!Array.isArray(host[many]))host[many]=[];
 host[many].forEach(m=>{if(!m.id)m.id=uid()});return host[many];
}
function ncLabMarkFor(where){return ncLabMarksFor(where)[0]||null}
function ncLabLocatedAll(ta,where){
 if(!ta)return [];const out=[];
 for(const m of ncLabMarksFor(where)){const at=ncLabLocate(ta,m);if(at){m.start=at.start;m.end=at.end;out.push({m,start:at.start,end:at.end})}}
 return out.sort((a,b)=>a.start-b.start);
}
function ncLabLocate(ta,mark){
 if(!ta||!mark?.quote)return null;const v=ta.value;
 let best=-1,at=v.indexOf(mark.quote);while(at>=0){if(best<0||Math.abs(at-mark.start)<Math.abs(best-mark.start))best=at;at=v.indexOf(mark.quote,at+1)}
 if(best<0){const r=markFindRange(v,mark.quote,mark.start);return r?{start:r[0],end:r[1]}:null}
 return {start:best,end:best+mark.quote.length};
}
function ncTaMirror(ta){
 if(!ta)return null;let wrap=ta.parentElement;
 if(!wrap.classList.contains('nc-ta-wrap')){wrap=document.createElement('div');wrap.className='nc-ta-wrap';ta.before(wrap);const m=document.createElement('div');m.className='nc-ta-mirror';m.setAttribute('aria-hidden','true');wrap.append(m,ta);
  ta.addEventListener('scroll',()=>{m.scrollTop=ta.scrollTop;m.scrollLeft=ta.scrollLeft});
  ta.addEventListener('input',()=>{clearTimeout(ta.__ncT);ta.__ncT=setTimeout(()=>ncTaPaint(ta),120)});
  if(window.ResizeObserver)new ResizeObserver(()=>{const w=ta.offsetWidth,h=ta.offsetHeight;if(w===ta.__ncW&&h===ta.__ncH)return;ta.__ncW=w;ta.__ncH=h;requestAnimationFrame(()=>ncTaPaint(ta))}).observe(ta);
 }
 return wrap.querySelector('.nc-ta-mirror');
}
function ncTaStyle(ta,m){
 const cs=getComputedStyle(ta);
 for(const k of ['fontFamily','fontSize','fontWeight','fontStyle','lineHeight','letterSpacing','wordSpacing','textIndent','tabSize','paddingTop','paddingLeft','paddingBottom','borderTopWidth','borderLeftWidth','borderRightWidth','borderBottomWidth','borderRadius','textAlign'])m.style[k]=cs[k];
 const sb=ta.offsetWidth-ta.clientWidth-(parseFloat(cs.borderLeftWidth)||0)-(parseFloat(cs.borderRightWidth)||0);
 m.style.paddingRight=((parseFloat(cs.paddingRight)||0)+Math.max(0,sb))+'px';
 m.style.width=ta.offsetWidth+'px';m.style.height=ta.offsetHeight+'px';m.style.left=ta.offsetLeft+'px';m.style.top=ta.offsetTop+'px';
 if(!ta.classList.contains('nc-ta-lit'))ta.__ncBg=cs.backgroundColor;m.style.background=ta.__ncBg||cs.backgroundColor;
}
/* Ряды подсветки: [{start,end,cls}] — отметка, найденное, текущее найденное. */
function ncTaPaint(ta){
 if(!ta?.isConnected)return;const m=ncTaMirror(ta);if(!m)return;
 const where=ta.readOnly?'source':'draft';const marks=[];
 for(const x of ncLabLocatedAll(ta,where))marks.push({start:x.start,end:x.end,cls:'nc-mk-stop'});
 if(ncFind.open&&ncFind.ta===ta){(ncFind.taHits||[]).forEach((h,i)=>marks.push({start:h[0],end:h[1],cls:i===ncFind.taCurrent?'nc-mk-find-cur':'nc-mk-find'}))}
 ncTaStyle(ta,m);
 if(!marks.length){m.innerHTML='';ta.classList.remove('nc-ta-lit');return}
 marks.sort((a,b)=>a.start-b.start);const v=ta.value;let out='',pos=0;
 for(const k of marks){if(k.start<pos)continue;out+=esc(v.slice(pos,k.start))+`<mark class="${k.cls}">`+esc(v.slice(k.start,k.end))+'</mark>';pos=k.end}
 out+=esc(v.slice(pos))+'\n ';m.innerHTML=out;m.scrollTop=ta.scrollTop;ta.classList.add('nc-ta-lit');
}
function ncTaScrollTo(ta,start,cls){
 ncTaPaint(ta);const m=ta.parentElement?.querySelector('.nc-ta-mirror');const mk=m?.querySelector('mark.'+cls);
 if(mk){ta.scrollTop=Math.max(0,mk.offsetTop-ta.clientHeight*.33);m.scrollTop=ta.scrollTop;try{ncLabSyncFrom(ta)}catch(e){}}
 const r=ta.getBoundingClientRect();if(r.top<90||r.bottom>window.innerHeight)ta.scrollIntoView({block:'nearest'});
}
/* RC3.8.7: «Листать оба окна вместе» ведёт только то окно, которое листает человек (колесо, тачпад,
   клавиши, полоса прокрутки). Программная прокрутка второго окна и её «эхо» назад не пересылаются —
   в WebKit на Mac события прокрутки приходят с задержкой, и окна раньше подталкивали друг друга по кругу. */
function ncLabLead(t,ms){t.__ncLeadUntil=performance.now()+(ms||450)}
function ncLabSyncFrom(t){
 if(!ncLabSyncOn())return;const {source,draft}=ncLabPanes();const other=t===source?draft:t===draft?source:null;if(!other)return;
 const max=t.scrollHeight-t.clientHeight,omax=other.scrollHeight-other.clientHeight;if(max<=0||omax<=0)return;
 const want=Math.round(t.scrollTop/max*omax);if(Math.abs(other.scrollTop-want)<1.5)return;
 other.__ncEcho=want;other.__ncLeadUntil=0;other.scrollTop=want;
}
function ncLabAfterRender(){
 const {source,draft}=ncLabPanes();
 [source,draft].forEach(t=>{if(t)ncTaPaint(t)});
 try{ncLabButtons()}catch(e){}
 [source,draft].forEach(t=>{if(!t||t.__ncSync)return;t.__ncSync=1;
  const lead=()=>ncLabLead(t);
  ['wheel','touchstart','touchmove','keydown','pointerdown'].forEach(ev=>t.addEventListener(ev,lead,{passive:true}));
  t.addEventListener('pointermove',e=>{if(e.buttons)lead()},{passive:true});
  t.addEventListener('scroll',()=>{
   if(t.__ncEcho!=null){const d=Math.abs(t.scrollTop-t.__ncEcho);t.__ncEcho=null;if(d<=3)return}
   if(!(performance.now()<(t.__ncLeadUntil||0)))return;
   ncLabSyncFrom(t);
  },{passive:true});
 });
}
function ncLabStopSet(where){
 const b=book(),lab=textLabData(b);const {source,draft}=ncLabPanes();const ta=where==='source'?source:draft;if(!ta||!lab)return;
 if(where==='draft'&&!textLabDraft(b))return;
 let s=ta.selectionStart,e=ta.selectionEnd;const v=ta.value;
 if(document.activeElement!==ta&&ta.__ncLastSel){[s,e]=ta.__ncLastSel}
 const caret=s,marks=ncLabMarksFor(where);
 /* курсор внутри уже отмеченной строки — снять эту отметку */
 if(s===e){const loc=ncLabLocatedAll(ta,where);const k=loc.findIndex(x=>caret>=x.start&&caret<=x.end);
  if(k>=0){const keep=marks.filter(m=>m!==loc[k].m);marks.length=0;marks.push(...keep);persist();ncTaPaint(ta);ncLabButtons();notify('Отметка '+(k+1)+' снята');return}}
 if(s===e){const ls=v.lastIndexOf('\n',Math.max(0,s-1))+1;let le=v.indexOf('\n',caret);if(le<0)le=v.length;s=ls;e=le;
  if(e-s>360){s=Math.max(ls,caret-180);e=Math.min(le,caret+180);while(s>ls&&/\S/.test(v[s-1]))s--;while(e<le&&/\S/.test(v[e]))e++}}
 const quote=v.slice(s,e);if(!quote.trim()){notify('Поставь курсор в строку с текстом или выдели фразу');return}
 const mark={id:uid(),start:s,end:e,quote,caret:Math.max(0,Math.min(e-s,caret-s)),at:Date.now()};
 marks.push(mark);persist();ncTaPaint(ta);ncLabButtons();
 const n=ncLabLocatedAll(ta,where).findIndex(x=>x.m===mark)+1;
 notify((n>0?'Отметка '+n:'Место отмечено')+(marks.length>1?' из '+marks.length:'')+' — строка подсвечена');
}
/* Без номера — к следующей отметке после курсора (по кругу); с номером — к этой. */
function ncLabStopGo(where,idx){
 const {source,draft}=ncLabPanes();const ta=where==='source'?source:draft;
 const loc=ncLabLocatedAll(ta,where);
 if(!ta||!ncLabMarksFor(where).length){notify('Здесь ещё нет отметок');return}
 if(!loc.length){notify('Отмеченные строки больше не найдены');return}
 let k;if(Number.isInteger(idx))k=Math.max(0,Math.min(loc.length-1,idx));
 else{const caret=Number(ta.selectionStart)||0;k=loc.findIndex(x=>x.start>caret);if(k<0)k=0}
 const x=loc[k];
 const m=ta.parentElement?.querySelector('.nc-ta-mirror');ncTaPaint(ta);
 const mk=m?[...m.querySelectorAll('mark.nc-mk-stop')][k]:null;
 if(mk){ta.scrollTop=Math.max(0,mk.offsetTop-ta.clientHeight*.33);m.scrollTop=ta.scrollTop;try{ncLabSyncFrom(ta)}catch(e){}}
 const r=ta.getBoundingClientRect();if(r.top<90||r.bottom>window.innerHeight)ta.scrollIntoView({block:'nearest'});
 const p=x.start+Math.max(0,Math.min(x.end-x.start,Number(x.m.caret)||0));
 try{ta.focus({preventScroll:true});ta.setSelectionRange(p,p)}catch(e){}
 if(loc.length>1)notify('Отметка '+(k+1)+' из '+loc.length);
}
function ncLabStopClear(where,id){
 const marks=ncLabMarksFor(where);if(!marks.length)return;
 const {source,draft}=ncLabPanes();const ta=where==='source'?source:draft;
 if(id){const loc=ncLabLocatedAll(ta,where);const k=loc.findIndex(x=>x.m.id===id);const keep=marks.filter(m=>m.id!==id);marks.length=0;marks.push(...keep);notify(k>=0?'Отметка '+(k+1)+' снята':'Отметка снята')}
 else{marks.length=0;notify('Отметки сняты')}
 persist();ncTaPaint(ta);ncLabButtons();
}
function ncLabStopButtons(where){
 const {source,draft}=ncLabPanes();const ta=where==='source'?source:draft;
 const loc=ta?ncLabLocatedAll(ta,where):ncLabMarksFor(where).slice().sort((x,y)=>(x.start||0)-(y.start||0)).map(m=>({m}));const has=loc.length>0;
 return `<span class="nc-lab-stop" data-nc-lab-stop="${where}"><button type="button" class="btn small" data-nc-stop-set="${where}" title="Поставь курсор в строку или выдели фразу — строка подсветится. На отмеченной строке — снимает отметку (${ncKeys('M')})">⚑ Отметить место</button><button type="button" class="btn small" data-nc-stop-go="${where}" title="К следующей отметке (${ncKeys('K')})" ${has?'':'disabled'}>↧ К отметке</button>${loc.map((x,i)=>`<span class="nc-lab-chip"><button type="button" data-nc-stop-go="${where}" data-nc-stop-i="${i}" title="${esc('Отметка '+(i+1)+': «'+snip(x.m.quote||'',120)+'»')}">${i+1}</button><button type="button" class="nc-lab-chip-x" data-nc-stop-del="${esc(x.m.id)}" data-nc-stop-where="${where}" title="Снять отметку ${i+1}" aria-label="Снять отметку ${i+1}">×</button></span>`).join('')}</span>`;
}
function ncLabButtons(){document.querySelectorAll('[data-nc-lab-stop]').forEach(x=>{const t=document.createElement('template');t.innerHTML=ncLabStopButtons(x.dataset.ncLabStop);x.replaceWith(t.content.firstElementChild)})}
document.addEventListener('mousedown',e=>{const s=e.target.closest('[data-nc-stop-set="source"],[data-nc-stop-set="draft"]');if(!s)return;const {source,draft}=ncLabPanes();const ta=s.dataset.ncStopSet==='source'?source:draft;if(ta)ta.__ncLastSel=[ta.selectionStart,ta.selectionEnd]},true);
document.addEventListener('change',e=>{if(e.target.matches?.('[data-nc-lab-sync]')){ncLabSyncSet(e.target.checked);if(e.target.checked){const {draft,source}=ncLabPanes();(draft||source)?.dispatchEvent(new Event('scroll'))}}});
document.addEventListener('click',e=>{const o=e.target.closest('[data-nc-lab-open-desk]');if(!o)return;e.preventDefault();const lab=textLabData(book());const id=lab?.sourceId;if(id&&book()?.chapters?.some(c=>c.id===id))ui.chapterEditorId=id;ncTabGo('desk')});

/* ——— Поиск по тексту: ⌘F (на Windows — Ctrl+F). Ищет в главе на столе,
       в рукописи, в обоих окнах «Редакций» и на остальных страницах. ——— */
var ncFind={open:false,q:'',hits:[],cur:-1,ta:null,taHits:[],taCurrent:-1,timer:null};
function ncNorm(s){return String(s||'').toLocaleLowerCase('ru').replace(/ё/g,'е')}
function ncFindScope(){
 if(ui.tab==='desk')return {kind:'dom',el:document.querySelector('[data-chapter-document]')};
 if(ui.tab==='reader')return {kind:'dom',el:document.querySelector('#readerPagedContent .nocturne-reader-text')||document.querySelector('#readerPagedContent')};
 if(ui.tab==='textlab'){const {source,draft}=ncLabPanes();return {kind:'ta',list:[draft,source].filter(Boolean)}}
 return {kind:'dom',el:document.querySelector('#app')};
}
function ncFindOpen(){
 let bar=document.querySelector('#ncFind');
 if(!bar){bar=document.createElement('div');bar.id='ncFind';bar.className='nc-find';bar.setAttribute('role','search');bar.innerHTML='<span aria-hidden="true">⌕</span><input type="search" placeholder="Найти в тексте…" aria-label="Найти в тексте" autocomplete="off" spellcheck="false"><span class="nc-find-count" aria-live="polite"></span><button type="button" class="btn icon plain" data-nc-find="prev" title="Предыдущее (⇧Enter)" aria-label="Предыдущее">↑</button><button type="button" class="btn icon plain" data-nc-find="next" title="Следующее (Enter)" aria-label="Следующее">↓</button><button type="button" class="btn icon plain" data-nc-find="close" title="Закрыть (Esc)" aria-label="Закрыть поиск">×</button>';document.body.append(bar);
  const inp=bar.querySelector('input');
  inp.addEventListener('input',()=>{clearTimeout(ncFind.timer);ncFind.timer=setTimeout(()=>{ncFind.q=inp.value;ncFindRun(0)},140)});
  inp.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();if(ncFind.q!==inp.value){ncFind.q=inp.value;ncFindRun(0)}else ncFindStep(e.shiftKey?-1:1)}});
  bar.addEventListener('click',e=>{const b=e.target.closest('[data-nc-find]');if(!b)return;e.preventDefault();const a=b.dataset.ncFind;if(a==='close')ncFindClose(false);else ncFindStep(a==='prev'?-1:1)});
 }
 ncFind.open=true;bar.classList.add('on');document.body.classList.add('nc-find-open');
 const inp=bar.querySelector('input');
 const sel=window.getSelection?.()?.toString().trim();if(sel&&sel.length<80&&!sel.includes('\n'))inp.value=sel;
 inp.focus();inp.select();if(inp.value){ncFind.q=inp.value;ncFindRun(0)}else ncFindCount();
}
function ncFindClose(placeCaret){
 const bar=document.querySelector('#ncFind');if(bar)bar.classList.remove('on');document.body.classList.remove('nc-find-open');
 const hit=ncFind.hits[ncFind.cur];
 ncFind.open=false;ncFindClear();
 if(placeCaret&&hit){
  if(hit.ta){if(!hit.ta.readOnly){try{hit.ta.focus({preventScroll:true});hit.ta.setSelectionRange(hit.s,hit.e)}catch(e){}}}
  else if(hit.r){const ed=(hit.r.startContainer.parentElement||hit.r.startContainer).closest?.('[contenteditable="true"]');if(ed){try{ed.focus({preventScroll:true});const s=window.getSelection();s.removeAllRanges();s.addRange(hit.r)}catch(e){}}}
 }
}
function ncFindClear(){
 if(ncHL){CSS.highlights.delete('nc-find');CSS.highlights.delete('nc-find-cur')}
 document.querySelectorAll('.nc-find-box').forEach(x=>x.remove());
 const t=ncFind.ta;ncFind.ta=null;ncFind.taHits=[];ncFind.taCurrent=-1;if(t)ncTaPaint(t);
 ncFind.hits=[];ncFind.cur=-1;
}
function ncFindCount(){const c=document.querySelector('#ncFind .nc-find-count');if(!c)return;c.textContent=!ncFind.q?'':ncFind.hits.length?(ncFind.cur+1)+' из '+ncFind.hits.length+(ncFind.hits.length>=2000?'+':''):'не найдено';c.classList.toggle('none',!!ncFind.q&&!ncFind.hits.length)}
function ncFindRun(keepIndex){
 const prevHit=ncFind.hits[ncFind.cur];ncFindClear();const q=ncNorm(ncFind.q);if(!q){ncFindCount();return}
 const scope=ncFindScope();const hits=[];
 if(scope.kind==='ta'){
  for(const ta of scope.list){const v=ncNorm(ta.value);let at=v.indexOf(q);while(at>=0&&hits.length<2000){hits.push({ta,s:at,e:at+q.length});at=v.indexOf(q,at+Math.max(1,q.length))}}
 }else if(scope.el){
  const {nodes,text}=markTextNodes(scope.el);const v=ncNorm(text);
  const skip=n=>{const p=n.parentElement;return !p||!!p.closest('[data-flow-divider],script,style,button,select,option,textarea,.nc-find,[hidden]')};
  let at=v.indexOf(q),ni=0;
  while(at>=0&&hits.length<2000){
   const end=at+q.length;while(ni<nodes.length-1&&nodes[ni+1][1]<=at)ni++;
   let si=ni,ei=ni;while(ei<nodes.length-1&&nodes[ei+1][1]<end)ei++;
   const [sn,sa]=nodes[si],[en,ea]=nodes[ei];
   if(!skip(sn)){try{const r=document.createRange();r.setStart(sn,at-sa);r.setEnd(en,end-ea);if(r.getClientRects().length||ui.tab==='reader')hits.push({r})}catch(e){}}
   at=v.indexOf(q,at+Math.max(1,q.length));
  }
 }
 ncFind.hits=hits;
 let idx=0;
 if(keepIndex===true&&prevHit){idx=Math.min(hits.length-1,Math.max(0,ncFind.cur))}
 else if(scope.kind==='dom'&&hits.length&&ui.tab!=='reader'){const topY=(document.querySelector('#ncTabs:not([hidden])')?.getBoundingClientRect().bottom||document.querySelector('.topbar')?.getBoundingClientRect().bottom||0);const i=hits.findIndex(h=>h.r.getBoundingClientRect().bottom>topY);if(i>=0)idx=i}
 ncFind.cur=hits.length?idx:-1;
 if(ncHL&&scope.kind==='dom'&&hits.length)CSS.highlights.set('nc-find',new Highlight(...hits.slice(0,2000).map(h=>h.r)));
 ncFindShow(keepIndex!==true);
}
function ncFindStep(d){if(!ncFind.hits.length){if(ncFind.q)ncFindRun(0);return}ncFind.cur=(ncFind.cur+d+ncFind.hits.length)%ncFind.hits.length;ncFindShow(true)}
function ncFindShow(scroll){
 ncFindCount();document.querySelectorAll('.nc-find-box').forEach(x=>x.remove());
 const hit=ncFind.hits[ncFind.cur];if(ncHL)CSS.highlights.delete('nc-find-cur');
 if(!hit){if(ncFind.ta){const t=ncFind.ta;ncFind.ta=null;ncTaPaint(t)}return}
 if(hit.ta){
  const ta=hit.ta,same=ncFind.hits.filter(h=>h.ta===ta);
  if(ncFind.ta&&ncFind.ta!==ta){const old=ncFind.ta;ncFind.ta=null;ncTaPaint(old)}
  ncFind.ta=ta;ncFind.taHits=same.map(h=>[h.s,h.e]);ncFind.taCurrent=same.indexOf(hit);
  if(scroll)ncTaScrollTo(ta,hit.s,'nc-mk-find-cur');else ncTaPaint(ta);return;
 }
 if(ncHL)CSS.highlights.set('nc-find-cur',new Highlight(hit.r));
 if(scroll){
  if(ui.tab==='reader'&&ui.readerView!=='continuous'){const paged=document.querySelector('#readerPagedContent'),g=paged&&readerGeometry(paged);if(g){const pr=paged.getBoundingClientRect(),er=hit.r.getBoundingClientRect(),abs=er.left-pr.left+Math.round((ui.readerSpreadIndex||0)*g.step);const want=Math.max(0,Math.min(g.maxIndex,Math.floor(abs/g.step)));if(want!==ui.readerSpreadIndex){ui.readerSpreadIndex=want;readerApplyPosition()}}}
  ncScrollRangeIntoView(hit.r);
 }
 requestAnimationFrame(()=>ncFindBox(hit.r));
}
function ncFindBox(r){document.querySelectorAll('.nc-find-box').forEach(x=>x.remove());if(!ncFind.open||!r)return;[...r.getClientRects()].slice(0,6).forEach(q=>{if(!q.width&&!q.height)return;const d=document.createElement('div');d.className='nc-find-box';d.style.cssText=`left:${q.left-2}px;top:${q.top-1}px;width:${q.width+4}px;height:${q.height+2}px`;document.body.append(d)})}
function ncFindRefresh(afterRender){if(!ncFind.open)return;if(afterRender){ncFind.hits=[];ncFind.cur=-1}ncFindRun(afterRender?0:true)}
window.addEventListener('scroll',()=>{if(ncFind.open){const h=ncFind.hits[ncFind.cur];if(h?.r)ncFindBox(h.r)}},{passive:true,capture:true});
window.addEventListener('resize',()=>{if(ncFind.open){const h=ncFind.hits[ncFind.cur];if(h?.r)ncFindBox(h.r)}});
document.addEventListener('input',e=>{if(!ncFind.open||e.target.closest?.('#ncFind'))return;if(e.target.closest?.('[data-chapter-document],[data-lab-draft-editor]')){clearTimeout(ncFindRefresh.t);ncFindRefresh.t=setTimeout(()=>ncFindRefresh(false),350)}},true);
window.addEventListener('keydown',e=>{
 const mod=e.metaKey||e.ctrlKey;
 if(document.querySelector('#ncGuide'))return;
 if(mod&&!e.altKey&&e.code==='KeyF'){if(document.querySelector('#ncAskVeil'))return;e.preventDefault();e.stopPropagation();ncFindOpen();return}
 if(mod&&!e.altKey&&e.code==='KeyG'&&ncFind.open){e.preventDefault();ncFindStep(e.shiftKey?-1:1);return}
 if(e.key==='Escape'&&ncFind.open&&!document.querySelector('#ncAskVeil')){e.preventDefault();e.stopImmediatePropagation();ncFindClose(!!e.target.closest?.('#ncFind'))}
},true);
/* Для автоматических проверок: только чтение. */
window.__ncDebug={get ui(){return ui},get state(){return state},book:()=>book()};

/* ——— RC3.8.3: первое окно — красивое приветствие и место хранения книг и копий;
       раз в неделю напоминание сохранить полный архив вне компьютера. ——— */
function profileWelcome(){
 const v=document.querySelector('#veil');if(!v||v.classList.contains('open'))return;
 const cap=v.querySelector('.modalhead .cap'),oldCap=cap?cap.textContent:'';
 if(cap){cap.textContent='Знакомство';const mo=new MutationObserver(()=>{if(!v.classList.contains('open')){cap.textContent=oldCap;mo.disconnect()}});mo.observe(v,{attributes:true,attributeFilter:['class']})}
 document.querySelector('#modalTitle').textContent='Добро пожаловать в NOCTURNE';
 const remind=ncBackupState().enabled!==false;
 document.querySelector('#modalBody').innerHTML=`<form id="profileWelcome" class="nc-welcome" onsubmit="return false">
 <div class="nc-welcome-hero"><div class="nc-welcome-moon" aria-hidden="true">☾</div><p class="nc-welcome-motto">Твои истории оживут здесь.</p><p class="nc-welcome-sub">Каждая глава, каждый герой и каждая ночная мысль найдут здесь свой дом.</p></div>
 <p>Несколько вопросов, чтобы NOCTURNE говорил с тобой правильно и надёжно берёг книги. Всё это можно поменять в любой момент в разделе «Настройки и данные».</p>
 <div class="field" style="margin-top:16px"><label>Как к тебе обращаться?</label>${profileChoiceHtml(state.profile?.address||'')}</div>
 <div class="field"><label for="profileAuthorName">Имя автора на страницах книг</label><input type="text" id="profileAuthorName" maxlength="100" placeholder="Например, Анна Северина" value="${esc(state.profile?.authorName||'')}"><small class="muted">Будет стоять в колонтитулах на «Письменном столе» и в «Читать рукопись». Можно оставить пустым.</small></div>
 <div class="field nc-welcome-store"><label>Где хранить книги</label><div class="settings-path" data-nc-welcome-path="data">Читаем папку…</div><button type="button" class="btn small" data-nc-welcome-folder="data">⌑ Выбрать другую папку</button><small class="muted">Обычно это «Документы → NOCTURNE». Если выбираешь другую, бери пустую папку: NOCTURNE перенесёт туда книги.</small></div>
 <div class="field nc-welcome-store"><label>Куда класть резервные копии</label><div class="settings-path" data-nc-welcome-path="backup">Читаем папку…</div><button type="button" class="btn small" data-nc-welcome-folder="backup">⌑ Выбрать папку копий</button><small class="muted">NOCTURNE сам делает копию раз в час. Надёжнее всего выбрать папку, которая синхронизируется с облаком (iCloud Drive, Яндекс Диск, Google Drive): тогда копии будут храниться и вне компьютера.</small></div>
 <label class="nc-check"><input type="checkbox" id="ncWelcomeRemind" ${remind?'checked':''}> Раз в неделю напоминать сохранить полный архив на другое устройство или в облако</label>
 <div class="modalfoot"><button type="button" class="btn gold" data-act="profile-save">Начать</button></div></form>`;
 v.classList.add('open');ncWelcomePaths();
}
function ncWelcomePaths(){if(typeof storageSettings!=='function')return;storageSettings().then(x=>{const a=document.querySelector('[data-nc-welcome-path="data"]'),b=document.querySelector('[data-nc-welcome-path="backup"]');if(a)a.textContent=x.dataDir||'—';if(b)b.textContent=x.backupDir||'—'}).catch(()=>{document.querySelectorAll('[data-nc-welcome-path]').forEach(x=>x.textContent='Папка недоступна в этой версии')})}
document.addEventListener('click',e=>{const f=e.target.closest('[data-nc-welcome-folder]');if(!f)return;e.preventDefault();e.stopPropagation();Promise.resolve(changeStorage(f.dataset.ncWelcomeFolder)).finally(()=>setTimeout(ncWelcomePaths,300))});
/* Галочка из первого окна сохраняется вместе с ответами (до основного обработчика). */
window.addEventListener('click',e=>{const b=e.target.closest?.('[data-act="profile-save"]');if(!b)return;const c=document.querySelector('#ncWelcomeRemind');if(c){ncBackupState().enabled=c.checked}},true);

function ncBackupState(){if(!state.backupReminder||typeof state.backupReminder!=='object')state.backupReminder={enabled:true,lastZipAt:0,lastRemindAt:Date.now()};return state.backupReminder}
var NC_WEEK=7*24*3600*1000;
function ncBackupDue(){const s=ncBackupState();return s.enabled!==false&&Date.now()-Math.max(Number(s.lastZipAt)||0,Number(s.lastRemindAt)||0)>=NC_WEEK}
function ncBackupRemind(force){
 if(document.querySelector('#ncBackupCard'))return;
 if(!force&&(!ncBackupDue()||ui.writerZen||document.querySelector('#veil.open,#ncAskVeil')))return;
 const s=ncBackupState(),last=Number(s.lastZipAt)||0;
 const card=document.createElement('div');card.id='ncBackupCard';card.className='nc-backup-remind';card.setAttribute('role','alertdialog');card.setAttribute('aria-label','Напоминание о резервной копии');
 card.innerHTML=`<button type="button" class="nc-backup-x" data-nc-backup="later" aria-label="Напомнить позже">×</button><div class="nc-backup-head">☁ Пора сохранить копию вне компьютера</div><p>Автокопии NOCTURNE лежат на этом же компьютере. Если с ним что-то случится, книги спасёт только копия на флешке, другом устройстве или в облаке.</p><p class="tiny muted">${last?'Последний полный архив: '+new Date(last).toLocaleDateString('ru-RU',{day:'numeric',month:'long'}):'Полный архив ещё ни разу не создавался.'}</p><div class="nc-widget-row"><button type="button" class="btn small gold" data-nc-backup="zip">⇩ Сделать полный архив</button><button type="button" class="btn small" data-nc-backup="later">Напомнить через неделю</button></div><button type="button" class="nc-backup-off" data-nc-backup="off">Не напоминать (включить снова — в «Настройках и данных»)</button>`;
 document.body.append(card);
}
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-nc-backup]');if(!b)return;e.preventDefault();e.stopPropagation();
 const s=ncBackupState(),a=b.dataset.ncBackup;document.querySelector('#ncBackupCard')?.remove();
 if(a==='zip'){s.lastRemindAt=Date.now();persist();backup().then(()=>notify('Архив в папке «Загрузки». Перенеси его на флешку, другой компьютер или в облако.'))}
 else if(a==='later'){s.lastRemindAt=Date.now();persist()}
 else if(a==='off'){s.enabled=false;persist();notify('Напоминания выключены. Включить — «Настройки и данные»')}
});
/* Полный ZIP из любого места считается сделанной копией. */
window.addEventListener('click',e=>{if(e.target.closest?.('[data-act="backup"]')){ncBackupState().lastZipAt=Date.now();persist()}},true);
document.addEventListener('change',e=>{if(e.target.matches?.('[data-nc-backup-remind]')){const s=ncBackupState();s.enabled=e.target.checked;if(s.enabled)s.lastRemindAt=Date.now();persist();notify(s.enabled?'Буду напоминать раз в неделю':'Напоминания выключены')}});
function ncBackupSettingsCard(){
 const s=ncBackupState(),last=Number(s.lastZipAt)||0;
 return `<div class="goal-card nc-backup-settings"><div class="cap">Копия вне компьютера</div><h3>Раз в неделю — архив на другое устройство</h3><p class="mini-help">Автоматические копии лежат на этом же компьютере. Они спасают от случайных ошибок, но не от поломки, кражи или потери ноутбука. Поэтому раз в неделю создавай полный ZIP и сохраняй его на флешку, другой компьютер или в облако. Ещё надёжнее — выбрать папкой копий папку, которая синхронизируется с облаком (iCloud Drive, Яндекс Диск, Google Drive).</p><label class="nc-check"><input type="checkbox" data-nc-backup-remind ${s.enabled!==false?'checked':''}> Напоминать раз в неделю</label><p class="tiny muted">${last?'Последний полный архив: '+new Date(last).toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'}):'Полный архив ещё ни разу не создавался.'}</p><button class="btn gold" data-act="backup">⇩ Создать полный ZIP сейчас</button></div>`;
}
setTimeout(()=>{try{ncBackupState();ncBackupRemind(false)}catch(e){}},9000);
setInterval(()=>{try{ncBackupRemind(false)}catch(e){}},3*3600*1000);
