/* ——— RC3.8.4: «Писательский ритм» — итоги прошлого месяца и статистика по месяцам. ——— */
var NC_M_NOM=['Январь','Февраль','Март','Апрель','Май','Июнь','Июль','Август','Сентябрь','Октябрь','Ноябрь','Декабрь'];
var NC_M_IN=['январе','феврале','марте','апреле','мае','июне','июле','августе','сентябре','октябре','ноябре','декабре'];
var NC_M_GEN=['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'];
var NC_M_DAT=['январю','февралю','марту','апрелю','маю','июню','июлю','августу','сентябрю','октябрю','ноябрю','декабрю'];
function ncPl(n,f){n=Math.abs(Math.round(n));const a=n%10,b=n%100;return f[a===1&&b!==11?0:a>=2&&a<=4&&(b<12||b>14)?1:2]}
function ncMonthKey(y,m){return y+'-'+String(m+1).padStart(2,'0')}
function ncMonthData(y,m){
 const unit=ncHabitUnit(),target=Math.max(1,Number(state.writingHabit?.target)||1500);
 const days=new Date(y,m+1,0).getDate(),today=dateLocal();
 let total=0,words=0,chars=0,written=0,norm=0,best=0,bestDay=0,streak=0,run=0,recorded=0;
 for(let d=1;d<=days;d++){
  const key=dateLocal(new Date(y,m,d));if(key>today)break;
  const row=state.writingDays?.[key];if(row)recorded++;
  const v=row?dailyTotal(key,unit):0;total+=v;if(row){words+=dailyTotal(key,'words');chars+=dailyTotal(key,'characters')}
  if(v>0){written++;run++;if(run>streak)streak=run}else run=0;
  if(v>=target)norm++;if(v>best){best=v;bestDay=d}
 }
 const mk=ncMonthKey(y,m);const focus=(state.focusSessions||[]).filter(x=>String(x.date||'').startsWith(mk)).reduce((n,x)=>n+(Number(x.minutes)||0),0);
 return {y,m,days,unit,target,total,words,chars,written,norm,best,bestDay,streak,recorded,focus};
}
function ncUnitWord(unit,n){return unit==='words'?ncPl(n,['слово','слова','слов']):unit==='nospace'?ncPl(n,['знак','знака','знаков'])+' без пробелов':ncPl(n,['знак','знака','знаков'])}
function ncPick(list,seed){let h=0;for(const c of String(seed))h=(h*31+c.charCodeAt(0))>>>0;return list[h%list.length]}
function ncMonthSummary(){
 const now=new Date(),py=now.getMonth()?now.getFullYear():now.getFullYear()-1,pm=now.getMonth()?now.getMonth()-1:11;
 const keys=Object.keys(state.writingDays||{}).sort(),first=keys[0]||dateLocal();
 const prevEnd=dateLocal(new Date(py,pm+1,0));
 if(first>prevEnd){
  const f=new Date(first+'T12:00:00');
  return `<div class="nc-month-summary empty"><div class="cap">Итоги ${NC_M_GEN[pm]}</div><p class="nc-month-line">Твой первый месяц в NOCTURNE ещё пишется.</p><p class="muted">Статистика ведётся с ${f.getDate()} ${NC_M_GEN[f.getMonth()]}. Когда месяц закончится, здесь появятся его итоги: сколько ${gs('ты написала','ты написал')}, сколько дней ${gs('писала','писал')} и какой день был самым щедрым.</p></div>`;
 }
 const P=ncMonthData(py,pm),U=P.unit;
 const ppy=pm?py:py-1,ppm=pm?pm-1:11,PP=ncMonthData(ppy,ppm);
 const pages=U==='words'?Math.round(P.total/250):U==='nospace'?Math.round(P.total/1500):Math.round(P.total/1800);
 const seed=ncMonthKey(py,pm);
 let line,tail;
 if(P.total<=0){
  line=`В ${NC_M_IN[pm]} история отдыхала.`;
  tail=ncPick(['Зато теперь она соскучилась — самое время вернуться к ней.','Тишина тоже часть работы: мысли зреют, пока руки отдыхают. Новый месяц — новая страница.','Ничего страшного: история дождалась. Открой её — она помнит, на чём вы остановились.'],seed);
 }else{
  line=`В ${NC_M_IN[pm]} ${gs('ты написала','ты написал')} ${fmtNum(P.total)} ${ncUnitWord(U,P.total)}`+(pages>=1?` — это около ${fmtNum(pages)} ${ncPl(pages,['страницы','страниц','страниц'])} новой истории`:'')+'.';
  const sheets=U==='characters'?P.total/40000:0;
  tail=sheets>=1?ncPick([`Больше ${Math.floor(sheets)>1?fmtNum(Math.floor(sheets))+' '+ncPl(Math.floor(sheets),['авторского листа','авторских листов','авторских листов']):'авторского листа'} — книга растёт на глазах.`,'Целый авторский лист и больше — так пишутся романы.'],seed)
   :P.total>=5000?ncPick(['Каждый из этих дней приблизил последнюю точку.','Страница за страницей — так и рождаются книги.','История стала больше и живее. Это твоя работа.'],seed)
   :ncPick(['Даже несколько строк — это движение. История помнит каждую.','Маленькие шаги тоже ведут к последней странице.','Начало положено — дальше будет легче.'],seed);
 }
 const chips=[];
 if(P.written)chips.push(`✒ ${P.written} ${ncPl(P.written,['день','дня','дней'])} с текстом из ${P.days}`);
 if(P.norm)chips.push(`◉ норма выполнена ${P.norm} ${ncPl(P.norm,['раз','раза','раз'])}`);
 if(P.streak>1)chips.push(`🔥 ${P.streak} ${ncPl(P.streak,['день','дня','дней'])} подряд`);
 if(P.best)chips.push(`★ лучший день — ${P.bestDay} ${NC_M_GEN[pm]}: ${fmtNum(P.best)} ${ncUnitWord(U,P.best)}`);
 if(P.focus)chips.push(`☾ ${fmtNum(P.focus)} ${ncPl(P.focus,['минута','минуты','минут'])} в фокусе`);
 if(PP.total>0&&P.total>0){const d=Math.round((P.total-PP.total)/PP.total*100);if(Math.abs(d)>=5)chips.push(d>0?`↗ на ${d}% больше, чем в ${NC_M_IN[ppm]}`:`↘ на ${-d}% меньше, чем в ${NC_M_IN[ppm]}`)}
 return `<div class="nc-month-summary"><div class="cap">Итоги ${NC_M_GEN[pm]}</div><p class="nc-month-line">${esc(line)}</p><p class="nc-month-tail">${esc(tail)}</p>${chips.length?`<div class="nc-month-chips">${chips.map(c=>`<span>${esc(c)}</span>`).join('')}</div>`:''}</div>`;
}
function ncMonthTable(){
 const now=new Date(),keys=Object.keys(state.writingDays||{}).sort(),first=keys[0]||dateLocal();
 const f=new Date(first+'T12:00:00');let y=now.getFullYear(),m=now.getMonth();const rows=[];
 for(let i=0;i<12;i++){if(y<f.getFullYear()||(y===f.getFullYear()&&m<f.getMonth()))break;rows.push(ncMonthData(y,m));if(--m<0){m=11;y--}}
 const max=Math.max(1,...rows.map(r=>r.total)),U=rows[0]?.unit||'characters',thisYear=now.getFullYear();
 const unitHead=U==='words'?'Слов':U==='nospace'?'Знаков без пробелов':'Знаков';
 return `<div class="nc-month-table" role="table" aria-label="Статистика по месяцам"><div class="nc-mrow head" role="row"><span role="columnheader">Месяц</span><span role="columnheader">${unitHead}</span><span role="columnheader">Дней с текстом</span><span role="columnheader">Норма</span><span role="columnheader">Лучший день</span><span role="columnheader">В фокусе</span></div>${rows.map((r,i)=>`<div class="nc-mrow ${i===0?'current':''}" role="row"><span role="cell">${NC_M_NOM[r.m]}${r.y!==thisYear?' '+r.y:''}${i===0?' <small>идёт</small>':''}</span><span role="cell" class="nc-mbar"><span class="nc-mtrack"><i style="width:${Math.max(r.total?2:0,Math.round(r.total/max*100))}%"></i></span><b>${fmtNum(r.total)}</b></span><span role="cell">${r.written}</span><span role="cell">${r.norm}</span><span role="cell">${r.best?fmtNum(r.best):'—'}</span><span role="cell">${r.focus?fmtNum(r.focus)+' мин':'—'}</span></div>`).join('')}</div>`;
}
function ncMonthCard(){
 try{return `<div class="goal-card nc-month-card"><div class="cap">Итоги и статистика</div><h3>Месяц за месяцем</h3>${ncMonthSummary()}<h4 class="nc-month-h">Статистика по месяцам</h4>${ncMonthTable()}<p class="mini-help">Считается прирост текста по всем книгам за каждый день — так же, как в календаре выше. «Норма» — сколько дней дневная норма была выполнена. «В фокусе» — минуты завершённых сеансов таймера письма.</p></div>`}
 catch(e){window.__ncLog?.('month card: '+(e&&e.stack||e));return ''}
}
/* ——— RC3.8.5: как считать написанное — знаки с пробелами, знаки без пробелов или слова.
       Одно правило для дневной нормы, календаря, итогов месяца и счётчика на «Письменном столе»;
       у цели каждой книги своя единица. ——— */
function ncUnitOk(u){return u==='characters'||u==='nospace'||u==='words'}
function ncHabitUnit(){const u=state?.writingHabit?.unit;return u==='words'||u==='nospace'?u:'characters'}
function ncUnitGen(u){return u==='words'?'слов':u==='nospace'?'знаков без пробелов':'знаков'}
function ncUnitTitle(u){return u==='words'?'Слова':u==='nospace'?'Знаки без пробелов':'Знаки с пробелами'}
function ncNormLabel(u){return 'Сколько '+(u==='words'?'слов':u==='nospace'?'знаков без пробелов':'знаков с пробелами')+' в день'}
function ncUnitList(){return [
 {value:'characters',label:'Знаки с пробелами',hint:'Как считают издательства: авторский лист — 40 000 знаков'},
 {value:'nospace',label:'Знаки без пробелов',hint:'Только буквы, цифры и знаки препинания'},
 {value:'words',label:'Слова',hint:'Удобно для писательских марафонов'}]}
function ncNoSpace(x){const s=String(x||'');return s?s.replace(/\s+/g,'').length:0}
var ncNSW;
function ncNSofCh(ch){const s=ch?.plain||'';if(!s)return 0;if(!ncNSW)ncNSW=new WeakMap();const c=ncNSW.get(ch);if(c&&c.s===s)return c.n;const n=ncNoSpace(s);ncNSW.set(ch,{s,n});return n}
function ncCountOf(t,unit=ncHabitUnit()){return unit==='words'?words(t):unit==='nospace'?ncNoSpace(t):charCount(t)}
var ncRatioMemo;
function ncRatio(b){
 if(!b)return 0.85;if(!ncRatioMemo)ncRatioMemo=new Map();let rev=0;try{rev=lifeHistoryRevision}catch(e){}
 const m=ncRatioMemo.get(b.id);if(m&&m.rev===rev)return m.r;
 const c=totalOf(b,'characters'),r=c>200?Math.min(1,Math.max(.6,totalOf(b,'nospace')/c)):.85;ncRatioMemo.set(b.id,{rev,r});return r;
}
/* Дни до RC3.8.5 хранят только знаки с пробелами и слова: «без пробелов» для них — оценка по доле пробелов в книге. */
function ncEarned(v,unit,id){
 if(!v)return 0;if(unit!=='nospace')return Number(v[unit])||0;
 if(v.nospace!=null)return Number(v.nospace)||0;
 const c=Number(v.characters)||0;return c?Math.round(c*ncRatio(state.books.find(x=>x.id===id))):0;
}
function dailyTotal(day,unit=ncHabitUnit()){const e=state.writingDays?.[day]?.earned||{};let s=0;for(const id in e)s+=ncEarned(e[id],unit,id);return s}
function statsInit(){
 state.writingHabit??={unit:'characters',target:1500};state.writingDays??={};state.collapsedWorlds??={};state.libraryBannerImage??='';
 state.books.forEach(b=>{b.headerImage??='';b.goal??={unit:'characters',target:0,deadline:''}});
 const day=dateLocal();let row=state.writingDays[day];if(!row){row={baseline:{},earned:{}};state.writingDays[day]=row}
 row.baseline??={};row.earned??={};
 state.books.forEach(b=>{
  const bl=row.baseline[b.id]??={characters:totalOf(b,'characters'),words:totalOf(b,'words'),nospace:totalOf(b,'nospace')};
  if(bl.nospace==null){const e=Number(row.earned[b.id]?.characters)||0;bl.nospace=Math.max(0,totalOf(b,'nospace')-Math.round(e*ncRatio(b)))}
  const er=row.earned[b.id]??={characters:0,words:0,nospace:0};
  if(er.nospace==null)er.nospace=Math.max(0,totalOf(b,'nospace')-bl.nospace);
 });
 const keys=Object.keys(state.writingDays).sort();for(let i=0;i<keys.length-366;i++)delete state.writingDays[keys[i]];
}
function recordWriting(){
 statsInit();lifeHistoryRevision++;const day=state.writingDays[dateLocal()];const lb=book();
 if(lb){
  const base=day.baseline[lb.id]||(day.baseline[lb.id]={characters:0,words:0,nospace:0});
  const nowC=totalOf(lb,'characters'),nowW=totalOf(lb,'words'),nowN=totalOf(lb,'nospace');
  if(base.nospace==null)base.nospace=nowN;
  /* RC3.7.1: удалённый сегодня текст не создаёт «долг» — точка отсчёта опускается вместе с объёмом книги */
  if(nowC<base.characters)base.characters=nowC;if(nowW<base.words)base.words=nowW;if(nowN<base.nospace)base.nospace=nowN;
  day.earned[lb.id]={characters:Math.max(0,nowC-base.characters),words:Math.max(0,nowW-base.words),nospace:Math.max(0,nowN-base.nospace)};
  const life=lifeOf(lb),habit=state.writingHabit||{},target=Number(habit.target)||1500,current=ncEarned(day.earned[lb.id],ncHabitUnit(),lb.id);
  const stage=current>=target*1.5?'extra':current>=target?'done':current>=target*.7?'near':current>0?'writing':'welcome';
  if(life.dailyEchoDate!==dateLocal()){life.dailyEchoDate=dateLocal();life.dailyEchoStage=''}
  if(stage!==life.dailyEchoStage){life.dailyEchoStage=stage;lifeSay(lb,stage==='writing'?'small':stage)}
  if(lifeCheck(lb))persist();
 }
 refreshHabitRings();
}
function lifeHistorySummary(){
 const src=state.writingDays||{};
 if(lifeHistoryCache&&lifeHistoryCache.src===src&&lifeHistoryCache.revision===lifeHistoryRevision)return lifeHistoryCache;
 const daysByBook=new Map(),maxByBook=new Map();
 for(const [day,row] of Object.entries(src)){
  for(const [id,earned] of Object.entries(row?.earned||{})){
   const chars=Number(earned?.characters)||0,wc=Number(earned?.words)||0;
   if(chars<=0&&wc<=0)continue;
   let days=daysByBook.get(id);if(!days){days=[];daysByBook.set(id,days)}days.push(day);
   let max=maxByBook.get(id);if(!max){max={characters:0,words:0,nospace:0};maxByBook.set(id,max)}
   max.characters=Math.max(max.characters,chars);max.words=Math.max(max.words,wc);max.nospace=Math.max(max.nospace,ncEarned(earned,'nospace',id));
  }
 }
 for(const arr of daysByBook.values())arr.sort();
 lifeHistoryCache={src,revision:lifeHistoryRevision,daysByBook,maxByBook};return lifeHistoryCache;
}
function ncConvertNorm(n,from,to){
 if(from===to)return n;const perWord=7,ratio=.85;
 const c=from==='words'?n*perWord:from==='nospace'?n/ratio:n,r=to==='words'?c/perWord:to==='nospace'?c*ratio:c,step=to==='words'?10:50;
 return Math.max(step,Math.round(r/step)*step);
}
function ncSetCountUnit(unit){
 if(!ncUnitOk(unit))return;state.writingHabit??={unit:'characters',target:1500};
 const h=state.writingHabit,from=ncHabitUnit();if(unit===from)return;
 h.target=ncConvertNorm(Number(h.target)||1500,from,unit);h.unit=unit;try{lifeHistoryRevision++}catch(e){}
 persist();render();notify(ncUnitTitle(unit)+' — дневная норма теперь '+fmtNum(h.target)+' '+ncUnitWord(unit,h.target));
}
function ncCountSettingsCard(){
 const u=ncHabitUnit();
 return `<div class="goal-card nc-count-settings"><div class="cap">Подсчёт текста</div><h3>Как считать написанное</h3><p class="mini-help">По этому правилу считаются дневная норма, календарь, итоги месяца и счётчик главы на «Письменном столе». У цели каждой книги своя единица — она выбирается в «Ритме письма». Дневная норма пересчитается сама, её можно поправить кнопкой «⚙ Изменить норму».</p><div class="nc-ask-choices nc-count-choices" role="radiogroup" aria-label="Как считать написанное">${ncUnitList().map(c=>`<label class="nc-radio"><input type="radio" name="ncCountUnit" value="${c.value}" data-nc-count-unit ${c.value===u?'checked':''}><span><b>${esc(c.label)}</b><small>${esc(c.hint)}</small></span></label>`).join('')}</div></div>`;
}
document.addEventListener('change',e=>{const r=e.target.closest?.('[data-nc-count-unit]');if(r&&r.checked)ncSetCountUnit(r.value)});
/* Счётчик главы на «Письменном столе»: выбранная единица, а при наведении — все три числа. */
function ncCountTitle(t){const w=words(t),c=charCount(t),n=ncNoSpace(t);return `${fmtNum(w)} ${ncPl(w,['слово','слова','слов'])} · ${fmtNum(c)} ${ncPl(c,['знак','знака','знаков'])} с пробелами · ${fmtNum(n)} без пробелов`}
function ncDeskCounter(t){const u=ncHabitUnit(),n=ncCountOf(t,u);return `<span id="chapterCountWrap" title="${esc(ncCountTitle(t))}"><span id="chapterWordCount">${fmtNum(n)}</span> <span id="chapterUnitLabel">${ncUnitWord(u,n)}</span></span>`}
function ncDeskCountUpdate(t){
 try{setTimeout(ncDeskBarCount,0)}catch(e){}
 const u=ncHabitUnit(),n=ncCountOf(t,u);
 const c=document.querySelector('#chapterWordCount');if(c)c.textContent=fmtNum(n);
 const l=document.querySelector('#chapterUnitLabel');if(l)l.textContent=ncUnitWord(u,n);
 const w=document.querySelector('#chapterCountWrap');if(w)w.title=ncCountTitle(t);
}

/* ——— RC3.8.5: путеводитель всегда под рукой — кнопка внизу бокового меню.
       Показывает встроенный текст этой версии программы; книгу-путеводитель в библиотеке не трогает. ——— */
var ncGuideList=null,ncGuideAt=0,ncGuideQ='',ncGuideHits=[],ncGuideHitAt=0,ncGuidePrev=null;
function ncGuideChapters(){
 if(ncGuideList)return ncGuideList;
 const g=JSON.parse(JSON.stringify(NOCTURNE_GUIDE)),win=g._win;
 if(Array.isArray(win)&&window.__NOCTURNE_NATIVE?.platform==='windows')win.forEach(([p,v])=>{let o=g;for(let i=0;i<p.length-1&&o;i++)o=o[p[i]];if(o)o[p[p.length-1]]=v});
 ncGuideList=(((g.books||[])[0]||{}).chapters||[]).map((c,i)=>({i,title:c.title||'',summary:c.summary||'',rich:c.rich||'',key:ncNorm((c.title||'')+'\n'+(c.summary||'')+'\n'+(c.plain||''))}));
 return ncGuideList;
}
function ncGuideOpen(i){
 const list=ncGuideChapters();if(!list.length){notify('Путеводитель не найден');return}
 if(i==null){try{i=Number(JSON.parse(localStorage.getItem('nocturne.guide.v1')||'{}').i)||0}catch(e){i=0}}
 ncGuideAt=Math.max(0,Math.min(list.length-1,Number(i)||0));
 let v=document.querySelector('#ncGuide');
 if(!v){
  ncGuidePrev=document.activeElement;
  v=document.createElement('div');v.id='ncGuide';v.className='nc-guide-veil';v.setAttribute('role','dialog');v.setAttribute('aria-modal','true');v.setAttribute('aria-label','Путеводитель по NOCTURNE');
  v.innerHTML=`<div class="nc-guide"><aside class="nc-guide-nav"><div class="nc-guide-brand"><span>Путеводитель</span><b>NOCTURNE</b></div><input type="search" class="nc-guide-search" placeholder="Найти в путеводителе" aria-label="Найти в путеводителе" data-nc-guide-q autocomplete="off" spellcheck="false"><div class="nc-guide-found" aria-live="polite"></div><ol class="nc-guide-list"></ol></aside><section class="nc-guide-main"><button type="button" class="nc-guide-close" data-nc-guide-close title="Закрыть (Esc)" aria-label="Закрыть путеводитель">×</button><div class="nc-guide-scroll"></div></section></div>`;
  document.body.append(v);
  const q=v.querySelector('[data-nc-guide-q]');q.value=ncGuideQ;
  q.addEventListener('input',()=>{ncGuideQ=q.value;ncGuideDrawList();ncGuideHighlight(true)});
  q.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();ncGuideNextHit(e.shiftKey?-1:1)}});
 }
 ncGuideDrawList();ncGuideDrawPage();ncGuideSave();
 setTimeout(()=>{try{v.querySelector('.nc-guide-scroll')?.focus({preventScroll:true})}catch(e){}},30);
}
function ncGuideSave(){try{localStorage.setItem('nocturne.guide.v1',JSON.stringify({i:ncGuideAt}))}catch(e){}}
function ncGuideClose(){
 const v=document.querySelector('#ncGuide');if(!v)return;v.remove();
 try{CSS.highlights?.delete('nc-guide-hit');CSS.highlights?.delete('nc-guide-cur')}catch(e){}
 try{if(ncGuidePrev&&ncGuidePrev.isConnected&&ncGuidePrev!==document.body)ncGuidePrev.focus({preventScroll:true})}catch(e){}
}
function ncGuideMatches(){const q=ncNorm(ncGuideQ.trim());return q?ncGuideChapters().filter(c=>c.key.includes(q)).map(c=>c.i):null}
function ncGuideDrawList(){
 const v=document.querySelector('#ncGuide');if(!v)return;const m=ncGuideMatches(),set=m&&new Set(m);
 v.querySelector('.nc-guide-list').innerHTML=ncGuideChapters().map(c=>`<li${set&&!set.has(c.i)?' hidden':''}><button type="button" data-nc-guide-ch="${c.i}" class="${c.i===ncGuideAt?'active':''}"><span>${c.i+1}</span>${esc(c.title)}</button></li>`).join('');
 v.querySelector('.nc-guide-found').textContent=m?(m.length?`Есть в ${m.length} ${ncPl(m.length,['главе','главах','главах'])} · Enter — дальше`:'Ничего не нашлось'):'';
}
function ncGuideDrawPage(){
 const v=document.querySelector('#ncGuide');if(!v)return;const list=ncGuideChapters(),c=list[ncGuideAt];if(!c)return;
 const prev=list[ncGuideAt-1],next=list[ncGuideAt+1],sc=v.querySelector('.nc-guide-scroll');
 sc.setAttribute('tabindex','-1');
 sc.innerHTML=`<article class="nc-guide-page"><div class="nc-guide-cap">Глава ${c.i+1} из ${list.length}</div><h2>${esc(c.title)}</h2>${c.summary?`<p class="nc-guide-sum">${esc(c.summary)}</p>`:''}<div class="nc-guide-body">${c.rich}</div><nav class="nc-guide-pager">${prev?`<button type="button" class="btn plain" data-nc-guide-ch="${prev.i}">‹ ${esc(prev.title)}</button>`:'<span></span>'}${next?`<button type="button" class="btn gold" data-nc-guide-ch="${next.i}">${esc(next.title)} ›</button>`:''}</nav></article>`;
 sc.scrollTop=0;
 v.querySelectorAll('.nc-guide-list [data-nc-guide-ch]').forEach(b=>b.classList.toggle('active',Number(b.dataset.ncGuideCh)===c.i));
 v.querySelector(`.nc-guide-list [data-nc-guide-ch="${c.i}"]`)?.scrollIntoView({block:'nearest'});
 ncGuideHighlight(true);
}
function ncGuideGo(i){ncGuideAt=Math.max(0,Math.min(ncGuideChapters().length-1,i));ncGuideSave();ncGuideDrawPage()}
function ncGuideHighlight(scroll){
 const v=document.querySelector('#ncGuide');if(!v)return;const hl=window.CSS&&CSS.highlights,q=ncNorm(ncGuideQ.trim());
 try{hl?.delete('nc-guide-hit');hl?.delete('nc-guide-cur')}catch(e){}
 ncGuideHits=[];ncGuideHitAt=0;if(!q)return;
 const root=v.querySelector('.nc-guide-page');if(!root)return;
 const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;
 while((n=w.nextNode())){if(n.parentElement?.closest('.nc-guide-pager'))continue;const t=ncNorm(n.data);let k=t.indexOf(q);while(k>=0){const r=document.createRange();r.setStart(n,k);r.setEnd(n,k+q.length);ncGuideHits.push(r);k=t.indexOf(q,k+q.length)}}
 try{if(hl&&window.Highlight&&ncGuideHits.length)hl.set('nc-guide-hit',new Highlight(...ncGuideHits))}catch(e){}
 if(scroll&&ncGuideHits[0])ncGuideShowHit(0);
}
function ncGuideShowHit(k){
 const r=ncGuideHits[k];if(!r)return;ncGuideHitAt=k;
 try{if(window.CSS&&CSS.highlights&&window.Highlight)CSS.highlights.set('nc-guide-cur',new Highlight(r))}catch(e){}
 const sc=document.querySelector('#ncGuide .nc-guide-scroll');if(!sc)return;
 const a=r.getBoundingClientRect(),b=sc.getBoundingClientRect();if(a.top<b.top+40||a.bottom>b.bottom-40)sc.scrollTop+=a.top-b.top-sc.clientHeight/3;
}
function ncGuideNextHit(dir){
 const m=ncGuideMatches();if(!m||!m.length)return;
 const k=ncGuideHitAt+dir;if(ncGuideHits.length&&k>=0&&k<ncGuideHits.length){ncGuideShowHit(k);return}
 const pos=m.indexOf(ncGuideAt);
 const j=pos>=0?m[(pos+dir+m.length)%m.length]:dir>0?(m.find(i=>i>ncGuideAt)??m[0]):([...m].reverse().find(i=>i<ncGuideAt)??m[m.length-1]);
 ncGuideGo(j);if(dir<0&&ncGuideHits.length)ncGuideShowHit(ncGuideHits.length-1);
}
document.addEventListener('click',e=>{
 if(e.target.closest?.('[data-nc-guide-open]')){e.preventDefault();e.stopPropagation();ncGuideOpen();return}
 const v=document.querySelector('#ncGuide');if(!v||!v.contains(e.target))return;
 const ch=e.target.closest('[data-nc-guide-ch]');if(ch){e.preventDefault();e.stopPropagation();ncGuideGo(Number(ch.dataset.ncGuideCh));return}
 if(e.target===v||e.target.closest('[data-nc-guide-close]')){e.preventDefault();e.stopPropagation();ncGuideClose()}
},true);
window.addEventListener('keydown',e=>{
 const v=document.querySelector('#ncGuide');if(!v||document.querySelector('#ncAskVeil'))return;
 const mod=e.metaKey||e.ctrlKey;
 if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();ncGuideClose();return}
 if(mod&&!e.altKey&&e.code==='KeyF'){e.preventDefault();e.stopImmediatePropagation();const q=v.querySelector('[data-nc-guide-q]');q.focus();q.select();return}
 if(mod&&!e.altKey&&e.code==='KeyG'){e.preventDefault();e.stopImmediatePropagation();ncGuideNextHit(e.shiftKey?-1:1);return}
 if(e.ctrlKey&&(e.key==='Tab'||/^Digit[1-9]$/.test(e.code||''))){e.preventDefault();e.stopImmediatePropagation();return}
 if(!mod&&!e.altKey&&!isTyping(e)&&(e.key==='ArrowRight'||e.key==='ArrowLeft')){e.preventDefault();e.stopImmediatePropagation();ncGuideGo(ncGuideAt+(e.key==='ArrowRight'?1:-1))}
},true);

/* ——— RC3.8.5: импорт темы прощает ответ нейросети — ```json-ограждения, пояснения вокруг кода,
       цвета в виде #abc или rgb(), отсутствие version. Код можно просто вставить, без файла. ——— */
function ncHex(v){
 v=String(v||'').trim();
 if(/^#?[0-9a-f]{6}$/i.test(v))return ('#'+v.replace('#','')).toLowerCase();
 if(/^#[0-9a-f]{8}$/i.test(v))return v.slice(0,7).toLowerCase();
 if(/^#[0-9a-f]{3}$/i.test(v))return ('#'+[...v.slice(1)].map(s=>s+s).join('')).toLowerCase();
 const m=v.match(/^rgba?\(\s*(\d+)[\s,]+(\d+)[\s,]+(\d+)/i);if(m)return '#'+[1,2,3].map(i=>Math.min(255,Number(m[i])).toString(16).padStart(2,'0')).join('');
 return null;
}
function ncThemeFromText(text,fallbackName){
 let t=String(text||'').replace(/^﻿/,'').trim();
 const a=t.indexOf('{'),b=t.lastIndexOf('}');if(a<0||b<=a)throw Error('в нём нет кода темы');
 let obj;try{obj=JSON.parse(t.slice(a,b+1))}catch(e){throw Error('код темы повреждён — попроси нейросеть прислать его заново')}
 if(obj&&obj.format&&obj.format!=='nocturne-theme')throw Error('это не тема NOCTURNE');
 const src=obj&&obj.colors&&typeof obj.colors==='object'?obj.colors:obj,base=themePaletteOfPreset('amber'),colors={};let got=0;
 for(const [key] of THEME_PALETTE_FIELDS){const hex=ncHex(src?.[key]);if(hex){colors[key]=hex;got++}else colors[key]=base[key]}
 if(got<Math.ceil(THEME_PALETTE_FIELDS.length/2))throw Error('в нём почти нет цветов темы');
 const name=(typeof obj.name==='string'&&obj.name.trim()?obj.name.trim():String(fallbackName||'').trim()||'Моя тема').slice(0,64);
 return {name,colors,missing:THEME_PALETTE_FIELDS.length-got};
}
function ncThemeAdd(t){
 const colors=safeThemePalette(t.colors);if(!colors)throw Error('некорректные цвета');
 state.customThemes??=[];const id='custom-'+uid(),th={id,name:t.name,base:'amber',colors};state.customThemes.push(th);
 ui.themeDraft={...th,colors:{...colors}};persist();ui.tab='themeatelier';render();
 notify('Тема «'+t.name+'» добавлена в «Мои темы»'+(t.missing?' (недостающие цвета — '+t.missing+' — взяты из янтарной)':'')+'. Нажми «Сохранить и применить», чтобы включить её.');
}
async function themeImport(file){
 if(!file)return;if(file.size>200000){notify('Файл темы слишком большой');return}
 try{ncThemeAdd(ncThemeFromText(await file.text(),String(file.name||'').replace(/\.[^.]+$/,'')))}catch(e){notify('Не удалось импортировать тему: '+e.message)}
}
async function ncThemePaste(){
 const v=await ncAsk({title:'Код темы',label:'Вставь сюда ответ нейросети целиком',multiline:true,rows:9,okText:'Добавить тему',hint:'Подойдёт и ответ с пояснениями вокруг: NOCTURNE сам найдёт в нём код темы.'});
 if(v===null||!String(v).trim())return;
 try{ncThemeAdd(ncThemeFromText(v,''))}catch(e){notify('Не удалось добавить тему: '+e.message)}
}
document.addEventListener('click',e=>{if(e.target.closest?.('[data-nc-theme-paste]')){e.preventDefault();e.stopPropagation();ncThemePaste()}},true);

/* ——— RC3.8.5: панель редактора всегда под рукой. Когда большая панель «Оформление и инструменты»
       уезжает вверх, над текстом остаётся узкая: Ж К Ч, подзаголовок, абзац, отметка места, поиск и счётчик.
       Отметка с клавиатуры: ⌘⇧M — отметить место, ⌘⇧K — к отметке (на Windows Ctrl+Shift+M / K). ——— */
function ncIsWin(){return window.__NOCTURNE_NATIVE?.platform==='windows'||(!window.__NOCTURNE_NATIVE&&/Windows/.test(navigator.userAgent))}
function ncKeys(k){return ncIsWin()?'Ctrl+Shift+'+k:'⌘⇧'+k}
function ncDeskBarEnsure(){
 let bar=document.querySelector('#ncDeskBar');if(bar)return bar;
 bar=document.createElement('div');bar.id='ncDeskBar';bar.className='nc-deskbar';bar.setAttribute('role','toolbar');bar.setAttribute('aria-label','Панель редактора');bar.hidden=true;
 const mod=ncIsWin()?'Ctrl+':'⌘';
 bar.innerHTML=`<button type="button" class="format-btn" data-rich-cmd="bold" title="Жирный (${mod}B)"><b>Ж</b></button><button type="button" class="format-btn" data-rich-cmd="italic" title="Курсив (${mod}I)"><i>К</i></button><button type="button" class="format-btn" data-rich-cmd="underline" title="Подчёркивание (${mod}U)"><u>Ч</u></button><span class="nc-deskbar-sep" aria-hidden="true"></span><button type="button" class="format-btn" data-rich-cmd="formatBlock" data-rich-value="h3" title="Подзаголовок сцены">Подзаголовок</button><button type="button" class="format-btn" data-rich-cmd="formatBlock" data-rich-value="p" title="Обычный абзац">Абзац</button><span class="nc-deskbar-sep" aria-hidden="true"></span><button type="button" class="btn small" data-nc-stop-set="chapter" title="Отметить место (${ncKeys('M')})">⚑ Отметить</button><button type="button" class="btn small" data-nc-stop-go="chapter" title="К отметке (${ncKeys('K')})">↧ К отметке</button><span class="nc-deskbar-sep" aria-hidden="true"></span><button type="button" class="btn small" data-nc-deskbar-find title="Поиск по тексту (${mod}F)" >⌕ Найти</button><span class="nc-deskbar-count" aria-live="off"></span>`;
 document.body.append(bar);return bar;
}
function ncDeskBarCount(){const b=document.querySelector('#ncDeskBar .nc-deskbar-count');if(!b)return;const c=document.querySelector('#chapterWordCount'),l=document.querySelector('#chapterUnitLabel');b.textContent=c?(c.textContent+' '+(l?.textContent||'')).trim():''}
var ncDeskBarRaf=0;
function ncDeskBarUpdate(){
 ncDeskBarRaf=0;
 const ed=document.querySelector('[data-chapter-document]'),paper=document.querySelector('.flow-paper')||ed;
 const off=ui.tab!=='desk'||!ed||!paper||document.querySelector('#ncGuide');
 if(off){const b=document.querySelector('#ncDeskBar');if(b)b.hidden=true;return}
 let limit=8;
 if(!ui.writerZen){const tabs=document.querySelector('#ncTabs'),top=document.querySelector('.topbar');const t=tabs&&tabs.offsetParent&&tabs.getBoundingClientRect().height?tabs.getBoundingClientRect().bottom:(top?top.getBoundingClientRect().bottom:0);limit=Math.max(8,Math.round(t)+8)}
 const pr=paper.getBoundingClientRect(),er=ed.getBoundingClientRect();
 const show=pr.top<limit+8&&er.bottom>limit+140;
 const b=ncDeskBarEnsure();
 if(show){const w=Math.min(Math.max(pr.width,600),window.innerWidth-16);b.style.top=limit+'px';b.style.left=Math.round(Math.max(8,Math.min(pr.left+pr.width/2-w/2,window.innerWidth-w-8)))+'px';b.style.width=Math.round(w)+'px';ncDeskBarCount()}
 if(b.hidden===show)b.hidden=!show;
}
function ncDeskBarSchedule(){if(!ncDeskBarRaf)ncDeskBarRaf=requestAnimationFrame(()=>{try{ncDeskBarUpdate()}catch(e){ncDeskBarRaf=0}})}
window.addEventListener('scroll',ncDeskBarSchedule,{passive:true});
window.addEventListener('resize',ncDeskBarSchedule);
document.addEventListener('mousedown',e=>{if(e.target.closest?.('#ncDeskBar [data-nc-deskbar-find]'))e.preventDefault()},true);
document.addEventListener('click',e=>{if(e.target.closest?.('#ncDeskBar [data-nc-deskbar-find]')){e.preventDefault();e.stopPropagation();ncFindOpen()}},true);
window.addEventListener('keydown',e=>{
 if(!(e.metaKey||e.ctrlKey)||!e.shiftKey||e.altKey||(e.code!=='KeyM'&&e.code!=='KeyK'))return;
 if(document.querySelector('#ncAskVeil,#ncGuide'))return;
 const set=e.code==='KeyM';
 if(ui.tab==='desk'&&document.querySelector('[data-chapter-document]')){e.preventDefault();e.stopPropagation();set?ncStopSetChapter():ncStopGoChapter();return}
 if(ui.tab==='textlab'){const {source,draft}=ncLabPanes();if(!source&&!draft)return;const where=document.activeElement===source?'source':'draft';e.preventDefault();e.stopPropagation();set?ncLabStopSet(where):ncLabStopGo(where)}
},true);

/* ——— RC3.8.7: журнал «кто сдвинул окно» (выключен, NC_DIAG) в «Читать рукопись» и «Редакциях».
       Пишет в music-debug.log только позиции и причины (без текста книги), не больше 150 строк за запуск. ——— */
var NC_DIAG=false; /* включить — true: журнал прокрутки снова начнёт писаться */
var ncDiag={n:0,user:0,render:0,buf:[],t:null,pos:new WeakMap()};
function ncDiagOn(){return NC_DIAG&&!!window.__NOCTURNE_NATIVE&&(ui.tab==='reader'||ui.tab==='textlab')&&ncDiag.n<150}
function ncDiagLog(msg){
 if(!ncDiagOn())return;ncDiag.n++;const now=performance.now();
 ncDiag.buf.push(Math.round(now)+' '+ui.tab+' '+msg+' | user '+Math.round(now-ncDiag.user)+'ms ago, render '+Math.round(now-ncDiag.render)+'ms ago'+(document.body.classList.contains('nc-music-on')?' music':'')+(document.querySelector('#ncFind:not([hidden])')?' find':''));
 if(!ncDiag.t)ncDiag.t=setTimeout(()=>{ncDiag.t=null;const lines=ncDiag.buf.splice(0);while(lines.length){let chunk='';while(lines.length&&(chunk.length+lines[0].length)<1700)chunk+=(chunk?'\n':'')+lines.shift();if(!chunk)chunk=lines.shift().slice(0,1700);try{const key=(window.__NOCTURNE_BOOT&&window.__NOCTURNE_BOOT.key)||'';fetch('/api/native/log',{method:'POST',headers:{'X-Nocturne-Key':key},body:'diag\n'+chunk}).catch(()=>{})}catch(e){}}},1500);
}
['wheel','keydown','pointerdown','touchstart','touchmove'].forEach(ev=>window.addEventListener(ev,()=>{ncDiag.user=performance.now()},{capture:true,passive:true}));
window.addEventListener('pointermove',e=>{if(e.buttons)ncDiag.user=performance.now()},{capture:true,passive:true});
document.addEventListener('scroll',e=>{
 if(!ncDiagOn())return;const t=e.target===document?document.scrollingElement:e.target;if(!t)return;
 const was=ncDiag.pos.get(t)||[t.scrollTop,t.scrollLeft],now=[t.scrollTop,t.scrollLeft];ncDiag.pos.set(t,now);
 if(performance.now()-ncDiag.user<700)return;
 const name=t===document.scrollingElement?'window':t.matches?.('[data-lab-draft-editor]')?'draft':t.tagName==='TEXTAREA'?'source':(t.id||t.className||t.tagName);
 const dy=Math.round(now[0]-was[0]),dx=Math.round(now[1]-was[1]);if(!dy&&!dx)return;
 ncDiagLog('self-scroll '+name+' dy='+dy+(dx?' dx='+dx:'')+' top='+Math.round(now[0]));
},true);
(function(){try{new MutationObserver(()=>{const on=document.body.classList.contains('nc-music-on');if(on!==ncDiag.music){ncDiag.music=on;ncDiagLog('player '+(on?'shown':'hidden'))}}).observe(document.body,{attributes:true,attributeFilter:['class']})}catch(e){}})();
if(window.ResizeObserver){var ncDiagRO=new ResizeObserver(es=>{for(const e of es){const r=e.contentRect;ncDiagLog('resize '+(e.target.matches?.('[data-lab-draft-editor]')?'draft':e.target.tagName==='TEXTAREA'?'source':(e.target.id||e.target.className))+' '+Math.round(r.width)+'x'+Math.round(r.height))}})}
function ncDiagAfterRender(){
 const now=performance.now();if(ncDiagOn()&&now-ncDiag.user>700)ncDiagLog('render without user input');ncDiag.render=now;
 try{if(ncDiagRO){document.querySelectorAll('.lab-pane textarea,#readerPagedContent').forEach(el=>{if(!el.__ncDiagRO){el.__ncDiagRO=1;ncDiagRO.observe(el)}})}}catch(e){}
}

/* ——— RC3.8.9: шрифт и размер текста для всей программы (в «Ателье оформления»).
       Стили программы при сборке переведены на var(--nc-ui) / var(--nc-head) / var(--nc-fs) / var(--nc-hs).
       Встроенные шрифты (OFL) лежат в __NC_FONTS, свои шрифты автора — в state.userFonts (переезжают с библиотекой).
       Рукопись — редактор, чтение, экспорт — задаёт шрифт сама и не меняется. ——— */
function ncFontCatalog(){
 const F=(id,name,group,stack,faces)=>({id,name,group,stack,faces});
 return [
  F('','Как задумано','base','',null),
  F('lora','Lora','serif',"'NC Lora',Georgia,serif",[['lora','400 700']]),
  F('ptserif','PT Serif','serif',"'NC PT Serif',Georgia,serif",[['ptserif-400','400'],['ptserif-700','700']]),
  F('cormorant','Cormorant Garamond','serif',"'NC Cormorant',Georgia,serif",[['cormorant','400 700']]),
  F('playfair','Playfair Display','serif',"'NC Playfair',Georgia,serif",[['playfair','400 700']]),
  F('ebgaramond','EB Garamond','serif',"'NC EB Garamond',Georgia,serif",[['ebgaramond','400 700']]),
  F('alegreya','Alegreya','serif',"'NC Alegreya',Georgia,serif",[['alegreya','400 700']]),
  F('inter','Inter','sans',"'NC Inter','Segoe UI',Arial,sans-serif",[['inter-400','400'],['inter-600','500 800']]),
  F('ptsans','PT Sans','sans',"'NC PT Sans','Segoe UI',Arial,sans-serif",[['ptsans-400','400'],['ptsans-700','700']]),
  F('montserrat','Montserrat','sans',"'NC Montserrat','Segoe UI',Arial,sans-serif",[['montserrat','400 700']]),
  F('nunito','Nunito','sans',"'NC Nunito','Segoe UI',Arial,sans-serif",[['nunito','400 700']]),
  F('rubik','Rubik','sans',"'NC Rubik','Segoe UI',Arial,sans-serif",[['rubik','400 700']]),
  F('raleway','Raleway','sans',"'NC Raleway','Segoe UI',Arial,sans-serif",[['raleway','400 700']]),
  F('comfortaa','Comfortaa','sans',"'NC Comfortaa','Segoe UI',Arial,sans-serif",[['comfortaa','400 700']]),
  F('caveat','Caveat','hand',"'NC Caveat','Segoe Print',cursive",[['caveat','400 700']]),
  F('marck','Marck Script','hand',"'NC Marck Script','Segoe Script',cursive",[['marck','400 700']]),
  F('georgia','Georgia','system',"Georgia,serif",null),
  F('times','Times New Roman','system',"'Times New Roman',Times,serif",null),
  F('palatino','Palatino','system',"'Palatino Linotype',Palatino,'Book Antiqua',serif",null),
  F('verdana','Verdana','system',"Verdana,Geneva,sans-serif",null),
  F('trebuchet','Trebuchet MS','system',"'Trebuchet MS','Lucida Grande',sans-serif",null),
  F('tahoma','Tahoma','system',"Tahoma,Geneva,sans-serif",null),
  F('courier','Courier New — машинка','system',"'Courier New',Courier,monospace",null),
 ].concat((Array.isArray(state?.userFonts)?state.userFonts:[]).map(u=>F('user:'+u.id,u.name||'Мой шрифт','user',`'NC User ${u.id}',Georgia,serif`,null)));
}
function ncFontGroupTitle(g){return {serif:'Книжные, с засечками',sans:'Современные, без засечек',hand:'Рукописные',system:'Системные',user:'Мои шрифты'}[g]||''}
function ncFontState(){const f=state?.uiFont;return f&&typeof f==='object'?f:{}}
function ncFontById(id){return ncFontCatalog().find(x=>x.id===id)||null}
/* значения из первой сборки RC3.8.9 (стек шрифтов строкой) понимаем как есть */
function ncFontStack(v){if(!v)return '';const f=ncFontById(v);return f?f.stack:(/[,'"]/.test(v)?v:'')}
function ncFontLabel(v){if(!v)return 'как задумано';const f=ncFontById(v);return f?f.name:'свой набор'}
var ncFontsDone;
function ncFontFaces(ids){
 if(typeof __NC_FONTS!=='object')return;if(!ncFontsDone)ncFontsDone={};let css='';
 for(const id of ids){const f=ncFontById(id);if(!f||!f.faces||ncFontsDone[id])continue;ncFontsDone[id]=1;
  const fam=f.stack.split(',')[0];
  for(const [key,w] of f.faces){const data=__NC_FONTS[key];if(data)css+=`@font-face{font-family:${fam};src:url(data:font/woff;base64,${data}) format('woff');font-weight:${w};font-style:normal;font-display:swap}\n`}}
 if(!css)return;const st=document.createElement('style');st.className='nc-fonts';st.textContent=css;document.head.append(st);
}
var ncUserFontsDone;
function ncUserFontsRegister(){
 if(!window.FontFace||!document.fonts)return;if(!ncUserFontsDone)ncUserFontsDone={};
 for(const u of (Array.isArray(state?.userFonts)?state.userFonts:[])){
  if(!u?.id||!u.data||ncUserFontsDone[u.id])continue;ncUserFontsDone[u.id]=1;
  try{const ff=new FontFace('NC User '+u.id,`url(${u.data})`);document.fonts.add(ff);ff.load().catch(()=>{})}catch(e){}
 }
}
function ncApplyFonts(){
 const f=ncFontState(),r=document.documentElement.style;
 const ui=ncFontStack(f.ui),head=ncFontStack(f.head);
 ncFontFaces([f.ui,f.head].filter(Boolean));ncUserFontsRegister();
 if(ui)r.setProperty('--nc-ui',ui);else r.removeProperty('--nc-ui');
 if(head)r.setProperty('--nc-head',head);else r.removeProperty('--nc-head');
 const sc=Math.min(1.6,Math.max(.7,Number(f.scale)||1)),hs=Math.min(1.5,Math.max(.8,Number(f.hscale)||1));
 if(Math.abs(sc-1)>.001)r.setProperty('--nc-fs',String(sc));else r.removeProperty('--nc-fs');
 if(Math.abs(hs-1)>.001)r.setProperty('--nc-hs',String(hs));else r.removeProperty('--nc-hs');
}
var ncFontTarget='ui';
function ncFontPanel(){
 const f=ncFontState(),sc=Math.round((Number(f.scale)||1)*100),hs=Math.round((Number(f.hscale)||1)*100);
 const target=ncFontTarget==='head'?'head':'ui',cur=target==='head'?(f.head||''):(f.ui||'');
 const cat=ncFontCatalog();
 const card=x=>`<button type="button" class="nc-font-card ${x.id===cur?'on':''}" data-nc-font-pick="${esc(x.id)}" style="${x.stack?`font-family:${esc(x.stack)}`:(target==='head'?'font-family:Georgia,serif':'')}"><b>Аа Бб</b><span>${esc(x.name)}</span>${x.group==='user'?`<i class="nc-font-del" data-nc-font-del="${esc(x.id.slice(5))}" title="Удалить шрифт" aria-label="Удалить шрифт ${esc(x.name)}">×</i>`:''}</button>`;
 const presets=[[85,'Мелкий'],[100,'Обычный'],[115,'Крупный'],[130,'Очень крупный'],[150,'Огромный']];
 const groups=['base','serif','sans','hand','system','user'].map(g=>{const list=cat.filter(x=>x.group===g);if(!list.length&&g!=='user')return '';
  return `${ncFontGroupTitle(g)?`<div class="nc-font-group">${ncFontGroupTitle(g)}</div>`:''}<div class="nc-font-grid">${list.map(card).join('')}${g==='user'?`<button type="button" class="nc-font-card nc-font-add" data-nc-font-add><b>＋</b><span>Добавить свой шрифт</span></button>`:''}</div>`}).join('');
 return `<div class="panel nc-font-panel"><div class="cap">Шрифт и размер текста</div><p class="mini-help">Для всей программы и для любой темы: меню, кнопки, заголовки, карточки и подсказки. Текст рукописи настраивается отдельно — на «Письменном столе» и в «Читать рукопись».</p><div class="nc-font-sizes"><label><span>Размер текста · <b data-nc-fs-label>${sc}%</b></span><input type="range" min="70" max="160" step="5" value="${sc}" data-nc-fs aria-label="Размер текста"></label><label><span>Размер заголовков · <b data-nc-hs-label>${hs}%</b></span><input type="range" min="80" max="150" step="5" value="${hs}" data-nc-hs aria-label="Размер заголовков"></label></div><div class="nc-font-presets">${presets.map(([v,t])=>`<button type="button" class="btn small ${v===sc?'gold':''}" data-nc-fs-preset="${v}">${t}</button>`).join('')}</div><div class="nc-font-target" role="tablist"><button type="button" role="tab" aria-selected="${target==='ui'}" class="${target==='ui'?'on':''}" data-nc-font-target="ui">Шрифт интерфейса</button><button type="button" role="tab" aria-selected="${target==='head'}" class="${target==='head'?'on':''}" data-nc-font-target="head">Шрифт заголовков</button></div><p class="mini-help nc-font-now">Сейчас: интерфейс — <b>${esc(ncFontLabel(f.ui))}</b>, заголовки — <b>${esc(ncFontLabel(f.head))}</b>. Щёлкни по шрифту, чтобы выбрать его для вкладки выше.</p><div class="nc-font-gallery">${groups}</div><p class="mini-help">Свой шрифт — файл .ttf, .otf, .woff или .woff2 (например, с Google Fonts или ParaType). Он сохраняется в библиотеке и переезжает вместе с ней. Проверь, что в шрифте есть русские буквы.</p><div class="nc-font-preview"><h3>Глава первая. Маяк без смотрителя</h3><p>Солёная Гавань встретила Мирру ветром. Так будет выглядеть текст программы с этими настройками.</p></div><button type="button" class="btn small plain" data-nc-font-reset ${(f.ui||f.head||sc!==100||hs!==100)?'':'disabled'}>Вернуть как было</button><input type="file" id="ncFontFile" accept=".ttf,.otf,.woff,.woff2" multiple hidden></div>`;
}
function ncFontPanelRefresh(){
 const old=document.querySelector('.nc-font-panel');if(!old)return;
 ncFontFaces(ncFontCatalog().map(x=>x.id));ncUserFontsRegister();
 const t=document.createElement('template');t.innerHTML=ncFontPanel();old.replaceWith(t.content.firstElementChild);
}
function ncFontSet(k,v){state.uiFont={...ncFontState(),[k]:v};ncApplyFonts();const b=document.querySelector('[data-nc-font-reset]');if(b){const f=state.uiFont;b.disabled=!(f.ui||f.head||Math.round((Number(f.scale)||1)*100)!==100||Math.round((Number(f.hscale)||1)*100)!==100)}}
async function ncFontAddFiles(files){
 state.userFonts=Array.isArray(state.userFonts)?state.userFonts:[];let added=0;
 for(const file of [...files||[]]){
  if(!/\.(ttf|otf|woff2?)$/i.test(file.name)){notify('«'+file.name+'» — не файл шрифта (.ttf, .otf, .woff, .woff2)');continue}
  if(file.size>3*1024*1024){notify('«'+file.name+'» больше 3 МБ — возьми версию шрифта полегче (.woff2)');continue}
  const total=state.userFonts.reduce((n,u)=>n+(u.size||0),0);if(total+file.size>12*1024*1024){notify('Своих шрифтов уже больше 12 МБ — удали ненужные');break}
  const data=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)});
  const id=String(uid()).replace(/[^a-z0-9]/gi,'').slice(0,12)||String(Date.now());
  try{const ff=new FontFace('NC User '+id,`url(${data})`);await ff.load();document.fonts.add(ff);if(!ncUserFontsDone)ncUserFontsDone={};ncUserFontsDone[id]=1}
  catch(e){notify('«'+file.name+'» не получилось открыть как шрифт');continue}
  const name=file.name.replace(/\.[^.]+$/,'').replace(/[-_]+/g,' ').replace(/\s+/g,' ').trim().slice(0,40)||'Мой шрифт';
  state.userFonts.push({id,name,data,size:file.size,addedAt:new Date().toISOString()});added++;
  ncFontSet(ncFontTarget==='head'?'head':'ui','user:'+id);
 }
 if(added){persist();ncFontPanelRefresh();notify(added===1?'Шрифт добавлен и выбран':'Добавлено шрифтов: '+added)}
}
document.addEventListener('input',e=>{
 const r=e.target.closest?.('[data-nc-fs],[data-nc-hs]');if(!r)return;const v=Number(r.value)||100;
 if(r.matches('[data-nc-fs]')){ncFontSet('scale',v/100);const l=document.querySelector('[data-nc-fs-label]');if(l)l.textContent=v+'%';document.querySelectorAll('[data-nc-fs-preset]').forEach(b=>b.classList.toggle('gold',Number(b.dataset.ncFsPreset)===v))}
 else{ncFontSet('hscale',v/100);const l=document.querySelector('[data-nc-hs-label]');if(l)l.textContent=v+'%'}
});
document.addEventListener('change',e=>{
 if(e.target.closest?.('[data-nc-fs],[data-nc-hs]')){persist();return}
 if(e.target.id==='ncFontFile'){const inp=e.target;ncFontAddFiles(inp.files).finally(()=>{inp.value=''})}
});
document.addEventListener('click',e=>{
 const t=e.target;
 if(t.closest?.('[data-nc-font-reset]')){e.preventDefault();e.stopPropagation();state.uiFont={};ncApplyFonts();persist();ncFontPanelRefresh();notify('Шрифт и размер — как было');return}
 const del=t.closest?.('[data-nc-font-del]');if(del){e.preventDefault();e.stopPropagation();const id=del.dataset.ncFontDel;const u=(state.userFonts||[]).find(x=>x.id===id);
  ncAsk({title:'Удалить шрифт?',label:'«'+(u?.name||'Мой шрифт')+'» исчезнет из программы. Там, где он был выбран, вернётся шрифт по умолчанию. Чтобы удалить, нажми «Удалить».',confirm:true,okText:'Удалить'}).then(v=>{if(v===null)return;state.userFonts=(state.userFonts||[]).filter(x=>x.id!==id);const f=ncFontState();if(f.ui==='user:'+id)ncFontSet('ui','');if(f.head==='user:'+id)ncFontSet('head','');persist();ncFontPanelRefresh();notify('Шрифт удалён')});return}
 if(t.closest?.('[data-nc-font-add]')){e.preventDefault();e.stopPropagation();document.querySelector('#ncFontFile')?.click();return}
 const tg=t.closest?.('[data-nc-font-target]');if(tg){e.preventDefault();e.stopPropagation();ncFontTarget=tg.dataset.ncFontTarget;ncFontPanelRefresh();return}
 const pk=t.closest?.('[data-nc-font-pick]');if(pk){e.preventDefault();e.stopPropagation();ncFontSet(ncFontTarget==='head'?'head':'ui',pk.dataset.ncFontPick);persist();ncFontPanelRefresh();return}
 const pr=t.closest?.('[data-nc-fs-preset]');if(pr){e.preventDefault();e.stopPropagation();ncFontSet('scale',Number(pr.dataset.ncFsPreset)/100);persist();ncFontPanelRefresh()}
},true);
try{ncApplyFonts()}catch(e){}

var ncReady=true;try{ncAfterRender()}catch(e){console.error(e)}

/* RC3.8.11: Windows — класс nc-win на <html> и цвет полос прокрутки из текущей темы
   (тема задаётся на body, а полосу окна браузер берёт с html). */
function ncWinChrome(){
 const r=document.documentElement;if(!ncIsWin()){r.classList.remove('nc-win');return}
 r.classList.add('nc-win');
 const cs=getComputedStyle(document.body),a=cs.getPropertyValue('--accent').trim(),sd=cs.getPropertyValue('--side').trim();
 if(a&&sd){const v=`color-mix(in srgb, ${a} 42%, ${sd})`;if(r.style.getPropertyValue('--nc-sb')!==v)r.style.setProperty('--nc-sb',v)}
}
try{ncWinChrome()}catch(e){}

/* RC3.8.11: сбой сохранения виден сразу — плашка сверху окна, а не только надпись внизу меню.
   Если NOCTURNE на компьютере не отвечает, страница повторяет сохранение каждые 5 секунд,
   и как только связь вернётся, всё накопленное записывается само. */
let ncSaveRetryT=null;
async function flushSave(){
  clearTimeout(saveTimer);
  if(saving||!pending||failed)return;
  saving=true;pending=false;firstUnsentEditAt=0;
  const packed=JSON.stringify({state:snapshot(),baseRevision:serverRevision});
  try{
    const response=await fetch('/api/save',{method:'POST',headers:{'Content-Type':'application/json','X-Nocturne-Key':remoteKey},body:packed});
    const result=await response.json().catch(()=>({}));
    if(!response.ok){const er=new Error(result.error||('HTTP '+response.status));er.ncHttp=response.status;throw er}
    serverRevision=result.revision;
    saveLabel(pending?'◌ Сохраняется на Mac…':'● Сохранено на Mac');
    ncSaveAlarm(false);
  }catch(e){
    pending=true;failed=true;saveLabel('⚠ НЕ СОХРАНЕНО — экспортируй JSON!');
    const lost=!e.ncHttp;
    ncSaveAlarm(true,lost?'NOCTURNE на компьютере не отвечает, поэтому изменения пока есть только в этом окне.':'Ошибка сохранения: '+e.message+'.');
    if(lost){clearTimeout(ncSaveRetryT);ncSaveRetryT=setTimeout(ncSaveRetry,5000)}
  }finally{saving=false;if(pending&&!failed){saveTimer=setTimeout(flushSave,40)}}
}
function ncSaveRetry(){clearTimeout(ncSaveRetryT);if(!failed)return;failed=false;pending=true;flushSave()}
function ncSaveAlarm(on,msg){
 let el=document.querySelector('#ncSaveAlarm');
 if(!on){if(el){el.remove();notify('Связь восстановлена — всё сохранено')}return}
 if(!el){el=document.createElement('div');el.id='ncSaveAlarm';el.setAttribute('role','alert');document.body.appendChild(el)}
 el.innerHTML=`<div class="nc-alarm-text"><b>⚠ Изменения не сохраняются</b><span>${esc(msg||'')} Не закрывай окно: сначала сохрани копию JSON. Потом перезапусти NOCTURNE и, если чего-то не хватает, импортируй эту копию через «⇧ Импорт JSON / ZIP».</span></div><div class="nc-alarm-acts"><button type="button" class="btn small gold" data-nc-alarm-json>⇩ Сохранить копию JSON</button><button type="button" class="btn small" data-nc-alarm-retry>Повторить</button></div>`;
}
document.addEventListener('click',e=>{
 const t=e.target;if(!t||!t.closest)return;
 if(t.closest('[data-nc-alarm-json]')){e.preventDefault();try{backupJson()}catch(err){notify('Не получилось: '+err.message)}return}
 if(t.closest('[data-nc-alarm-retry]')){e.preventDefault();ncSaveRetry()}
},true);

/* RC3.8.11: «⇩ Архив» — повторные нажатия не плодят копии, имя файла по местному времени,
   и сразу видно, что архив собирается (на Windows тестер нажал 8 раз за 5 секунд). */
let ncBackupBusy=0;
async function backup(){
 if(ncBackupBusy&&Date.now()-ncBackupBusy<60000){notify('Архив уже собирается — подожди пару секунд');return}
 ncBackupBusy=Date.now();
 const btns=[...document.querySelectorAll('[data-act="backup"]')];btns.forEach(b=>{b.disabled=true;b.dataset.ncText=b.textContent;b.textContent='◌ Собираю архив…'});
 notify('◌ Собираю полный архив…');
 try{
  await waitSaved();
  const r=await fetch('/api/backup',{headers:{'X-Nocturne-Key':remoteKey},cache:'no-store'});
  if(!r.ok){const x=await r.json().catch(()=>({}));throw new Error(x.error||'Не удалось создать архив')}
  const b=await r.blob();
  if(!await looksLikeZip(b))throw new Error('Получен пустой или некорректный ZIP');
  const d=new Date(),p=n=>String(n).padStart(2,'0');
  download(`NOCTURNE_архив_${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}_${p(d.getHours())}-${p(d.getMinutes())}-${p(d.getSeconds())}.zip`,b);
  notify('Полный ZIP подготовлен к скачиванию. Проверь его наличие в Загрузках.');
 }catch(e){notify('Ошибка создания архива: '+e.message)}
 finally{setTimeout(()=>{ncBackupBusy=0;document.querySelectorAll('[data-act="backup"]').forEach(b=>{b.disabled=false;if(b.dataset.ncText){b.textContent=b.dataset.ncText;delete b.dataset.ncText}})},2500)}
}

/* ——— RC3.8.13: библиотека для многих историй ———
   • вид «Полка» и компактный «Список» (поиск, сортировка, группы по вселенным);
   • у книги и вселенной меню «⋯»: открыть, переименовать, перенести, выше/ниже, в корзину;
   • книги и вселенные перетаскиваются — в библиотеке и в боковом меню;
   • корзина: убранное возвращается одним нажатием, навсегда — только «Удалить навсегда»;
   • «Библиотека» — отдельной кнопкой над «Мастерской»; плейлисты листаются отдельно. */
var NC_LIB_LIST_FROM=24, ncDrag=null, ncLibMenuAnchor=null, ncLibClosed={}, ncLibMenuAt=0;
function ncLibView(){const v=state.libraryView;if(v==='list'||v==='shelf')return v;return (state.books||[]).length>=NC_LIB_LIST_FROM?'list':'shelf'}
function ncBookById(id){return (state.books||[]).find(b=>b.id===id)||null}
function ncWorldById(id){return (state.worlds||[]).find(w=>w.id===id)||null}
function ncBookWorldKey(b){return b&&b.worldId&&ncWorldById(b.worldId)?b.worldId:''}
function ncLibGroupsFresh(){const by=new Map([['',[]]]);for(const w of state.worlds||[])by.set(w.id,[]);for(const b of state.books||[])by.get(ncBookWorldKey(b)).push(b);return by}
function ncLibCommit(msg){booksByWorldDuringRender=null;persist();render();if(msg)notify(msg)}
function ncStories(n){return n+' '+ruForm(n,['история','истории','историй'])}
function ncFixActive(){
 if(!ncBookById(state.activeBookId)){
  state.activeBookId=state.books[0]?.id||null;const b=book();
  state.theme=b?.atmosphereTheme||state.libraryTheme||'amber';ui.sceneId=null;
  if(!['library','world','ideas','music','rhythm','themeatelier','widgets','settings'].includes(ui.tab))ui.tab='library';
 }
 if(state.activeWorldId&&!ncWorldById(state.activeWorldId)){state.activeWorldId=worldOf(book())?.id||state.worlds[0]?.id||null;if(ui.tab==='world')ui.tab='library'}
}
function ncLastWritten(){const m=new Map(),days=state.writingDays||{};for(const k of Object.keys(days).sort()){const e=days[k]?.earned||{};for(const id in e){const v=e[id]||{};if((v.characters||0)>0||(v.words||0)>0||(v.nospace||0)>0)m.set(id,k)}}return m}
function ncDayLabel(k){if(!k)return '—';const now=new Date(),t=dateLocal(now);if(k===t)return 'сегодня';const y=new Date(now);y.setDate(y.getDate()-1);if(k===dateLocal(y))return 'вчера';const d=new Date(k+'T12:00:00');return d.toLocaleDateString('ru-RU',{day:'numeric',month:'short'})+(d.getFullYear()!==now.getFullYear()?' '+d.getFullYear():'')}

/* ---------- изменения ---------- */
function ncBookShift(id,dir){const b=ncBookById(id);if(!b)return;const same=ncLibGroupsFresh().get(ncBookWorldKey(b)),i=same.indexOf(b),j=i+dir;if(i<0||j<0||j>=same.length)return;const o=same[j],ia=state.books.indexOf(b),ib=state.books.indexOf(o);state.books[ia]=o;state.books[ib]=b;ncLibCommit()}
function ncBookPlace(id,beforeId,worldId){
 const b=ncBookById(id);if(!b||id===beforeId)return;worldId=worldId&&ncWorldById(worldId)?worldId:'';
 const fromWorld=ncBookWorldKey(b);
 state.books.splice(state.books.indexOf(b),1);b.worldId=worldId||'';
 let at=-1;if(beforeId)at=state.books.findIndex(x=>x.id===beforeId);
 if(at<0){let last=-1;state.books.forEach((x,i)=>{if(ncBookWorldKey(x)===worldId)last=i});at=last<0?state.books.length:last+1}
 state.books.splice(at,0,b);
 if(state.activeBookId===id&&worldId)state.activeWorldId=worldId;
 ncLibCommit(fromWorld!==worldId?'«'+b.title+'» → '+(worldId?'«'+ncWorldById(worldId).name+'»':'«Отдельные истории»'):'');
}
function ncWorldShift(id,dir){const i=state.worlds.findIndex(w=>w.id===id),j=i+dir;if(i<0||j<0||j>=state.worlds.length)return;const t=state.worlds[i];state.worlds[i]=state.worlds[j];state.worlds[j]=t;ncLibCommit()}
function ncWorldPlace(id,beforeId){const w=ncWorldById(id);if(!w||id===beforeId)return;state.worlds.splice(state.worlds.indexOf(w),1);let at=beforeId?state.worlds.findIndex(x=>x.id===beforeId):-1;if(at<0)at=state.worlds.length;state.worlds.splice(at,0,w);ncLibCommit()}
async function ncBookRename(id){const b=ncBookById(id);if(!b)return;const t=await ncAsk({title:'Переименовать книгу',label:'Название',value:b.title,okText:'Сохранить'});if(t==null)return;const v=String(t).trim();if(!v){notify('Название не может быть пустым');return}if(v===b.title)return;b.title=v;ncLibCommit('Книга переименована')}
async function ncWorldRename(id){const w=ncWorldById(id);if(!w)return;const t=await ncAsk({title:'Переименовать вселенную',label:'Название',value:w.name,okText:'Сохранить'});if(t==null)return;const v=String(t).trim();if(!v){notify('Название не может быть пустым');return}if(v===w.name)return;w.name=v;ncLibCommit('Вселенная переименована')}
async function ncBookMoveAsk(id){
 const b=ncBookById(id);if(!b)return;const cur=ncBookWorldKey(b);
 const choices=state.worlds.map(w=>({value:w.id,label:w.name,hint:ncStories((ncLibGroupsFresh().get(w.id)||[]).length)})).concat([{value:'',label:'Отдельные истории',hint:'без вселенной'}]);
 const r=await ncAsk({title:'Перенести «'+b.title+'»',choicesTitle:'Куда',choices,choice:cur,confirm:true,okText:'Перенести'});
 if(!r)return;const to=r.choice||'';if(to===cur)return;ncBookPlace(id,null,to);
}
function ncTrash(){if(!Array.isArray(state.trash))state.trash=[];return state.trash}
function ncTrashPut(x){ncTrash().unshift({id:uid(),deletedAt:new Date().toISOString(),...x})}
async function ncBookDelete(id){
 const b=ncBookById(id);if(!b)return;
 if(state.books.length<=1){notify('Это последняя книга в библиотеке — её нельзя убрать. Сначала создай другую.');return}
 const r=await ncAsk({title:'Убрать книгу в корзину?',label:'«'+b.title+'» · '+ruCount((b.chapters||[]).length,'глав')+' · '+ruCount(fmtNum(totalOf(b,'words')),'слов'),hint:gs('Книга не пропадёт: её можно вернуть из корзины внизу библиотеки. Навсегда она удалится, только если ты сама очистишь корзину.','Книга не пропадёт: её можно вернуть из корзины внизу библиотеки. Навсегда она удалится, только если ты сам очистишь корзину.'),confirm:true,okText:'В корзину'});
 if(r==null)return;
 ncTrashPut({kind:'book',item:b,worldName:worldOf(b)?.name||''});state.books.splice(state.books.indexOf(b),1);ncFixActive();
 ncLibCommit('«'+b.title+'» — в корзине. Вернуть можно внизу библиотеки');
}
async function ncWorldDelete(id){
 const w=ncWorldById(id);if(!w)return;const bs=state.books.filter(b=>b.worldId===id);
 const r=await ncAsk({title:'Убрать вселенную «'+w.name+'»?',choicesTitle:bs.length?'Что сделать с её историями ('+bs.length+')':'',choices:bs.length?[{value:'keep',label:'Оставить истории',hint:'они перейдут в «Отдельные истории»'},{value:'trash',label:'Убрать вместе с историями',hint:'всё уйдёт в корзину, вернуть можно целиком'}]:null,choice:'keep',confirm:true,okText:'В корзину',hint:'Лор, хронология и общие персонажи вселенной уйдут в корзину вместе с ней. Вернуть можно внизу библиотеки.'});
 if(r==null)return;const mode=bs.length?((r&&r.choice)||'keep'):'keep';
 if(mode==='trash'&&bs.length>=state.books.length){notify('В библиотеке должна остаться хотя бы одна книга');return}
 ncTrashPut({kind:'world',item:w,books:mode==='trash'?bs:[],keptBookIds:mode==='keep'?bs.map(b=>b.id):[]});
 state.worlds.splice(state.worlds.indexOf(w),1);
 if(mode==='trash'){for(const b of bs)state.books.splice(state.books.indexOf(b),1)}else{for(const b of bs)b.worldId=''}
 ncFixActive();ncLibCommit('Вселенная «'+w.name+'» — в корзине');
}
function ncTrashRestore(tid){
 const T=ncTrash(),i=T.findIndex(t=>t.id===tid);if(i<0)return;const t=T[i];
 if(t.kind==='book'){const b=t.item;if(ncBookById(b.id))b.id=uid();if(b.worldId&&!ncWorldById(b.worldId))b.worldId='';state.books.push(b)}
 else if(t.kind==='world'){const w=t.item;if(ncWorldById(w.id))w.id=uid();state.worlds.push(w);for(const b of t.books||[]){b.worldId=w.id;if(!ncBookById(b.id))state.books.push(b)}for(const bid of t.keptBookIds||[]){const b=ncBookById(bid);if(b&&!b.worldId)b.worldId=w.id}}
 T.splice(i,1);ncLibCommit('Возвращено: «'+(t.kind==='world'?t.item.name:t.item.title)+'»');
}
async function ncTrashPurge(tid){const T=ncTrash(),t=T.find(x=>x.id===tid);if(!t)return;const name=t.kind==='world'?t.item.name:t.item.title;const r=await ncAsk({title:'Удалить навсегда?',label:'«'+name+'»'+(t.kind==='world'&&t.books?.length?' и '+ruCount(t.books.length,'книг')+' внутри':''),hint:'Это нельзя отменить.',confirm:true,okText:'Удалить навсегда'});if(r==null)return;T.splice(T.indexOf(t),1);ncLibCommit('Удалено навсегда')}
async function ncTrashEmpty(){const T=ncTrash();if(!T.length)return;const r=await ncAsk({title:'Очистить корзину?',label:'Всё в корзине ('+T.length+') удалится навсегда.',hint:'Это нельзя отменить.',confirm:true,okText:'Очистить'});if(r==null)return;state.trash=[];ncLibCommit('Корзина очищена')}

/* ---------- страница «Библиотека» ---------- */
function library(){
 try{return ncLibraryPage()}catch(e){
  console.error('NOCTURNE: библиотека',e);
  const bs=Array.isArray(state.books)?state.books:[];
  return `<div class="page-head"><div><div class="cap">Библиотека</div><h1>Мои миры и книги</h1></div></div><div class="nc-lib-fallback">${bs.map(b=>`<button type="button" class="btn" data-open-book="${esc(b.id)}">${esc(b.title||'Без названия')}</button>`).join('')}</div>`;
 }
}
function ncLibraryPage(){
 const view=ncLibView(),n=state.books.length;
 const hero=`<div class="hero editable-hero ${state.libraryBannerImage?'':'nc-hero-themed'}" data-library-tint="${esc(state.libraryBannerTint||'gradient')}" style="--library-tint-strength:${Number(state.libraryBannerTintStrength??65)/100}"><img class="hero-wallpaper" alt="Фон библиотеки" src="${esc(state.libraryBannerImage||ASSETS.first)}"><div class="nc-hero-grade" aria-hidden="true"></div><div class="hero-content"><div class="cap">NOCTURNE · Обитель историй</div><h1>Здесь истории<br>оживают.</h1><p>Каждая история заслуживает быть рассказанной. Выбери свой мир — он будет рад твоему возвращению.</p>${book()?`<button class="btn gold" data-open-book="${esc(book().id)}">✒ Продолжить «${esc(snip(book().title,24))}»</button>`:''}</div><div class="hero-custom-controls"><button class="btn small" data-act="banner-upload" data-banner-scope="library">✦ Свой фон</button><label class="tiny banner-overlay-label">Покрытие <select id="libraryBannerTint"><option value="none" ${state.libraryBannerTint==='none'?'selected':''}>Без наложения</option><option value="gradient" ${!state.libraryBannerTint||state.libraryBannerTint==='gradient'?'selected':''}>Мягкий градиент</option><option value="theme" ${state.libraryBannerTint==='theme'?'selected':''}>Цвет темы</option></select></label>${state.libraryBannerImage?`<button class="btn small plain" data-act="banner-remove" data-banner-scope="library">Сбросить</button>`:''}</div></div>`;
 return `${hero}
${habitRingMarkup(false)}
${homeInspiration()}
${ncLibToolbar(view,n)}${view==='list'?ncLibList():ncLibShelf()}${ncTrashBlock()}<p class="mini-help" style="margin-top:24px">Рукописи сохраняются в выбранной папке на Mac. Для внешней копии создавай полный ZIP-архив.</p>`;
}
function ncLibToolbar(view,n){
 const sort=ui.ncLibSort||'order';
 return `<div class="nc-lib-bar" role="toolbar" aria-label="Библиотека"><div class="nc-seg" role="group" aria-label="Вид библиотеки"><button type="button" data-nc-libview="shelf" aria-pressed="${view==='shelf'}" class="${view==='shelf'?'on':''}">▦ Полка</button><button type="button" data-nc-libview="list" aria-pressed="${view==='list'}" class="${view==='list'?'on':''}">☰ Список</button></div><input type="search" class="nc-lib-search" data-nc-libq placeholder="Найти историю…" aria-label="Найти историю" value="${esc(ui.ncLibQ||'')}">${view==='list'?`<label class="nc-lib-sort">Порядок <select data-nc-libsort>${[['order','мой'],['title','по названию'],['recent','недавние'],['size','по объёму']].map(([v,t])=>`<option value="${v}" ${sort===v?'selected':''}>${t}</option>`).join('')}</select></label>`:''}<span class="nc-lib-count" data-nc-libfound>${ncStories(n)} · ${ruCount(state.worlds.length,'вселенных')}</span><span class="nc-lib-grow"></span><button type="button" class="btn small" data-nc-bookimp title="Книга из файла NOCTURNE или из ответа нейросети (ChatGPT, Claude и др.)">⇧ Импорт книги</button><button type="button" class="btn small" data-act="new-world">＋ Вселенная</button><button type="button" class="btn small gold" data-act="new-book">＋ История</button></div>${view==='shelf'&&n>=NC_LIB_LIST_FROM?`<p class="mini-help nc-lib-tip">Историй много — попробуй вид «Список»: он компактнее и с поиском.</p>`:''}<p class="mini-help nc-lib-howto">Книги и вселенные можно перетаскивать. Переименовать, перенести или убрать — через «⋯».</p>`;
}
function ncLibGroupsList(){const by=ncLibGroupsFresh();return state.worlds.map(w=>({id:w.id,name:w.name,world:w,books:by.get(w.id)||[]})).concat([{id:'',name:'Отдельные истории',world:null,books:by.get('')||[]}])}
function ncLibList(){
 const sort=ui.ncLibSort||'order',lw=ncLastWritten(),manual=sort==='order';
 const sorter={title:(a,b)=>String(a.title).localeCompare(String(b.title),'ru'),recent:(a,b)=>(lw.get(b.id)||'').localeCompare(lw.get(a.id)||''),size:(a,b)=>totalOf(b,'words')-totalOf(a,'words')}[sort];
 return `<div class="nc-lib-list">${ncLibGroupsList().map(g=>{const bs=sorter?g.books.slice().sort(sorter):g.books,key=g.id||'__solo',closed=!!(ncLibClosed&&ncLibClosed[key]);
  return `<section class="nc-lib-group ${closed?'closed':''}" data-nc-group="${esc(g.id)}"><div class="nc-lib-ghead" data-nc-drop-world="${esc(g.id)}" ${g.world?`data-nc-drag-world="${esc(g.id)}" draggable="true"`:''}><button type="button" class="nc-lib-caret" data-nc-libfold="${esc(key)}" aria-expanded="${!closed}" aria-label="${closed?'Развернуть':'Свернуть'}: ${esc(g.name)}">${closed?'▸':'▾'}</button>${g.world?`<button type="button" class="nc-lib-gname" data-open-world="${esc(g.id)}"><span class="glyph" aria-hidden="true">✦</span>${esc(g.name)}</button>`:`<span class="nc-lib-gname"><span class="glyph" aria-hidden="true">◈</span>Отдельные истории</span>`}<span class="nc-lib-gcount">${bs.length}</span>${g.world?`<button type="button" class="nc-more" data-nc-more="world" data-id="${esc(g.id)}" aria-label="Действия со вселенной «${esc(g.name)}»">⋯</button>`:''}</div>${closed?'':`<div class="nc-lib-rows">${bs.map(b=>ncLibRow(b,lw,manual)).join('')||`<div class="nc-lib-empty">Перетащи сюда историю или <button type="button" class="nc-linkish" data-act="new-book" data-world-id="${esc(g.id)}">создай новую</button></div>`}</div>`}</section>`}).join('')}</div>`;
}
function ncLibRow(b,lw,manual){
 const words=totalOf(b,'words'),ch=(b.chapters||[]).length;
 return `<div class="nc-lib-row ${state.activeBookId===b.id?'current':''}" data-nc-drag-book="${esc(b.id)}" data-nc-book-world="${esc(ncBookWorldKey(b))}" data-nc-title="${esc(String(b.title||'').toLocaleLowerCase('ru'))}" ${manual?'draggable="true"':''}>${manual?'<span class="nc-grip" aria-hidden="true">⋮⋮</span>':''}<button type="button" class="nc-lib-open" data-open-book="${esc(b.id)}"><span class="nc-lib-thumb" aria-hidden="true">${b.cover?`<img src="${esc(b.cover)}" alt="" loading="lazy" decoding="async">`:`<span>${esc(String(b.title||'?').trim().charAt(0).toUpperCase())}</span>`}</span><span class="nc-lib-title"><b>${esc(b.title)}</b>${b.genre?`<small>${esc(b.genre)}</small>`:''}</span></button><span class="nc-lib-meta">${ruCount(ch,'глав')}</span><span class="nc-lib-meta">${ruCount(fmtNum(words),'слов')}</span><span class="nc-lib-meta nc-lib-when" title="Последний день, когда в книге прибавился текст">${ncDayLabel(lw.get(b.id))}</span><button type="button" class="nc-more" data-nc-more="book" data-id="${esc(b.id)}" aria-label="Действия с книгой «${esc(b.title)}»">⋯</button></div>`;
}
function ncShelfTiles(arr,worldId){
 return `<div class="book-shelf">${arr.map(b=>`<div class="nc-tile-wrap" data-nc-drag-book="${esc(b.id)}" data-nc-book-world="${esc(ncBookWorldKey(b))}" data-nc-title="${esc(String(b.title||'').toLocaleLowerCase('ru'))}" draggable="true"><button class="booktile" data-open-book="${esc(b.id)}"><span class="life-book-cover">${bookCover(b)}<span class="life-book-icon">${lifeBadge(b,true)}</span></span><strong>${esc(b.title)}</strong><span class="sub">${ruCount((b.chapters||[]).length,'глав')} · ${ruCount(fmtNum(totalOf(b,'words')),'слов')}</span></button><button type="button" class="nc-more nc-tile-more" data-nc-more="book" data-id="${esc(b.id)}" aria-label="Действия с книгой «${esc(b.title)}»">⋯</button></div>`).join('')}<button class="booktile" data-act="new-book" data-world-id="${esc(worldId||'')}"><div class="blankbook">＋</div><strong>Новая история</strong><span class="sub">Открой новую рукопись</span></button></div>`;
}
function ncLibShelf(){
 const by=ncLibGroupsFresh();
 const tiles=state.worlds.map(w=>`<div class="nc-tile-wrap nc-world-wrap" data-nc-drag-world="${esc(w.id)}" draggable="true"><button class="world-card" data-open-world="${esc(w.id)}"><img loading="lazy" decoding="async" class="worldthumb" src="${esc(w.image||ASSETS.third)}" alt=""><div class="world-copy"><span class="cap">Вселенная · ${ruCount((by.get(w.id)||[]).length,'книг')}</span><strong style="display:block;margin-top:5px">${esc(w.name)}</strong><p>${esc(snip(w.description,130))}</p></div></button><button type="button" class="nc-more nc-tile-more" data-nc-more="world" data-id="${esc(w.id)}" aria-label="Действия со вселенной «${esc(w.name)}»">⋯</button></div>`).join('');
 return `<div class="shelf-label"><h2>Мои вселенные</h2></div><div class="tricol">${tiles||'<div class="empty"><div class="symbol">✦</div>Здесь будут твои миры</div>'}</div>
${state.worlds.map(w=>`<section class="nc-shelf-block" data-nc-group="${esc(w.id)}"><div class="shelf-label" data-nc-drop-world="${esc(w.id)}"><h2>${esc(w.name)}</h2><button class="btn small plain" data-open-world="${esc(w.id)}">Открыть мир ↗</button></div>${ncShelfTiles(by.get(w.id)||[],w.id)}</section>`).join('')}
<section class="nc-shelf-block" data-nc-group=""><div class="shelf-label" data-nc-drop-world=""><h2>Самостоятельные книги</h2></div>${ncShelfTiles(by.get('')||[],'')}</section>`;
}
function ncTrashBlock(){
 const T=state.trash||[];if(!T.length)return '';
 return `<details class="nc-trash" ${ui.ncTrashOpen?'open':''}><summary>Корзина · ${T.length}</summary><p class="mini-help">Убранное лежит здесь, пока ты не удалишь его навсегда. Вернуть можно одним нажатием.</p>${T.map(t=>`<div class="nc-trash-row"><span class="nc-trash-kind">${t.kind==='world'?'✦ Вселенная':'⌑ Книга'}</span><span class="nc-trash-name"><b>${esc(t.kind==='world'?t.item.name:t.item.title)}</b><small>${esc(ncTrashNote(t))}</small></span><button type="button" class="btn small" data-nc-trash="restore" data-id="${esc(t.id)}">↺ Вернуть</button><button type="button" class="btn small plain" data-nc-trash="purge" data-id="${esc(t.id)}">Удалить навсегда</button></div>`).join('')}<button type="button" class="btn small plain nc-trash-empty" data-nc-trash="empty">Очистить корзину</button></details>`;
}
function ncTrashNote(t){const d=new Date(t.deletedAt),when=isNaN(d)?'':d.toLocaleDateString('ru-RU',{day:'numeric',month:'short'});if(t.kind==='world')return (t.books?.length?ruCount(t.books.length,'книг')+' внутри · ':'')+'убрана '+when;return (t.worldName?'из «'+t.worldName+'» · ':'')+ruCount((t.item.chapters||[]).length,'глав')+' · убрана '+when}
function ncLibFilter(){
 const root=document.querySelector('#app');if(!root||ui.tab!=='library')return;
 const q=String(ui.ncLibQ||'').trim().toLocaleLowerCase('ru');let found=0;
 root.querySelectorAll('[data-nc-title]').forEach(el=>{const hide=!!q&&!el.dataset.ncTitle.includes(q);el.hidden=hide;if(!hide)found++});
 root.querySelectorAll('.nc-lib-group,.nc-shelf-block').forEach(g=>{g.hidden=!!q&&!g.querySelector('[data-nc-title]:not([hidden])')});
 const c=root.querySelector('[data-nc-libfound]');if(c)c.textContent=q?('Найдено: '+found):(ncStories(state.books.length)+' · '+ruCount(state.worlds.length,'вселенных'));
}

/* ---------- меню «⋯» ---------- */
function ncLibMenuClose(){document.querySelector('#ncLibMenu')?.remove();ncLibMenuAnchor=null}
function ncLibMenuOpen(anchor,kind,id){
 ncLibMenuClose();let items,title;
 if(kind==='book'){const b=ncBookById(id);if(!b)return;title=b.title;const g=ncLibGroupsFresh().get(ncBookWorldKey(b))||[],i=g.indexOf(b);
  items=[['open','Открыть книгу','↗'],['rename','Переименовать','✎'],['move','Перенести во вселенную…','⇄'],['up','Выше','↑',i<=0],['down','Ниже','↓',i<0||i>=g.length-1],['export','Выгрузить книгу в файл','⇩'],['-'],['trash','Убрать в корзину','×']];}
 else{const w=ncWorldById(id);if(!w)return;title=w.name;const i=state.worlds.indexOf(w);
  items=[['open','Открыть вселенную','✦'],['rename','Переименовать','✎'],['newbook','Новая история здесь','＋'],['up','Выше','↑',i<=0],['down','Ниже','↓',i>=state.worlds.length-1],['-'],['trash','Убрать в корзину','×']];}
 const m=document.createElement('div');m.id='ncLibMenu';m.className='nc-lib-menu';m.setAttribute('role','menu');m.setAttribute('aria-label',title);m.dataset.kind=kind;m.dataset.id=id;
 m.innerHTML=`<div class="nc-lib-menu-title">${esc(title)}</div>`+items.map(([a,t,ic,dis])=>a==='-'?'<div class="nc-lib-menu-sep" role="separator"></div>':`<button type="button" role="menuitem" data-nc-lm="${a}" ${dis?'disabled':''} class="${a==='trash'?'danger':''}"><span class="ic" aria-hidden="true">${ic}</span>${t}</button>`).join('');
 document.body.appendChild(m);ncLibMenuAnchor=anchor;ncLibMenuAt=Date.now();anchor.setAttribute('aria-expanded','true');
 const r=anchor.getBoundingClientRect(),mw=m.offsetWidth,mh=m.offsetHeight;
 let x=Math.max(8,Math.min(r.right-mw,innerWidth-mw-8)),y=r.bottom+4;if(y+mh>innerHeight-8)y=Math.max(8,r.top-mh-4);
 m.style.left=x+'px';m.style.top=y+'px';
 m.querySelector('button:not([disabled])')?.focus({preventScroll:true});
}
function ncLibMenuAct(a,kind,id){
 const anchor=ncLibMenuAnchor;ncLibMenuClose();try{anchor?.setAttribute('aria-expanded','false')}catch(e){}
 if(kind==='book'){if(a==='open')setBook(id);else if(a==='rename')ncBookRename(id);else if(a==='move')ncBookMoveAsk(id);else if(a==='up')ncBookShift(id,-1);else if(a==='down')ncBookShift(id,1);else if(a==='export')ncBookExport(id);else if(a==='trash')ncBookDelete(id)}
 else{if(a==='open')setWorld(id);else if(a==='rename')ncWorldRename(id);else if(a==='newbook')modal('book',null,{worldId:id});else if(a==='up')ncWorldShift(id,-1);else if(a==='down')ncWorldShift(id,1);else if(a==='trash')ncWorldDelete(id)}
}

/* ---------- боковое меню: «Библиотека», «⋯», перетаскивание, поиск ---------- */
function ncHomeNavRender(){
 const el=document.querySelector('#ncHomeNav');if(!el)return;
 const n=(state.books||[]).length,w=(state.worlds||[]).length,sub=ncStories(n)+(w?' · '+w+' '+ruForm(w,['мир','мира','миров']):'');
 el.innerHTML=`<button type="button" class="navlink nc-home-link ${ui.tab==='library'?'active':''}" data-tab="library" title="Библиотека — все вселенные и книги"><span class="symbol" aria-hidden="true">⌂</span><span class="nc-home-text"><b>Библиотека</b><small>${esc(sub)}</small></span></button>`;
 const head=document.querySelector('.sidebar-workspace-head');
 if(head){const b=book(),t=b?'для книги «'+b.title+'»':'выбери книгу в библиотеке';let s=head.querySelector('.nc-workshop-for');if(!s){s=document.createElement('small');s.className='nc-workshop-for';head.appendChild(s)}if(s.textContent!==t)s.textContent=t;head.title='Мастерская — инструменты для одной книги'}
}
function ncSideDecorate(){
 const nav=document.querySelector('#worldNav');if(!nav)return;
 nav.querySelectorAll('.sideworld').forEach(sw=>{
  const head=sw.querySelector('.sideworld-head'),entry=head?.querySelector('.world-entry');if(!entry)return;
  const wid=entry.dataset.openWorld;
  if(wid){entry.setAttribute('draggable','true');entry.dataset.ncDragWorld=wid;head.dataset.ncDropWorld=wid;if(!head.querySelector('.nc-more'))head.insertAdjacentHTML('beforeend',`<button type="button" class="nc-more nc-side-more" data-nc-more="world" data-id="${esc(wid)}" aria-label="Действия со вселенной">⋯</button>`)}
  else if(entry.dataset.tab==='library')head.dataset.ncDropWorld='';
  sw.querySelectorAll('.s-book[data-open-book]').forEach(sb=>{
   const id=sb.dataset.openBook,b=ncBookById(id);if(!b)return;
   sb.setAttribute('draggable','true');sb.dataset.ncDragBook=id;sb.dataset.ncBookWorld=ncBookWorldKey(b);
   if(!sb.parentElement.classList.contains('nc-srow')){const row=document.createElement('div');row.className='nc-srow';sb.replaceWith(row);row.appendChild(sb);row.insertAdjacentHTML('beforeend',`<button type="button" class="nc-more nc-side-more" data-nc-more="book" data-id="${esc(id)}" aria-label="Действия с книгой">⋯</button>`)}
  });
 });
 if((state.books||[]).length>=12&&!nav.querySelector('.nc-side-find'))nav.insertAdjacentHTML('afterbegin',`<div class="nc-side-find"><input type="search" data-nc-sideq placeholder="Найти книгу…" aria-label="Найти книгу в меню" value="${esc(ui.ncSideQ||'')}"><div class="nc-side-results" hidden></div></div>`);
 ncSideFilter();
}
function ncSideFilter(){
 const nav=document.querySelector('#worldNav');if(!nav)return;const box=nav.querySelector('.nc-side-results');
 const q=String(ui.ncSideQ||'').trim().toLocaleLowerCase('ru');
 nav.querySelectorAll(':scope > .sideworld, :scope > .s-book').forEach(el=>{el.hidden=!!q});
 if(!box)return;
 if(!q){box.hidden=true;box.innerHTML='';return}
 const hits=state.books.filter(b=>String(b.title||'').toLocaleLowerCase('ru').includes(q)).slice(0,40);
 box.hidden=false;box.innerHTML=hits.map(b=>`<button class="s-book ${state.activeBookId===b.id?'current-book':''}" data-open-book="${esc(b.id)}">⌑ <span style="overflow:hidden;text-overflow:ellipsis">${esc(b.title)}</span><small>${esc(worldOf(b)?.name||'')}</small></button>`).join('')||'<div class="nc-side-none">Ничего не нашлось</div>';
}

/* ---------- перетаскивание ---------- */
function ncDropZone(t){
 if(!ncDrag||!t||!t.closest)return null;
 if(ncDrag.kind==='book'){
  const row=t.closest('[data-nc-drag-book]');if(row&&row.dataset.ncDragBook!==ncDrag.id)return {el:row,act:'before',id:row.dataset.ncDragBook,world:row.dataset.ncBookWorld||''};
  const g=t.closest('[data-nc-drop-world]');if(g)return {el:g,act:'into',world:g.dataset.ncDropWorld||''};
  const sec=t.closest('.nc-lib-group,.nc-shelf-block');if(sec)return {el:sec,act:'into',world:sec.dataset.ncGroup||''};
  return null;
 }
 const wh=t.closest('[data-nc-drag-world]');if(wh&&wh.dataset.ncDragWorld!==ncDrag.id)return {el:wh,act:'wbefore',id:wh.dataset.ncDragWorld};
 const g=t.closest('[data-nc-drop-world=""]');if(g)return {el:g,act:'wend'};
 return null;
}
function ncDropMark(el){document.querySelectorAll('.nc-drop-target').forEach(x=>{if(x!==el)x.classList.remove('nc-drop-target')});if(el)el.classList.add('nc-drop-target')}
document.addEventListener('dragstart',e=>{
 const t=e.target&&e.target.closest?e.target.closest('[data-nc-drag-book],[data-nc-drag-world]'):null;if(!t||!t.getAttribute('draggable'))return;
 ncDrag=t.dataset.ncDragBook?{kind:'book',id:t.dataset.ncDragBook}:{kind:'world',id:t.dataset.ncDragWorld};
 try{e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',ncDrag.id)}catch(err){}
 ncLibMenuClose();setTimeout(()=>{document.body.classList.add('nc-dragging');t.classList.add('nc-drag-src')},0);
});
document.addEventListener('dragover',e=>{if(!ncDrag)return;const z=ncDropZone(e.target);if(!z){ncDropMark(null);return}e.preventDefault();try{e.dataTransfer.dropEffect='move'}catch(err){}ncDropMark(z.el)});
document.addEventListener('drop',e=>{
 if(!ncDrag)return;const z=ncDropZone(e.target);const d=ncDrag;ncDrag=null;ncDropMark(null);document.body.classList.remove('nc-dragging');
 if(!z)return;e.preventDefault();
 if(z.act==='before')ncBookPlace(d.id,z.id,z.world);else if(z.act==='into')ncBookPlace(d.id,null,z.world);else if(z.act==='wbefore')ncWorldPlace(d.id,z.id);else if(z.act==='wend')ncWorldPlace(d.id,null);
});
document.addEventListener('dragend',()=>{ncDrag=null;ncDropMark(null);document.body.classList.remove('nc-dragging');document.querySelectorAll('.nc-drag-src').forEach(x=>x.classList.remove('nc-drag-src'))});

/* ---------- щелчки, ввод, клавиши ---------- */
document.addEventListener('click',e=>{
 const t=e.target;if(!t||!t.closest)return;
 const more=t.closest('[data-nc-more]');
 if(more){e.preventDefault();e.stopPropagation();const open=document.querySelector('#ncLibMenu');if(open&&ncLibMenuAnchor===more){ncLibMenuClose();return}ncLibMenuOpen(more,more.dataset.ncMore,more.dataset.id);return}
 const lm=t.closest('#ncLibMenu [data-nc-lm]');
 if(lm){e.preventDefault();e.stopPropagation();if(lm.disabled)return;const m=lm.closest('#ncLibMenu');ncLibMenuAct(lm.dataset.ncLm,m.dataset.kind,m.dataset.id);return}
 if(t.closest('#ncLibMenu'))return;
 if(document.querySelector('#ncLibMenu'))ncLibMenuClose();
 const lv=t.closest('[data-nc-libview]');if(lv){e.preventDefault();e.stopPropagation();state.libraryView=lv.dataset.ncLibview;persist();render();return}
 const fold=t.closest('[data-nc-libfold]');if(fold){e.preventDefault();e.stopPropagation();const k=fold.dataset.ncLibfold;if(!ncLibClosed)ncLibClosed={};ncLibClosed[k]=!ncLibClosed[k];render();return}
 const tr=t.closest('[data-nc-trash]');if(tr){e.preventDefault();e.stopPropagation();const act=tr.dataset.ncTrash,id=tr.dataset.id;if(act==='restore')ncTrashRestore(id);else if(act==='purge')ncTrashPurge(id);else if(act==='empty')ncTrashEmpty();return}
},true);
document.addEventListener('input',e=>{
 const t=e.target;if(!t||!t.matches)return;
 if(t.matches('[data-nc-libq]')){ui.ncLibQ=t.value;ncLibFilter();return}
 if(t.matches('[data-nc-sideq]')){ui.ncSideQ=t.value;ncSideFilter()}
},true);
document.addEventListener('change',e=>{const t=e.target;if(t&&t.matches&&t.matches('[data-nc-libsort]')){ui.ncLibSort=t.value;render()}},true);
document.addEventListener('toggle',e=>{if(e.target&&e.target.matches&&e.target.matches('.nc-trash'))ui.ncTrashOpen=e.target.open},true);
window.addEventListener('keydown',e=>{
 const m=document.querySelector('#ncLibMenu');if(!m)return;
 if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();const a=ncLibMenuAnchor;ncLibMenuClose();try{a?.focus()}catch(err){}return}
 if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();e.stopImmediatePropagation();const bs=[...m.querySelectorAll('button:not([disabled])')],i=bs.indexOf(document.activeElement);const n=e.key==='ArrowDown'?(i+1)%bs.length:(i-1+bs.length)%bs.length;bs[n]?.focus()}
},true);
window.addEventListener('resize',()=>ncLibMenuClose());
document.addEventListener('scroll',e=>{if(e.target&&e.target.closest&&e.target.closest('#ncLibMenu'))return;if(Date.now()-ncLibMenuAt<400)return;if(document.querySelector('#ncLibMenu'))ncLibMenuClose()},true);

/* ---------- плейлисты листаются отдельно ---------- */
var ncMusicColScroll=0;
document.addEventListener('scroll',e=>{const t=e.target;if(t&&t.classList&&t.classList.contains('music-collections'))ncMusicColScroll=t.scrollTop},true);
function ncMusicCollections(){
 if(ui.tab!=='music')return;
 const top=document.querySelector('.topbar'),tabs=document.querySelector('#ncTabs');
 const vis=el=>el&&getComputedStyle(el).display!=='none'?el.offsetHeight:0;
 document.documentElement.style.setProperty('--nc-sticky-top',(vis(top)+vis(tabs)+14)+'px');
 const col=document.querySelector('.music-collections');if(!col)return;
 col.scrollTop=ncMusicColScroll;
 const a=col.querySelector('.music-collection.active');
 if(a&&col.scrollHeight>col.clientHeight){const at=a.getBoundingClientRect().top-col.getBoundingClientRect().top+col.scrollTop;if(at<col.scrollTop||at+a.offsetHeight>col.scrollTop+col.clientHeight){col.scrollTop=Math.max(0,at-col.clientHeight/3);ncMusicColScroll=col.scrollTop}}
}

function ncLibAfterRender(){
 ncHomeNavRender();ncSideDecorate();ncLibFilter();ncMusicCollections();
 if(document.querySelector('#ncLibMenu')&&!(ncLibMenuAnchor&&ncLibMenuAnchor.isConnected))ncLibMenuClose();
}

/* ——— RC3.8.14: одна книга — в файл и из файла (в том числе собранного ChatGPT) ———
   «⇩ Выгрузить книгу» (меню «⋯») сохраняет книгу целиком: главы, героев, лор, линии,
   карточки, картинки; вселенную — для справки. «⇧ Импорт книги» в библиотеке читает такой
   файл или простой формат, который собирает ChatGPT по готовому промпту. Перед импортом
   видно, что внутри; импорт создаёт новую книгу или дополняет выбранную, ничего не удаляя. */
var NC_BOOK_FORMAT=1;
function ncSafeName(t){return String(t||'Книга').replace(/[\\/:*?"<>|\u0000-\u001f]+/g,' ').replace(/\s+/g,' ').trim().slice(0,80)||'Книга'}
function ncBookExport(id){
 const b=ncBookById(id);if(!b)return;const w=worldOf(b);
 const data={nocturne:'book',version:NC_BOOK_FORMAT,exportedAt:new Date().toISOString(),book:JSON.parse(JSON.stringify(b)),universe:w?JSON.parse(JSON.stringify(w)):null,ideas:(state.quickIdeas||[]).filter(x=>x.bookId===b.id).map(x=>({text:x.text,createdAt:x.createdAt}))};
 download(ncSafeName(b.title)+'.nocturne-book.json',new Blob([JSON.stringify(data,null,1)],{type:'application/json'}));
 notify('Книга «'+b.title+'» выгружена в файл'+(w?' вместе с вселенной «'+w.name+'»':'')+'. Музыка в файл не входит.');
}
/* разбор текста: блок кода, лишний текст вокруг, висячие запятые, комментарии */
function ncBookParseText(text){
 let t=String(text||'').replace(/^﻿/,'').trim();
 if(!t)throw new Error('Пусто — вставь ответ нейросети или выбери файл');
 const fence=t.match(/```[a-zA-Z]*\s*([\s\S]*?)```/);if(fence&&fence[1].includes('{'))t=fence[1].trim();
 const a=t.indexOf('{'),z=t.lastIndexOf('}');
 if(a<0||z<a)throw new Error('Не вижу данных книги: нужен блок, который начинается с «{» и заканчивается «}». Попроси нейросеть прислать ответ одним блоком кода.');
 t=t.slice(a,z+1);
 const tries=[x=>x,x=>x.replace(/,\s*([}\]])/g,'$1'),x=>x.replace(/^\s*\/\/.*$/gm,'').replace(/,\s*([}\]])/g,'$1'),x=>x.replace(/[“”„]/g,'"').replace(/,\s*([}\]])/g,'$1')];
 let err=null;for(const f of tries){try{return JSON.parse(f(t))}catch(e){err=e}}
 throw new Error('Файл повреждён: '+String(err&&err.message||err).slice(0,140)+'. Попроси нейросеть проверить, что это корректный JSON, и прислать заново.');
}
const ncS=v=>v==null?'':Array.isArray(v)?v.map(ncS).filter(Boolean).join('\n\n'):typeof v==='object'?Object.values(v).map(ncS).filter(Boolean).join('\n'):String(v).trim();
function ncPickKey(o,...keys){if(!o||typeof o!=='object')return '';for(const k of keys){if(o[k]!=null&&ncS(o[k])!=='')return ncS(o[k])}return ''}
function ncArr(o,...keys){if(!o||typeof o!=='object')return [];for(const k of keys){const v=o[k];if(Array.isArray(v))return v;if(v&&typeof v==='object')return Object.entries(v).map(([name,x])=>typeof x==='object'&&x?{name,title:name,...x}:{name,title:name,text:x})}return []}
function ncTextHtml(t){return String(t||'').split(/\n{2,}|\r\n\r\n/).map(p=>p.trim()).filter(Boolean).map(p=>'<p>'+esc(p).replace(/\n/g,'<br>')+'</p>').join('')}
function ncNow(){return new Date().toISOString()}
/* простой формат (ChatGPT) → части книги NOCTURNE */
function ncBookFromAI(o){
 const root=o.book&&typeof o.book==='object'&&!Array.isArray(o.book)?{...o,...o.book}:o;
 const title=ncPickKey(root,'title','name','название','книга')||'Книга из нейросети';
 const uni=root.universe??root.world??root['вселенная']??root['мир'];
 const universe=uni?(typeof uni==='string'?{name:uni.trim()}:{name:ncPickKey(uni,'name','title','название'),description:ncPickKey(uni,'description','about','описание'),lore:ncArr(uni,'lore','лор','articles','статьи'),timeline:ncArr(uni,'timeline','хронология','events','события')}):null;
 const chars=ncArr(root,'characters','персонажи','герои','heroes','cast').map(c=>typeof c==='string'?{name:c}:c).map(c=>({id:uid(),image:'',name:ncPickKey(c,'name','имя','title'),role:[ncPickKey(c,'role','роль'),ncPickKey(c,'description','описание','appearance','внешность')].filter(Boolean).join('. '),want:ncPickKey(c,'want','wants','goal','хочет','цель','желание'),fear:ncPickKey(c,'fear','fears','боится','страх'),secret:ncPickKey(c,'secret','secrets','тайна','секрет'),arc:ncPickKey(c,'arc','арка','развитие'),relations:ncPickKey(c,'relations','relationships','связи','отношения')})).filter(c=>c.name);
 const chapters=ncArr(root,'chapters','главы','plan','план').map((c,i)=>typeof c==='string'?{title:c}:c).map((c,i)=>{const text=ncPickKey(c,'text','текст','content','prose','body');const t=ncPickKey(c,'title','name','название')||('Глава '+(i+1));return {id:uid(),title:t,summary:ncPickKey(c,'summary','plan','план','кратко','описание','description'),goal:ncPickKey(c,'goal','цель','change','итог'),rich:text?ncTextHtml(text):'',plain:text||'',modifiedAt:ncNow()}});
 const lore=ncArr(root,'lore','лор','articles','статьи','world_lore').map(l=>typeof l==='string'?{title:l}:l).map(l=>({id:uid(),title:ncPickKey(l,'title','name','название'),category:ncPickKey(l,'category','section','раздел','категория'),subtitle:ncPickKey(l,'subtitle','epigraph','подзаголовок','эпиграф'),image:'',body:ncPickKey(l,'text','body','content','текст','описание','description'),images:[],links:[]})).filter(l=>l.title);
 const threads=ncArr(root,'threads','линии','plotlines','storylines','mysteries','тайны').map(t=>typeof t==='string'?{name:t}:t).map(t=>{const st=ncPickKey(t,'status','статус');return {id:uid(),name:ncPickKey(t,'name','title','название'),kind:ncPickKey(t,'kind','type','тип'),question:ncPickKey(t,'question','promise','вопрос','обещание'),payoff:ncPickKey(t,'payoff','answer','resolution','раскрытие','ответ'),status:['Открыта','В разработке','Закрыта'].includes(st)?st:'Открыта'}}).filter(t=>t.name);
 const findChar=n=>{const k=String(n||'').trim().toLocaleLowerCase('ru');return k?chars.find(c=>c.name.toLocaleLowerCase('ru')===k||c.name.toLocaleLowerCase('ru').split(/\s+/)[0]===k):null};
 const findThread=n=>{const k=String(n||'').trim().toLocaleLowerCase('ru');return k?threads.find(t=>t.name.toLocaleLowerCase('ru')===k):null};
 const timeline=ncArr(root,'timeline','хронология','events','события').map(e=>typeof e==='string'?{title:e}:e).map(e=>({id:uid(),date:ncPickKey(e,'date','when','дата','когда'),title:ncPickKey(e,'title','event','name','событие','название'),detail:ncPickKey(e,'detail','details','description','что произошло','описание'),revealBookId:'',revealChapterId:'',revealSceneId:'',revealNote:ncPickKey(e,'reveal','reader','читатель узнаёт'),characterId:findChar(ncPickKey(e,'character','who','персонаж','кто'))?.id||'',threadId:findThread(ncPickKey(e,'thread','line','линия'))?.id||''})).filter(e=>e.title);
 const cards=ncArr(root,'cards','карточки','notes','заметки','details','детали').map(c=>typeof c==='string'?{text:c}:c).map(c=>({id:uid(),kind:ncPickKey(c,'kind','category','type','раздел','тип')||'Детали',title:ncPickKey(c,'title','name','название')||ncPickKey(c,'text','body','текст').slice(0,40),body:ncPickKey(c,'text','body','content','текст','описание')})).filter(c=>c.title||c.body);
 const ideas=ncArr(root,'ideas','идеи','sparks').map(x=>typeof x==='string'?x:ncPickKey(x,'text','idea','идея')).filter(Boolean).map(text=>({text}));
 const rels=[],roles=[];
 for(const r of ncArr(root,'relationships','relations','отношения','связи')){
  const a=findChar(ncPickKey(r,'from','who','кто','a')),b=findChar(ncPickKey(r,'to','whom','кому','кого','b'));if(!a||!b||a===b)continue;
  const type=ncPickKey(r,'type','kind','feeling','role','тип','чувство','роль'),detail=ncPickKey(r,'detail','details','description','описание');
  const base={id:uid(),fromId:a.id,toId:b.id,detail,secret:ncPickKey(r,'secret','тайна'),chapterId:'',endChapterId:'',direction:'forward'};
  if(ROLE_KINDS.includes(type))roles.push({...base,type});
  else if(REL_KINDS.includes(type))rels.push({...base,type,intensity:String(Math.min(5,Math.max(1,Number(ncPickKey(r,'intensity','strength','сила'))||3)))});
  else rels.push({...base,type:'Нейтрально',intensity:'3',detail:[type,detail].filter(Boolean).join(': ')});
 }
 return {kind:'ai',title,universe,meta:{genre:ncPickKey(root,'genre','жанр','subtitle'),premise:ncPickKey(root,'premise','logline','synopsis','завязка','логлайн','о чём'),theme:ncPickKey(root,'theme','тема'),whyWrite:ncPickKey(root,'why','whyWrite','зачем','зачем я пишу')},parts:{characters:chars,chapters,lore,threads,timeline,cards,ideas,relationships:rels,statusLinks:roles}};
}
function ncBookFromExport(o){
 const b=JSON.parse(JSON.stringify(o.book));const u=o.universe&&typeof o.universe==='object'?o.universe:null;
 return {kind:'export',title:b.title||'Книга',universe:u?{name:u.name||'',description:u.description||'',full:u}:null,book:b,ideas:(o.ideas||[]).filter(x=>x&&x.text),parts:{characters:b.characters||[],chapters:b.chapters||[],lore:b.lore||[],threads:b.threads||[],timeline:b.timeline||[],cards:b.notesCards||[],ideas:o.ideas||[],relationships:b.relationships||[],statusLinks:b.statusLinks||[],notesBoard:b.notesBoard||[]}};
}
function ncBookRead(text){const o=ncBookParseText(text);if(o&&o.nocturne==='book'&&o.book&&typeof o.book==='object'&&Array.isArray(o.book.chapters)&&o.book.id)return ncBookFromExport(o);return ncBookFromAI(o)}
const NC_PART_LABEL=[['chapters','Главы',['глава','главы','глав']],['characters','Персонажи',['персонаж','персонажа','персонажей']],['lore','Статьи лора',['статья','статьи','статей']],['threads','Линии и тайны',['линия','линии','линий']],['timeline','События хронологии',['событие','события','событий']],['cards','Карточки',['карточка','карточки','карточек']],['relationships','Чувства между героями',['связь','связи','связей']],['statusLinks','Роли и статусы',['связь','связи','связей']],['ideas','Идеи',['идея','идеи','идей']],['notesBoard','Образы вдохновения',['образ','образа','образов']]];
/* ---------- окно импорта ---------- */
function ncBookImpClose(){document.querySelector('#ncBookImpVeil')?.remove()}
function ncBookImpOpen(prefill){
 ncBookImpClose();ncLibMenuClose();
 const v=document.createElement('div');v.id='ncBookImpVeil';v.className='nc-ask-veil';
 v.innerHTML=`<div class="nc-ask nc-bookimp" role="dialog" aria-modal="true" aria-labelledby="ncBookImpTitle"><h3 id="ncBookImpTitle">Импорт книги</h3><p class="mini-help">Файл книги NOCTURNE (<b>.nocturne-book.json</b>) или ответ нейросети — ChatGPT, Claude или другой. Импорт создаёт новую книгу или дополняет выбранную — ничего не удаляет.</p><div class="nc-bookimp-step" data-step="src"><div class="nc-bookimp-src"><button type="button" class="btn gold" data-nc-bi="file">⇧ Выбрать файл…</button><button type="button" class="btn" data-nc-bi="prompt" title="Скопировать инструкцию для нейросети: она соберёт заметки о книге в файл для NOCTURNE">✦ Промпт для нейросети</button></div><label for="ncBookImpText">или вставь сюда ответ нейросети</label><textarea id="ncBookImpText" rows="9" spellcheck="false" placeholder="{ &quot;title&quot;: &quot;…&quot;, &quot;characters&quot;: [ … ] }"></textarea><div class="nc-bookimp-err" role="alert" hidden></div><div class="nc-ask-foot"><button type="button" class="btn plain" data-nc-bi="cancel">Отмена</button><button type="button" class="btn gold" data-nc-bi="read">Посмотреть, что внутри</button></div><input type="file" id="ncBookImpFile" accept=".json,.txt,.md,application/json,text/plain" hidden></div><div class="nc-bookimp-step" data-step="preview" hidden></div></div>`;
 document.body.appendChild(v);
 const ta=v.querySelector('#ncBookImpText');if(prefill)ta.value=prefill;setTimeout(()=>ta.focus(),30);
}
function ncBookImpError(msg){const e=document.querySelector('#ncBookImpVeil .nc-bookimp-err');if(e){e.textContent=msg;e.hidden=!msg}}
var ncBookImpData=null;
function ncBookImpPreview(d){
 ncBookImpData=d;const v=document.querySelector('#ncBookImpVeil');if(!v)return;
 const src=v.querySelector('[data-step="src"]'),pv=v.querySelector('[data-step="preview"]');
 const rows=NC_PART_LABEL.map(([k,label,forms])=>{const n=(d.parts[k]||[]).length;if(!n)return '';const withText=k==='chapters'?(d.parts.chapters||[]).filter(c=>String(c.plain||c.rich||'').trim()).length:0;return `<label class="nc-bookimp-part"><input type="checkbox" data-nc-part="${k}" checked><span><b>${label}</b> · ${n} ${ruForm(n,forms)}${withText?` <small>(с текстом: ${withText})</small>`:''}</span></label>`}).join('');
 const uName=d.universe?.name||'';const same=uName?state.worlds.find(w=>w.name.trim().toLocaleLowerCase('ru')===uName.trim().toLocaleLowerCase('ru')):null;
 const wopts=[...(uName&&!same?[[`new`,`Новая вселенная «${uName}»${d.kind==='export'&&d.universe?.full?' — с её лором и хронологией':''}`]]:[]),...state.worlds.map(w=>[w.id,'Вселенная «'+w.name+'»']),['','Отдельные истории (без вселенной)']];
 const wsel=same?same.id:(uName?'new':'');
 const meta=d.kind==='export'?[d.book.genre,d.book.premise]:[d.meta.genre,d.meta.premise];
 pv.innerHTML=`<div class="nc-bookimp-head"><div class="cap">${d.kind==='export'?'Книга NOCTURNE':'Книга из нейросети'}</div><div class="nc-bookimp-title">${esc(d.title)}</div>${meta.filter(Boolean).length?`<p class="mini-help">${esc(meta.filter(Boolean).join(' · ').slice(0,260))}</p>`:''}</div>${rows?`<div class="nc-bookimp-parts">${rows}</div>`:'<p class="mini-help">В файле только название и описание книги.</p>'}<div class="nc-bookimp-where"><label for="ncBookImpMode">Куда</label><select id="ncBookImpMode">${ncBookImpSame(d)?`<option value="replace" selected>Обновить книгу «${esc(ncBookImpSame(d).title)}» этой версией</option>`:''}<option value="new">Новая книга «${esc(d.title)}»</option>${state.books.map(b=>`<option value="${esc(b.id)}">Дополнить книгу «${esc(b.title)}»</option>`).join('')}</select><label for="ncBookImpWorld" data-nc-bi-wlabel>Вселенная</label><select id="ncBookImpWorld">${wopts.map(([val,t])=>`<option value="${esc(val)}" ${val===wsel?'selected':''}>${esc(t)}</option>`).join('')}</select></div><p class="mini-help nc-bookimp-merge" hidden>Дополнение ничего не стирает: новые герои, главы и статьи добавятся, а у совпадающих по имени заполнятся только пустые поля.</p><p class="mini-help nc-bookimp-replace" hidden>Книга заменится версией из файла целиком — главы, герои, лор, карточки. Нынешняя версия уйдёт в корзину внизу библиотеки, её можно вернуть.</p><div class="nc-ask-foot"><button type="button" class="btn plain" data-nc-bi="back">Назад</button><button type="button" class="btn gold" data-nc-bi="go">Импортировать</button></div>`;
 src.hidden=true;pv.hidden=false;ncBookImpModeSync();pv.querySelector('[data-nc-bi="go"]').focus();
}
function ncBookImpModeSync(){const v=document.querySelector('#ncBookImpVeil');if(!v)return;const m=v.querySelector('#ncBookImpMode')?.value||'new';const isNew=m==='new',isRep=m==='replace';v.querySelector('#ncBookImpWorld').hidden=!isNew;v.querySelector('[data-nc-bi-wlabel]').hidden=!isNew;v.querySelector('.nc-bookimp-merge').hidden=isNew||isRep;const r=v.querySelector('.nc-bookimp-replace');if(r)r.hidden=!isRep;const parts=v.querySelector('.nc-bookimp-parts');if(parts)parts.style.display=isRep?'none':''}
function ncBookTotals(b){renderCountCache=new Map();return {characters:totalOf(b,'characters'),words:totalOf(b,'words'),nospace:totalOf(b,'nospace')}}
function ncBookImpApply(){
 const d=ncBookImpData,v=document.querySelector('#ncBookImpVeil');if(!d||!v)return;
 const take=k=>!!v.querySelector(`[data-nc-part="${k}"]`)?.checked;
 const mode=v.querySelector('#ncBookImpMode').value,worldSel=v.querySelector('#ncBookImpWorld').value;
 if(mode==='replace'){ncBookImpReplace(d);return}
 const P=k=>take(k)?JSON.parse(JSON.stringify(d.parts[k]||[])):[];
 let target,created=false,worldId='';
 if(mode==='new'){
  if(worldSel==='new'){const u=d.universe||{};const full=d.kind==='export'&&u.full?JSON.parse(JSON.stringify(u.full)):null;const w=full?{...full,id:uid()}:{id:uid(),name:u.name||'Новая вселенная',description:u.description||'',image:'',lore:[],timeline:[],characters:[],notesBoard:[]};
   if(!full&&d.kind==='ai'){w.lore=(u.lore||[]).map(l=>typeof l==='string'?{title:l}:l).map(l=>({id:uid(),title:ncPickKey(l,'title','name','название'),category:ncPickKey(l,'category','раздел'),subtitle:ncPickKey(l,'subtitle'),image:'',body:ncPickKey(l,'text','body','content','текст','описание'),images:[],links:[]})).filter(l=>l.title);w.timeline=(u.timeline||[]).map(e=>typeof e==='string'?{title:e}:e).map(e=>({id:uid(),date:ncPickKey(e,'date','дата'),title:ncPickKey(e,'title','event','событие'),detail:ncPickKey(e,'detail','description','описание'),bookId:''})).filter(e=>e.title)}
   state.worlds.push(w);worldId=w.id}
  else worldId=worldSel&&ncWorldById(worldSel)?worldSel:'';
  if(d.kind==='export'){
   target=JSON.parse(JSON.stringify(d.book));target.id=uid();target.worldId=worldId;
   for(const k of ['characters','chapters','lore','threads','timeline','relationships','statusLinks','notesBoard'])if(!take(k))target[k]=[];
   if(!take('cards'))target.notesCards=[];
   if(!take('characters')){target.relationships=[];target.statusLinks=[]}
   target.lastChapterId=target.chapters.some(c=>c.id===target.lastChapterId)?target.lastChapterId:(target.chapters[0]?.id||'');
  }else{
   target={id:uid(),title:d.title,worldId,genre:d.meta.genre,premise:d.meta.premise,theme:d.meta.theme,cover:'',scenes:[],chapters:P('chapters'),characters:P('characters'),locations:[],threads:P('threads'),notesBoard:[],lore:P('lore'),timeline:P('timeline'),notes:'',notesCards:P('cards'),relationships:P('relationships'),statusLinks:P('statusLinks'),atmosphereTheme:state.libraryTheme||'amber',atmospherePlaylistId:'',featuredInspirationIds:[],whyWrite:d.meta.whyWrite||'',returnNote:'',lastWrite:null,chapterDocumentVersion:1};
   target.lastChapterId=target.chapters[0]?.id||'';
   if(take('characters')===false){target.relationships=[];target.statusLinks=[]}
  }
  target.chapterDocumentVersion=1;state.books.push(target);created=true;
 }else{
  target=ncBookById(mode);if(!target){ncBookImpError('Книга не найдена');return}
  const before=ncBookTotals(target),low=x=>String(x||'').trim().toLocaleLowerCase('ru');
  const merge=(arr,items,key,fields)=>{let add=0,upd=0;for(const it of items){const ex=arr.find(x=>low(x[key])&&low(x[key])===low(it[key]));if(ex){let ch=false;for(const f of fields){if(!String(ex[f]||'').trim()&&String(it[f]||'').trim()){ex[f]=it[f];ch=true}}if(ch)upd++}else{arr.push(it);add++}}return [add,upd]};
  target.characters??=[];target.chapters??=[];target.lore??=[];target.threads??=[];target.timeline??=[];target.notesCards??=[];target.relationships??=[];target.statusLinks??=[];
  const reid=(arr,list)=>{const ids=new Set(arr.map(x=>x.id));for(const it of list)if(!it.id||ids.has(it.id))it.id=uid();return list};
  // герои: id из файла ↔ id в книге, чтобы связи легли на тех же людей
  const fileChars=P('characters'),idMap=new Map(),haveIds=new Set(target.characters.map(x=>x.id));
  for(const c of fileChars){const ex=target.characters.find(x=>low(x.name)===low(c.name));if(ex)idMap.set(c.id,ex.id);else{const nid=haveIds.has(c.id)?uid():c.id;idMap.set(c.id,nid);c.id=nid}}
  merge(target.characters,fileChars,'name',['role','want','fear','secret','arc','relations','image']);
  for(const c of reid(target.chapters,P('chapters'))){const ex=target.chapters.find(x=>low(x.title)===low(c.title));if(ex){for(const f of ['summary','goal'])if(!String(ex[f]||'').trim()&&String(c[f]||'').trim())ex[f]=c[f];if(!String(ex.plain||'').trim()&&String(c.plain||'').trim()){ex.plain=c.plain;ex.rich=c.rich;ex.modifiedAt=ncNow()}}else target.chapters.push(c)}
  merge(target.lore,reid(target.lore,P('lore')),'title',['category','subtitle','body']);
  merge(target.threads,reid(target.threads,P('threads')),'name',['kind','question','payoff']);
  for(const e of reid(target.timeline,P('timeline'))){if(!target.timeline.some(x=>low(x.title)===low(e.title)&&low(x.date)===low(e.date))){e.characterId=idMap.get(e.characterId)||e.characterId;target.timeline.push(e)}}
  merge(target.notesCards,reid(target.notesCards,P('cards')),'title',['kind','body']);
  for(const k of ['relationships','statusLinks'])for(const r of P(k)){r.fromId=idMap.get(r.fromId)||r.fromId;r.toId=idMap.get(r.toId)||r.toId;if(!target[k].some(x=>x.fromId===r.fromId&&x.toId===r.toId&&x.type===r.type))target[k].push(r)}
  chapterize(target);
  // добавленный текст не считается написанным сегодня
  const after=ncBookTotals(target),row=state.writingDays?.[dateLocal()];
  if(row?.baseline?.[target.id])for(const u of ['characters','words','nospace'])row.baseline[target.id][u]=(Number(row.baseline[target.id][u])||0)+Math.max(0,after[u]-before[u]);
 }
 if(take('ideas')){const have=new Set((state.quickIdeas||[]).filter(x=>x.bookId===target.id).map(x=>low2(x.text)));for(const it of d.parts.ideas||[]){const t=String(it.text||it||'').trim();if(t&&!have.has(low2(t))){state.quickIdeas.push({id:uid(),text:t,bookId:target.id,createdAt:ncNow()});have.add(low2(t))}}}
 ncBookImpClose();booksByWorldDuringRender=null;
 state.activeBookId=target.id;if(target.worldId)state.activeWorldId=target.worldId;state.theme=target.atmosphereTheme||state.libraryTheme||'amber';
 persist();setTab('atmosphere');
 notify(created?'Книга «'+target.title+'» добавлена в библиотеку':'Книга «'+target.title+'» дополнена');
}
function low2(x){return String(x||'').trim().toLocaleLowerCase('ru')}
function ncBookPrompt(){
 return `Собери всё про мою книгу — из нашего разговора и из файлов и заметок, которые есть в этом чате, — в файл для программы NOCTURNE.

Правила:
— Бери только то, что действительно есть в разговоре, файлах и заметках. Ничего не выдумывай и не дописывай от себя. Если чего-то нет — просто не включай это поле.
— Заметки могут быть разрозненными и в любом виде: разложи их по разделам формата ниже — герои, главы, лор, сюжетные линии, хронология, связи, карточки. Если что-то никуда не подходит, положи это в "ideas".
— Текст глав, если он есть, переноси дословно, без правок и сокращений. Абзацы разделяй пустой строкой.
— Сохрани результат как файл «книга.nocturne.json» для скачивания. Если не можешь создать файл — выведи всё одним блоком кода json.
— Это должен быть корректный JSON: двойные кавычки, без комментариев и без лишних запятых.
— Если всё не помещается в один ответ, раздели на части с одинаковым "title": в первой — книга и герои, дальше — главы. Я загружу их по очереди.

Формат (все поля, кроме "title", необязательны):
{
  "nocturne": "ai-book",
  "title": "Название книги",
  "genre": "жанр",
  "premise": "завязка и сердце истории",
  "theme": "основная тема",
  "why": "зачем я пишу эту книгу",
  "universe": "название вселенной, если книга из цикла",
  "characters": [{"name": "Имя", "role": "кто это в истории", "want": "чего хочет", "fear": "чего боится", "secret": "какую тайну хранит", "arc": "как меняется", "relations": "связи с другими"}],
  "chapters": [{"title": "Глава 1. Название", "summary": "план главы", "goal": "что меняется к концу главы", "text": "текст главы, если он есть"}],
  "lore": [{"title": "Название статьи", "category": "Магия / История / Места / Кланы …", "text": "текст статьи"}],
  "threads": [{"name": "сюжетная линия или тайна", "kind": "главная тайна / любовная / …", "question": "что обещано читателю", "payoff": "где и как раскрывается"}],
  "timeline": [{"date": "дата или эпоха", "title": "событие", "detail": "что произошло на самом деле", "character": "имя героя", "thread": "название линии"}],
  "relationships": [{"from": "Имя", "to": "Имя", "type": "одно из: ${REL_KINDS.join(', ')} — или роль: ${ROLE_KINDS.join(', ')}", "detail": "пояснение"}],
  "cards": [{"kind": "Места / Предметы / Детали / Фразы", "title": "название", "text": "описание"}],
  "ideas": ["идея или находка", "ещё одна"]
}`;
}
async function ncBookPromptCopy(){
 const p=ncBookPrompt();let ok=false;try{await navigator.clipboard.writeText(p);ok=true}catch(e){}
 if(ok){notify('Промпт скопирован — вставь его в чат с нейросетью, где лежат заметки о книге');return}
 const ta=document.querySelector('#ncBookImpText');if(ta){ta.value=p;ta.focus();ta.select();ncBookImpError('Скопируй этот текст (⌘C / Ctrl+C) и вставь в чат с нейросетью. Потом очисти поле и вставь сюда его ответ.')}
}
document.addEventListener('click',async e=>{
 const t=e.target;if(!t||!t.closest)return;
 if(t.closest('[data-nc-bookimp]')){e.preventDefault();e.stopPropagation();ncBookImpOpen();return}
 const b=t.closest('#ncBookImpVeil [data-nc-bi]');if(!b){if(t.id==='ncBookImpVeil'){/* щелчок мимо окна ничего не закрывает */}return}
 e.preventDefault();e.stopPropagation();const a=b.dataset.ncBi,v=document.querySelector('#ncBookImpVeil');
 if(a==='cancel')ncBookImpClose();
 else if(a==='file')v.querySelector('#ncBookImpFile').click();
 else if(a==='prompt')ncBookPromptCopy();
 else if(a==='read'){try{ncBookImpError('');ncBookImpPreview(ncBookRead(v.querySelector('#ncBookImpText').value))}catch(err){ncBookImpError(err.message)}}
 else if(a==='back'){v.querySelector('[data-step="preview"]').hidden=true;v.querySelector('[data-step="src"]').hidden=false}
 else if(a==='go'){try{ncBookImpApply()}catch(err){ncBookImpError('Не получилось: '+err.message);console.error(err)}}
},true);
document.addEventListener('change',async e=>{
 const t=e.target;if(!t)return;
 if(t.id==='ncBookImpMode'){ncBookImpModeSync();return}
 if(t.id==='ncBookImpFile'){const f=t.files&&t.files[0];t.value='';if(!f)return;if(f.size>60*1024*1024){ncBookImpError('Файл слишком большой (больше 60 МБ)');return}try{const txt=await f.text();ncBookImpError('');ncBookImpPreview(ncBookRead(txt))}catch(err){ncBookImpError(err.message)}}
},true);
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('#ncBookImpVeil')){e.preventDefault();e.stopImmediatePropagation();ncBookImpClose()}},true);

/* ——— RC3.8.15: раздел «Арки и хронология» ———
   «Сюжет по схеме»: книга ложится на готовый каркас (три акта, путешествие героя, Save the Cat!,
   Пропп и др.), главы привязываются к этапам, видно темп. Данные — b.plotArcs, b.plotArcActive.
   «Хронология»: события книги (те же, что в «Нитях времени», b.timeline) по датам календаря книги,
   общие, по героям и по веткам, сочетаются фильтрами; порядок «как было» и «как узнаёт читатель».
   У событий появляются необязательные поля when{y,m,d}, people[], threads[], chapterId —
   «Нити времени» их не замечают и работают как раньше. */
